{
  "name": "Basmati Pro - AI Attendance Analytics",
  "description": "A high-end employee attendance analysis system with AI-powered insights, smart token management, and advanced shift classification logic.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface PunchDetail {
  time: string;
  period: string;
  is_duplicate: boolean;
  raw_datetime: Date;
}

export interface ShiftReport {
  employee_id: string | number;
  employee_name: string;
  shift_date: string;
  punches_details: PunchDetail[];
  punches_count: number;
  status: 'مكتملة' | 'ناقصة';
}

export interface EmployeeSummary {
  id: string | number;
  name: string;
  shifts: ShiftReport[];
  totalPunches: number;
  completionRate: number;
  performanceScore: number;
  isEligible: boolean;
}

export interface TimePeriod {
  start: string; // HH:mm format
  end: string;   // HH:mm format
}

export interface Rules {
  REQUIRED_PUNCHES_PER_SHIFT: number;
  MAX_HOURS_BETWEEN_PUNCHES: number;
  TIME_PERIODS: {
    [key: string]: TimePeriod;
  };
}

import { Rules } from './types';

export const ATTENDANCE_RULES: Rules = {
  REQUIRED_PUNCHES_PER_SHIFT: 5,
  MAX_HOURS_BETWEEN_PUNCHES: 12,
  TIME_PERIODS: {
    "فترة الصباح": { start: "07:30", end: "08:10" },
    "بصمة وسطية": { start: "12:00", end: "15:59" },
    "بصمة مسائية": { start: "18:00", end: "21:59" },
    "بصمة ليلية": { start: "22:00", end: "03:00" },
    "فترة الخروج": { start: "07:49", end: "09:00" },
  }
};

export const COLORS = {
  primary: '#4f46e5',
  success: '#10b981',
  danger: '#ef4444',
  warning: '#f59e0b',
  info: '#3b82f6',
};

import { ATTENDANCE_RULES } from '../constants';
import { ShiftReport, PunchDetail, EmployeeSummary } from '../types';

const parseTimeToMinutes = (t: string) => {
  const [h, m] = t.split(':').map(Number);
  return h * 60 + m;
};

export const classifyPunch = (
  timeStr: string, 
  isFirst: boolean, 
  isLast: boolean
): string | null => {
  const t = parseTimeToMinutes(timeStr);
  const periods = ATTENDANCE_RULES.TIME_PERIODS;

  // Rule 1: Exit Punch (Priority 1)
  const exitStart = parseTimeToMinutes(periods["فترة الخروج"].start);
  const exitEnd = parseTimeToMinutes(periods["فترة الخروج"].end);
  if (isLast && t >= exitStart && t <= exitEnd) {
    return "بصمة خروج";
  }

  // Rule 2: Morning Punch (Priority 2)
  const mornStart = parseTimeToMinutes(periods["فترة الصباح"].start);
  const mornEnd = parseTimeToMinutes(periods["فترة الصباح"].end);
  if (isFirst && t >= mornStart && t <= mornEnd) {
    return "دخول صباحي";
  }

  // Rule 3: Night Punch (Crosses midnight)
  const nightStart = parseTimeToMinutes(periods["بصمة ليلية"].start);
  const nightEnd = parseTimeToMinutes(periods["بصمة ليلية"].end);
  // After 10 PM or Before 3 AM
  if (t >= nightStart || t <= nightEnd) {
    // Extra safety: ensure it's not actually morning
    if (t > mornEnd || t < 240) { // 240 is 4:00 AM
      return "بصمة ليلية";
    }
  }

  // Rule 4: Middle and Evening
  const midStart = parseTimeToMinutes(periods["بصمة وسطية"].start);
  const midEnd = parseTimeToMinutes(periods["بصمة وسطية"].end);
  if (t >= midStart && t <= midEnd) return "بصمة وسطية";

  const eveStart = parseTimeToMinutes(periods["بصمة مسائية"].start);
  const eveEnd = parseTimeToMinutes(periods["بصمة مسائية"].end);
  if (t >= eveStart && t <= eveEnd) return "بصمة مسائية";

  return null;
};

export const processExcelData = (rawData: any[]): EmployeeSummary[] => {
  if (!rawData || rawData.length === 0) return [];

  // Group by Employee
  const employeesMap: Map<string, any[]> = new Map();
  rawData.forEach(row => {
    const id = String(row['AC-No'] || row[1]);
    if (!employeesMap.has(id)) employeesMap.set(id, []);
    employeesMap.get(id)?.push(row);
  });

  const allSummaries: EmployeeSummary[] = [];

  employeesMap.forEach((punches, id) => {
    const name = punches[0]['Name'] || punches[0][2] || 'Unknown';

    // Sort all punches by datetime
    const sortedPunches = punches.map(p => {
      const datePart = p['Date'] || p[3];
      const timePart = String(p['Time'] || p[4]);

      // Handle Excel date formats or strings
      let dt: Date;
      if (typeof datePart === 'number') {
        // Excel serial date
        dt = new Date((datePart - 25569) * 86400 * 1000);
      } else {
        dt = new Date(datePart);
      }

      // Add time
      const [h, m] = timePart.split(':').map(Number);
      dt.setHours(h || 0, m || 0, 0, 0);

      return { id, name, dt };
    }).sort((a, b) => a.dt.getTime() - b.dt.getTime());

    // Split into shifts
    const shifts: ShiftReport[] = [];
    let currentShiftPunches: Date[] = [];

    for (let i = 0; i < sortedPunches.length; i++) {
      if (i > 0) {
        const diffHours = (sortedPunches[i].dt.getTime() - sortedPunches[i-1].dt.getTime()) / (1000 * 60 * 60);
        if (diffHours > ATTENDANCE_RULES.MAX_HOURS_BETWEEN_PUNCHES) {
          shifts.push(createShiftReport(id, name, currentShiftPunches));
          currentShiftPunches = [];
        }
      }
      currentShiftPunches.push(sortedPunches[i].dt);
    }
    if (currentShiftPunches.length > 0) {
      shifts.push(createShiftReport(id, name, currentShiftPunches));
    }

    // Aggregate Summary
    const totalValidPunches = shifts.reduce((sum, s) => sum + s.punches_count, 0);
    const completedShifts = shifts.filter(s => s.status === 'مكتملة').length;
    const completionRate = shifts.length > 0 ? Math.round((completedShifts / shifts.length) * 100) : 0;
    const totalRequired = shifts.length * ATTENDANCE_RULES.REQUIRED_PUNCHES_PER_SHIFT;
    const performanceScore = totalRequired > 0 ? Math.round((totalValidPunches / totalRequired) * 100) : 0;

    allSummaries.push({
      id,
      name,
      shifts,
      totalPunches: totalValidPunches,
      completionRate,
      performanceScore,
      isEligible: completedShifts === shifts.length && shifts.length > 0
    });
  });

  return allSummaries;
};

function createShiftReport(id: string, name: string, punches: Date[]): ShiftReport {
  const shiftDate = punches[0].toLocaleDateString('en-CA');
  const details: PunchDetail[] = [];
  const seenPeriods = new Set<string>();

  punches.forEach((p, idx) => {
    const timeStr = p.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
    const period = classifyPunch(timeStr, idx === 0, idx === punches.length - 1);
    const finalPeriod = period || "غير مصنفة";

    let isDuplicate = seenPeriods.has(finalPeriod) && finalPeriod !== "غير مصنفة";
    if (finalPeriod === "بصمة خروج") isDuplicate = false; // Exit can never be duplicate per requirements

    details.push({
      time: timeStr,
      period: finalPeriod,
      is_duplicate: isDuplicate,
      raw_datetime: p
    });

    if (!isDuplicate && finalPeriod !== "غير مصنفة") {
      seenPeriods.add(finalPeriod);
    }
  });

  const validCount = seenPeriods.size;

  return {
    employee_id: id,
    employee_name: name,
    shift_date: shiftDate,
    punches_details: details,
    punches_count: validCount,
    status: validCount >= ATTENDANCE_RULES.REQUIRED_PUNCHES_PER_SHIFT ? 'مكتملة' : 'ناقصة'
  };
}

import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary } from "../types";

// Token Estimation Logic
const estimateTokens = (text: string) => Math.ceil(text.length / 4);
const MAX_CONTEXT_TOKENS = 15000; // Safe buffer for Gemini 3 Flash

export const analyzeEmployeeAttendanceAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Create a structured, dense data string to save tokens
  const shiftSummary = employee.shifts.map(s => 
    `${s.shift_date}: ${s.status} (${s.punches_count}/${5} بصمات)`
  ).join(', ');

  const prompt = `
    حلل أداء الحضور للموظف التالي وقدم توصيات مختصرة جداً:
    الاسم: ${employee.name}
    الرقم: ${employee.id}
    عدد الأيام: ${employee.shifts.length}
    نسبة الإكمال: ${employee.completionRate}%
    درجة الأداء: ${employee.performanceScore}%
    بيانات الورديات: ${shiftSummary}

    المطلوب:
    1. نقاط القوة.
    2. الثغرات المتكررة (مثل فقدان بصمة الصباح أو الوسطية).
    3. توصية إدارية (تحفيز، تنبيه، أو تدريب).
    اجعل الإجابة باللغة العربية بأسلوب مهني ومختصر.
  `;

  // Smart Scoping: If the data is too large, we truncate the shifts list
  let scopedPrompt = prompt;
  if (estimateTokens(scopedPrompt) > MAX_CONTEXT_TOKENS) {
    const truncatedShifts = employee.shifts.slice(0, 20).map(s => s.shift_date).join(', ');
    scopedPrompt = `(بيانات مقتطعة بسبب الحجم) ... ${prompt.replace(shiftSummary, truncatedShifts)}`;
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: scopedPrompt,
      config: {
        temperature: 0.7,
        topP: 0.95,
        thinkingConfig: { thinkingBudget: 0 } // Low latency
      }
    });

    return response.text || "لم يتمكن الذكاء الاصطناعي من توليد تحليل حالياً.";
  } catch (error) {
    console.error("AI Analysis Error:", error);
    return "حدث خطأ أثناء الاتصال بالذكاء الاصطناعي.";
  }
};

import React, { useState, useCallback, useMemo } from 'react';
import { 
  FileUp, 
  Search, 
  Users, 
  CheckCircle2, 
  Clock, 
  TrendingUp, 
  BrainCircuit, 
  X, 
  Menu,
  ChevronLeft,
  Calendar,
  AlertCircle,
  LayoutDashboard
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { analyzeEmployeeAttendanceAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport } from './types';
import { COLORS } from './constants';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [selectedEmployee, setSelectedEmployee] = useState<EmployeeSummary | null>(null);
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Stats
  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / totalShifts) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0)
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => 
      e.name.toLowerCase().includes(term) || String(e.id).includes(term)
    );
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      const data = new Uint8Array(e.target?.result as ArrayBuffer);
      // @ts-ignore (XLSX from index.html)
      const workbook = XLSX.read(data, { type: 'array' });
      const firstSheetName = workbook.SheetNames[0];
      const worksheet = workbook.Sheets[firstSheetName];
      // @ts-ignore
      const json = XLSX.utils.sheet_to_json(worksheet);

      const processed = processExcelData(json);
      setEmployees(processed);
      setIsAnalyzing(false);
    };
    reader.readAsArrayBuffer(file);
  };

  const handleAiDeepDive = async (emp: EmployeeSummary) => {
    setSelectedEmployee(emp);
    setIsAiLoading(true);
    setAiAnalysis(null);
    const analysis = await analyzeEmployeeAttendanceAI(emp);
    setAiAnalysis(analysis);
    setIsAiLoading(false);
  };

  return (
    <div className="min-h-screen flex bg-slate-50 text-slate-900">
      {/* Sidebar */}
      <aside className={`fixed inset-y-0 right-0 z-50 w-72 bg-white border-l border-slate-200 transition-transform duration-300 lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="p-6 h-full flex flex-col">
          <div className="flex items-center gap-3 mb-10">
            <div className="p-2 bg-indigo-600 rounded-xl text-white">
              <BrainCircuit size={24} />
            </div>
            <div>
              <h1 className="font-bold text-xl tracking-tight">بصمتي برو</h1>
              <p className="text-xs text-slate-500">نظام تحليل الحضور الذكي</p>
            </div>
          </div>

          <nav className="space-y-2 flex-1">
            <NavItem icon={<LayoutDashboard size={20}/>} label="لوحة التحكم" active />
            <NavItem icon={<Users size={20}/>} label="الموظفون" />
            <NavItem icon={<TrendingUp size={20}/>} label="التقارير التحليلية" />
          </nav>

          <div className="mt-auto">
            <label className="flex flex-col items-center justify-center w-full p-4 border-2 border-dashed border-slate-200 rounded-2xl cursor-pointer hover:border-indigo-400 hover:bg-indigo-50 transition-all group">
              <FileUp className="text-slate-400 group-hover:text-indigo-600 mb-2" />
              <span className="text-sm font-medium text-slate-600 group-hover:text-indigo-700">رفع ملف البيانات</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
            </label>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 lg:pr-72 min-h-screen">
        {/* Header */}
        <header className="sticky top-0 z-40 bg-white/80 backdrop-blur-md border-b border-slate-200 px-4 py-4 sm:px-8">
          <div className="max-w-7xl mx-auto flex items-center justify-between">
            <button className="lg:hidden p-2 text-slate-600" onClick={() => setIsSidebarOpen(!isSidebarOpen)}>
              {isSidebarOpen ? <X /> : <Menu />}
            </button>

            <div className="relative flex-1 max-w-md mx-4">
              <span className="absolute inset-y-0 right-0 flex items-center pr-3 pointer-events-none text-slate-400">
                <Search size={18} />
              </span>
              <input 
                type="text" 
                placeholder="ابحث عن اسم موظف أو رقم..." 
                className="w-full bg-slate-100 border-none rounded-xl pr-10 pl-4 py-2.5 focus:ring-2 focus:ring-indigo-500 text-sm"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>

            <div className="flex items-center gap-3">
               <div className="hidden sm:block text-left">
                  <p className="text-xs text-slate-400">التاريخ اليوم</p>
                  <p className="text-sm font-bold">{new Date().toLocaleDateString('ar-SA')}</p>
               </div>
            </div>
          </div>
        </header>

        <div className="p-4 sm:p-8 max-w-7xl mx-auto">
          {/* Stats Grid */}
          {stats && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
              <StatCard title="عدد الموظفين" value={stats.totalEmployees} icon={<Users className="text-indigo-600" />} color="bg-indigo-50" />
              <StatCard title="نسبة الإكتمال" value={`${stats.completionRate}%`} icon={<CheckCircle2 className="text-emerald-600" />} color="bg-emerald-50" />
              <StatCard title="إجمالي البصمات" value={stats.totalPunches} icon={<Clock className="text-amber-600" />} color="bg-amber-50" />
            </div>
          )}

          {/* Data List */}
          <div className="space-y-6">
            {isAnalyzing ? (
              <div className="flex flex-col items-center justify-center py-20 bg-white rounded-3xl border border-slate-200 shadow-sm">
                <div className="w-12 h-12 border-4 border-indigo-600/30 border-t-indigo-600 rounded-full animate-spin mb-4"></div>
                <h3 className="text-lg font-bold">جاري تحليل البيانات...</h3>
                <p className="text-slate-500 text-sm">نقوم بمعالجة الورديات وتصنيف البصمات بذكاء</p>
              </div>
            ) : filteredEmployees.length > 0 ? (
              filteredEmployees.map((emp, i) => (
                <EmployeeRow 
                  key={emp.id} 
                  employee={emp} 
                  index={i} 
                  onAiAnalysis={() => handleAiDeepDive(emp)}
                />
              ))
            ) : (
              <div className="text-center py-20 bg-white rounded-3xl border border-slate-200 border-dashed">
                <div className="inline-flex p-4 bg-slate-50 rounded-full mb-4">
                  <FileUp size={32} className="text-slate-400" />
                </div>
                <h3 className="text-xl font-bold mb-1">لا توجد بيانات متاحة</h3>
                <p className="text-slate-500 max-w-sm mx-auto">ارفع ملف إكسل يحتوي على بيانات البصمات لبدء التحليل الفوري.</p>
              </div>
            )}
          </div>
        </div>
      </main>

      {/* AI Modal */}
      {selectedEmployee && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setSelectedEmployee(null)}></div>
          <div className="relative w-full max-w-2xl bg-white rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-6 bg-indigo-600 text-white flex justify-between items-center">
              <div className="flex items-center gap-3">
                <BrainCircuit />
                <div>
                  <h3 className="font-bold text-lg">تحليل الذكاء الاصطناعي</h3>
                  <p className="text-xs text-indigo-100">{selectedEmployee.name}</p>
                </div>
              </div>
              <button onClick={() => setSelectedEmployee(null)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                <X size={20} />
              </button>
            </div>

            <div className="p-8">
              {isAiLoading ? (
                <div className="flex flex-col items-center justify-center py-10">
                  <div className="flex gap-1 mb-4">
                    <div className="w-2 h-2 bg-indigo-600 rounded-full animate-bounce"></div>
                    <div className="w-2 h-2 bg-indigo-600 rounded-full animate-bounce delay-100"></div>
                    <div className="w-2 h-2 bg-indigo-600 rounded-full animate-bounce delay-200"></div>
                  </div>
                  <p className="text-slate-500 font-medium">يقوم Gemini بتحليل أنماط الحضور...</p>
                </div>
              ) : (
                <div className="prose prose-slate max-w-none text-right whitespace-pre-line leading-relaxed">
                  {aiAnalysis}
                </div>
              )}

              <div className="mt-8 pt-6 border-t border-slate-100 flex justify-between items-center">
                <div className="flex items-center gap-2 text-xs text-slate-400">
                   <AlertCircle size={14} />
                   <span>تم استخدام نطاق التوكنات الذكي لضمان دقة التحليل.</span>
                </div>
                <button 
                  onClick={() => setSelectedEmployee(null)}
                  className="px-6 py-2 bg-slate-100 text-slate-700 rounded-xl font-bold text-sm hover:bg-slate-200 transition-colors"
                >
                  إغلاق
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// --- Sub-components ---

const NavItem: React.FC<{ icon: React.ReactNode; label: string; active?: boolean }> = ({ icon, label, active }) => (
  <button className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-medium ${active ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'text-slate-500 hover:bg-slate-100'}`}>
    {icon}
    <span>{label}</span>
  </button>
);

const StatCard: React.FC<{ title: string; value: string | number; icon: React.ReactNode; color: string }> = ({ title, value, icon, color }) => (
  <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm flex items-center justify-between">
    <div>
      <p className="text-sm text-slate-500 font-medium mb-1">{title}</p>
      <h4 className="text-2xl font-extrabold">{value}</h4>
    </div>
    <div className={`p-4 ${color} rounded-2xl`}>
      {icon}
    </div>
  </div>
);

const EmployeeRow: React.FC<{ employee: EmployeeSummary; index: number; onAiAnalysis: () => void }> = ({ employee, index, onAiAnalysis }) => {
  return (
    <div className="bg-white rounded-3xl border border-slate-200 p-6 shadow-sm hover:shadow-md transition-shadow group animate-in fade-in slide-in-from-bottom-4" style={{ animationDelay: `${index * 50}ms` }}>
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
        <div className="flex items-center gap-4">
          <div className="w-14 h-14 bg-slate-100 rounded-2xl flex items-center justify-center text-slate-400 font-bold group-hover:bg-indigo-50 group-hover:text-indigo-600 transition-colors">
            {employee.name.charAt(0)}
          </div>
          <div>
            <h3 className="text-lg font-extrabold flex items-center gap-2">
              {employee.name}
              {employee.isEligible && (
                <span className="text-[10px] bg-emerald-100 text-emerald-700 px-2 py-0.5 rounded-full">يستحق</span>
              )}
            </h3>
            <p className="text-sm text-slate-400">رقم الموظف: {employee.id}</p>
          </div>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 flex-1">
          <QuickStat label="أيام الحضور" value={`${employee.shifts.length} يوم`} />
          <QuickStat label="البصمات الصالحة" value={employee.totalPunches} />
          <QuickStat label="نسبة الإكمال" value={`${employee.completionRate}%`} status={employee.completionRate > 80 ? 'good' : 'bad'} />
          <QuickStat label="درجة الأداء" value={`${employee.performanceScore}%`} />
        </div>

        <button 
