import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary } from "../types";

// Token Estimation: ~4 characters per token is a safe average for mixed Arabic/English
const estimateTokens = (text: string) => Math.ceil(text.length / 4);
const MAX_CONTEXT_TOKENS = 25000; // Gemini 3 Flash can handle much more, but we stay conservative for speed

export const analyzeEmployeeAttendanceAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Dense data representation to save tokens
  const shiftSummary = employee.shifts.map(s => 
    `${s.shift_date}:${s.status.substring(0,1)}(${s.punches_count})`
  ).join('|');

  const prompt = `
    ديك بيانات حضور الموظف:
    الاسم: ${employee.name}
    الرقم: ${employee.id}
    الأيام: ${employee.shifts.length}
    الإكمال: ${employee.completionRate}%
    الأداء: ${employee.performanceScore}%
    البيانات: ${shiftSummary}

    المطلوب تحليل احترافي جداً:
    1. ملخص سريع للنمط العام.
    2. تحديد "البصمة المفقودة" الأكثر تكراراً (صباح، وسط، مساء، خروج).
    3. نصيحة عملية للموظف لتحسين التزامه.
    اجعل الرد بصيغة نقاط واضحة ومختصرة باللغة العربية.
  `;

  let finalPrompt = prompt;
  if (estimateTokens(finalPrompt) > MAX_CONTEXT_TOKENS) {
    // Keep only the most recent 30 shifts if data is massive
    const truncatedShifts = employee.shifts.slice(-30).map(s => `${s.shift_date}:${s.status.substring(0,1)}`).join('|');
    finalPrompt = prompt.replace(shiftSummary, `[مقتطع]...${truncatedShifts}`);
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: finalPrompt,
      config: { temperature: 0.4, topP: 0.9 }
    });
    return response.text || "لا يتوفر تحليل حالياً.";
  } catch (error) {
    return "خطأ في الاتصال بالذكاء الاصطناعي.";
  }
};

export const analyzeCompanyTrendsAI = async (employees: EmployeeSummary[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Aggregate stats for token efficiency
  const totalEmployees = employees.length;
  const avgCompletion = employees.reduce((a, b) => a + b.completionRate, 0) / totalEmployees;
  const topPerformers = employees.filter(e => e.completionRate > 90).length;
  const lowPerformers = employees.filter(e => e.completionRate < 50).length;

  const prompt = `
    تحليل تقرير حضور الشركة الإجمالي:
    عدد الموظفين: ${totalEmployees}
    متوسط نسبة الإكمال: ${avgCompletion.toFixed(1)}%
    المتميزون (>90%): ${topPerformers}
    المتعثرون (<50%): ${lowPerformers}

    قدم رؤية إدارية شاملة عن حالة الانضباط في الشركة، مع ذكر 3 توصيات لتحسين كفاءة نظام البصمة الإجمالي.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "لا يتوفر تحليل حالياً.";
  } catch (error) {
    return "فشل تحليل الاتجاهات العامة.";
  }
};

