                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>

            <button 
              onClick={getCompanyInsight}
              disabled={employees.length === 0}
              className="flex items-center gap-2 px-6 py-3.5 bg-gradient-to-r from-indigo-600 to-violet-600 text-white rounded-2xl font-bold text-sm shadow-lg shadow-indigo-100 hover:shadow-indigo-200 transition-all hover:scale-[1.02] disabled:opacity-50 disabled:scale-100"
            >
              <Sparkles size={18} />
              <span className="hidden sm:inline">تحليل ذكي للشركة</span>
