                  </h2>
                  <div className="text-indigo-100 leading-relaxed text-sm md:text-base whitespace-pre-line opacity-90">
                    {companyInsight}
                  </div>
                </div>
                <button onClick={() => setCompanyInsight(null)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                  <X size={20} />
                </button>
              </div>
            </div>
          )}

          {stats && (
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 animate-in slide-in-from-bottom-10 duration-700 delay-150">
              <StatCard title="إجمالي الموظفين" value={stats.totalEmployees} subtitle="مسجلين في النظام" icon={<Users className="text-indigo-600" />} gradient="from-indigo-50 to-indigo-100/30" />
              <StatCard title="متوسط الانضباط" value={`${stats.completionRate}%`} subtitle="نسبة إكمال الورديات" icon={<CheckCircle2 className="text-emerald-600" />} gradient="from-emerald-50 to-emerald-100/30" />
              <StatCard title="نشاط البصمات" value={stats.totalPunches} subtitle="عملية بصمة مسجلة" icon={<Clock className="text-amber-600" />} gradient="from-amber-50 to-amber-100/30" />
            </div>
          )}

          <div className="space-y-8">
            <h2 className="text-2xl font-black text-slate-800 tracking-tight">قائمة الموظفين والتحليلات التفصيلية</h2>
