              </div>
            )}
          </div>
        </div>
      </main>

      {/* AI Modal */}
      {selectedEmployee && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setSelectedEmployee(null)}></div>
          <div className="relative w-full max-w-2xl bg-white rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-8 bg-gradient-to-r from-slate-900 to-indigo-900 text-white flex justify-between items-center">
              <div className="flex items-center gap-4">
                <Sparkles size={24} className="text-indigo-300" />
                <div>
                  <h3 className="font-black text-xl">تحليل Gemini</h3>
                  <p className="text-xs text-indigo-300 font-bold uppercase">{selectedEmployee.name}</p>
                </div>
              </div>
              <button onClick={() => setSelectedEmployee(null)} className="p-3 hover:bg-white/10 rounded-full transition-colors"><X size={20} /></button>
            </div>
            <div className="p-10">
              {isAiLoading ? (
