const DetailedShiftCard: React.FC<{ shift: ShiftReport }> = ({ shift }) => {
  const isComplete = shift.status === 'مكتملة';

  // Find missing periods
  const capturedPeriods = new Set(shift.punches_details.filter(p => !p.is_duplicate && p.period !== "غير مصنفة").map(p => p.period));
  const missingPeriods = Object.keys(ATTENDANCE_RULES.TIME_PERIODS).filter(p => !capturedPeriods.has(p));

  return (
    <div className={`p-8 rounded-[2rem] bg-white border-2 transition-all duration-300 relative group overflow-hidden ${isComplete ? 'border-emerald-50 shadow-emerald-100/20' : 'border-rose-50 shadow-rose-100/20'}`}>
      <div className="flex items-center justify-between mb-8 relative z-10">
        <div className="flex items-center gap-3">
           <div className={`p-2.5 rounded-xl ${isComplete ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
              <Calendar size={18} />
           </div>
           <div>
             <h5 className="font-black text-slate-800">{shift.shift_date}</h5>
             <p className="text-[10px] text-slate-400 font-bold uppercase">{new Date(shift.shift_date).toLocaleDateString('ar-SA', { weekday: 'long' })}</p>
           </div>
        </div>
        <div className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${isComplete ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white shadow-lg shadow-rose-200'}`}>
          {shift.status}
        </div>
      </div>

      {/* Vertical Timeline */}
      <div className="relative space-y-6 before:absolute before:inset-y-0 before:right-[15px] before:w-0.5 before:bg-slate-100 before:z-0">
        {shift.punches_details.map((punch, pIdx) => (
          <div key={pIdx} className="relative pr-10 flex items-center justify-between group/punch">
             {/* Timeline Node */}
             <div className={`absolute right-0 top-1/2 -translate-y-1/2 w-8 h-8 rounded-full border-4 border-white shadow-sm z-10 flex items-center justify-center transition-transform group-hover/punch:scale-125
               ${punch.is_duplicate ? 'bg-amber-400' : punch.period === "غير مصنفة" ? 'bg-slate-200' : 'bg-indigo-600'}
             `}>
                {punch.is_duplicate ? <Clock size={12} className="text-white" /> : punch.period === "غير مصنفة" ? <Info size={12} className="text-slate-400" /> : <Fingerprint size={12} className="text-white" />}
             </div>

             <div className="flex-1 text-right">
                <div className="flex items-center justify-between">
                  <span className={`text-[11px] font-black ${punch.is_duplicate ? 'text-amber-600' : punch.period === "غير مصنفة" ? 'text-slate-400 italic' : 'text-slate-800'}`}>
                    {punch.period}
                    {punch.is_duplicate && " (مكررة)"}
                  </span>
                  <span className="text-xs font-black text-indigo-700 bg-indigo-50 px-2.5 py-1 rounded-lg">
                    {punch.time}
                  </span>
                </div>
                <p className="text-[9px] text-slate-400 mt-0.5">تسجيل بصمة رقم {pIdx + 1}</p>
             </div>
          </div>
        ))}
      </div>

      {/* Requirements Checkbox List */}
      <div className="mt-10 pt-8 border-t border-slate-50">
         <h6 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">متطلبات الوردية</h6>
         <div className="grid grid-cols-1 gap-3">
            {Object.keys(ATTENDANCE_RULES.TIME_PERIODS).map((periodName) => {
              const hasIt = capturedPeriods.has(periodName);
              return (
                <div key={periodName} className={`flex items-center justify-between p-3 rounded-xl border transition-all ${hasIt ? 'bg-emerald-50/50 border-emerald-100' : 'bg-rose-50/30 border-rose-100 border-dashed'}`}>
                   <span className={`text-[11px] font-bold ${hasIt ? 'text-emerald-700' : 'text-rose-700 opacity-60'}`}>{periodName}</span>
                   {hasIt ? (
                     <div className="w-5 h-5 bg-emerald-500 rounded-full flex items-center justify-center text-white"><Check size={12} strokeWidth={4} /></div>
                   ) : (
                     <div className="w-5 h-5 bg-rose-200 rounded-full flex items-center justify-center text-rose-700"><X size={12} strokeWidth={4} /></div>
                   )}
                </div>
              )
            })}
         </div>
      </div>

      {!isComplete && (
        <div className="mt-6 flex items-start gap-3 p-4 bg-rose-600 rounded-2xl text-white shadow-lg shadow-rose-200 animate-pulse">
           <AlertCircle size={18} className="shrink-0 mt-0.5" />
           <div>
              <p className="text-xs font-black">وردية ناقصة</p>
              <p className="text-[10px] opacity-90 leading-relaxed mt-0.5">يفتقد الموظف إلى {missingPeriods.length} بصمات أساسية لاعتبار هذا اليوم مكتملاً وفقاً للوائح.</p>
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

