              </div>
            </div>
          )}

          {stats && (
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 animate-in slide-in-from-bottom-10 duration-700 delay-150">
              <StatCard title="إجمالي الموظفين" value={stats.totalEmployees} subtitle="موظف مسجل" icon={<Users className="text-indigo-600" />} gradient="from-indigo-50 to-indigo-100/30" />
              <StatCard title="انضباط الورديات" value={`${stats.completionRate}%`} subtitle="نسبة إكمال 5 بصمات" icon={<CheckCircle2 className="text-emerald-600" />} gradient="from-emerald-50 to-emerald-100/30" />
              <StatCard title="إجمالي الحركات" value={stats.totalPunches} subtitle="بصمة تم تحليلها" icon={<Clock className="text-amber-600" />} gradient="from-amber-50 to-amber-100/30" />
