import { ATTENDANCE_RULES } from '../constants';
import { ShiftReport, PunchDetail, EmployeeSummary } from '../types';

const parseTimeToMinutes = (t: string) => {
  const [h, m] = t.split(':').map(Number);
  return h * 60 + m;
};

export const classifyPunch = (
  timeStr: string, 
  isFirst: boolean, 
  isLast: boolean
): string | null => {
  const t = parseTimeToMinutes(timeStr);
  const periods = ATTENDANCE_RULES.TIME_PERIODS;

  // Rule 1: Exit Punch (Priority 1)
  const exitStart = parseTimeToMinutes(periods["فترة الخروج"].start);
  const exitEnd = parseTimeToMinutes(periods["فترة الخروج"].end);
  if (isLast && t >= exitStart && t <= exitEnd) {
    return "بصمة خروج";
  }

  // Rule 2: Morning Punch (Priority 2)
  const mornStart = parseTimeToMinutes(periods["فترة الصباح"].start);
  const mornEnd = parseTimeToMinutes(periods["فترة الصباح"].end);
  if (isFirst && t >= mornStart && t <= mornEnd) {
    return "دخول صباحي";
  }

  // Rule 3: Night Punch (Crosses midnight)
  const nightStart = parseTimeToMinutes(periods["بصمة ليلية"].start);
  const nightEnd = parseTimeToMinutes(periods["بصمة ليلية"].end);
  if (t >= nightStart || t <= nightEnd) {
    if (t > mornEnd || t < 240) { 
      return "بصمة ليلية";
    }
  }

  // Rule 4: Middle and Evening
  const midStart = parseTimeToMinutes(periods["بصمة وسطية"].start);
  const midEnd = parseTimeToMinutes(periods["بصمة وسطية"].end);
  if (t >= midStart && t <= midEnd) return "بصمة وسطية";

  const eveStart = parseTimeToMinutes(periods["بصمة مسائية"].start);
  const eveEnd = parseTimeToMinutes(periods["بصمة مسائية"].end);
  if (t >= eveStart && t <= eveEnd) return "بصمة مسائية";

  return null;
};

export const processExcelData = (rawData: any[]): EmployeeSummary[] => {
  if (!rawData || rawData.length === 0) return [];

  // Group by Employee ID
  const employeesMap: Map<string, any[]> = new Map();
  rawData.forEach(row => {
    const id = String(row['AC-No'] || row[1] || '0');
    if (!employeesMap.has(id)) employeesMap.set(id, []);
    employeesMap.get(id)?.push(row);
  });

  const allSummaries: EmployeeSummary[] = [];

  employeesMap.forEach((punches, id) => {
    const name = punches[0]['Name'] || punches[0][2] || 'غير معروف';

    // Group punches for this employee by the specific "Date" string from Excel
    const dateGroups: Map<string, Date[]> = new Map();

    punches.forEach(p => {
      const dateVal = p['Date'] || p[3];
      const timePart = String(p['Time'] || p[4] || "00:00");

      let dt: Date;
      let dateStringKey: string;

      if (typeof dateVal === 'number') {
        // Handle Excel numeric dates
        dt = new Date((dateVal - 25569) * 86400 * 1000);
        dateStringKey = dt.toLocaleDateString('en-CA'); // YYYY-MM-DD
      } else {
        dt = new Date(dateVal);
        dateStringKey = dateVal.toString(); // Use the string directly from Excel
      }

      const [h, m] = timePart.split(':').map(Number);
      dt.setHours(h || 0, m || 0, 0, 0);

      if (!dateGroups.has(dateStringKey)) {
        dateGroups.set(dateStringKey, []);
      }
      dateGroups.get(dateStringKey)?.push(dt);
    });

    // Create a shift report for each unique date mentioned in Excel
    const shifts: ShiftReport[] = [];

    // Sort keys (dates) chronologically
    const sortedDateKeys = Array.from(dateGroups.keys()).sort((a, b) => new Date(a).getTime() - new Date(b).getTime());

    sortedDateKeys.forEach(dateKey => {
      const dayPunches = dateGroups.get(dateKey) || [];
      // Sort punches within the day by time
      dayPunches.sort((a, b) => a.getTime() - b.getTime());

      shifts.push(createShiftReport(id, name, dayPunches, dateKey));
    });

    // Aggregate Summary
    const totalValidPunches = shifts.reduce((sum, s) => sum + s.punches_count, 0);
    const completedShifts = shifts.filter(s => s.status === 'مكتملة').length;
    const completionRate = shifts.length > 0 ? Math.round((completedShifts / shifts.length) * 100) : 0;
    const totalRequired = shifts.length * ATTENDANCE_RULES.REQUIRED_PUNCHES_PER_SHIFT;
    const performanceScore = totalRequired > 0 ? Math.round((totalValidPunches / totalRequired) * 100) : 0;

    allSummaries.push({
      id,
      name,
      shifts,
      totalPunches: totalValidPunches,
      completionRate,
      performanceScore,
      isEligible: completedShifts === shifts.length && shifts.length > 0
    });
  });

  return allSummaries;
};

function createShiftReport(id: string, name: string, punches: Date[], excelDateString: string): ShiftReport {
  const details: PunchDetail[] = [];
  const seenPeriods = new Set<string>();

  punches.forEach((p, idx) => {
    const timeStr = p.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
    const period = classifyPunch(timeStr, idx === 0, idx === punches.length - 1);
    const finalPeriod = period || "غير مصنفة";

    let isDuplicate = seenPeriods.has(finalPeriod) && finalPeriod !== "غير مصنفة";
    if (finalPeriod === "بصمة خروج") isDuplicate = false; 

    details.push({
      time: timeStr,
      period: finalPeriod,
      is_duplicate: isDuplicate,
      raw_datetime: p
    });

    if (!isDuplicate && finalPeriod !== "غير مصنفة") {
      seenPeriods.add(finalPeriod);
    }
  });

  const validCount = seenPeriods.size;

  return {
    employee_id: id,
    employee_name: name,
    shift_date: excelDateString, // Using the exact date from Excel
    punches_details: details,
    punches_count: validCount,
    status: validCount >= ATTENDANCE_RULES.REQUIRED_PUNCHES_PER_SHIFT ? 'مكتملة' : 'ناقصة'
  };
}

