import { ATTENDANCE_RULES } from '../constants';
import { ShiftReport, PunchDetail, EmployeeSummary } from '../types';

const parseTimeToMinutes = (t: string | Date): number => {
  if (t instanceof Date) {
    return t.getHours() * 60 + t.getMinutes();
  }
  const [h, m] = t.split(':').map(Number);
  return h * 60 + m;
};

const getMinutes = (h: number, m: number) => h * 60 + m;

/**
 * EXACT PORT OF PYTHON LOGIC FROM app.py
 */
export const classifyPunch = (
  punchDate: Date,
  isFirst: boolean,
  isLast: boolean
): string | null => {
  const t = parseTimeToMinutes(punchDate);
  const periods = ATTENDANCE_RULES.TIME_PERIODS;

  // Rule 1: Exit Punch (Priority 1) - If last in day and in exit period
  const exitStart = parseTimeToMinutes(periods["فترة الخروج"].start);
  const exitEnd = parseTimeToMinutes(periods["فترة الخروج"].end);
  if (isLast && t >= exitStart && t <= exitEnd) {
    return "بصمة خروج";
  }

  // Rule 2: Morning Punch (Priority 2) - If first and in morning period
  const mornStart = parseTimeToMinutes(periods["فترة الصباح"].start);
  const mornEnd = parseTimeToMinutes(periods["فترة الصباح"].end);
  if (isFirst && t >= mornStart && t <= mornEnd) {
    return "دخول صباحي";
  }

  // Rule 3: Night Punch (Priority 3) - Crosses midnight
  const nightStart = parseTimeToMinutes(periods["بصمة ليلية"].start);
  const nightEnd = parseTimeToMinutes(periods["بصمة ليلية"].end);
  // Python logic: punch_time >= start or punch_time <= end
  if (t >= nightStart || t <= nightEnd) {
    // Protection: ensures not too close to morning (Python uses 4:00 AM)
    if (t > mornEnd || t < getMinutes(4, 0)) {
      return "بصمة ليلية";
    }
  }

  // Rule 4: Middle and Evening Periods
  const midStart = parseTimeToMinutes(periods["بصمة وسطية"].start);
  const midEnd = parseTimeToMinutes(periods["بصمة وسطية"].end);
  if (t >= midStart && t <= midEnd) return "بصمة وسطية";

  const eveStart = parseTimeToMinutes(periods["بصمة مسائية"].start);
  const eveEnd = parseTimeToMinutes(periods["بصمة مسائية"].end);
  if (t >= eveStart && t <= eveEnd) return "بصمة مسائية";

  return null;
};

export const processExcelData = (rawData: any[]): EmployeeSummary[] => {
  if (!rawData || rawData.length === 0) return [];

  const employeesMap: Map<string, any[]> = new Map();

  // Preliminary sorting to handle rows correctly (mimicking Python pandas behavior)
  rawData.forEach(row => {
    const id = String(row['AC-No'] || row[1] || '0');
    if (!employeesMap.has(id)) employeesMap.set(id, []);
    employeesMap.get(id)?.push(row);
  });

  const allSummaries: EmployeeSummary[] = [];

  employeesMap.forEach((punches, id) => {
    const name = punches[0]['Name'] || punches[0][2] || 'غير معروف';

    // Sort all punches chronologically
    const sortedPunches = punches.map(p => {
      const dateVal = p['Date'] || p[3];
      const timePart = String(p['Time'] || p[4] || "00:00");
      let dt: Date;
      if (typeof dateVal === 'number') {
        dt = new Date((dateVal - 25569) * 86400 * 1000);
      } else {
        dt = new Date(dateVal);
      }
      const times = timePart.split(' '); // Handle multiple times in one cell if exists
      return times.map(tStr => {
        const d = new Date(dt);
        const [h, m] = tStr.split(':').map(Number);
        d.setHours(h || 0, m || 0, 0, 0);
        return d;
      });
    }).flat().sort((a, b) => a.getTime() - b.getTime());

    // Shift Grouping (Python: MAX_HOURS_BETWEEN_PUNCHES)
    const shiftsData: Date[][] = [];
    if (sortedPunches.length > 0) {
      let currentShift: Date[] = [sortedPunches[0]];
      for (let i = 1; i < sortedPunches.length; i++) {
        const diffHours = (sortedPunches[i].getTime() - sortedPunches[i-1].getTime()) / (1000 * 3600);
        if (diffHours > ATTENDANCE_RULES.MAX_HOURS_BETWEEN_PUNCHES) {
          shiftsData.push(currentShift);
          currentShift = [];
        }
        currentShift.push(sortedPunches[i]);
      }
      if (currentShift.length > 0) shiftsData.push(currentShift);
    }

    const shiftsReports: ShiftReport[] = shiftsData.map(punchDates => {
      const shiftDate = punchDates[0].toLocaleDateString('en-CA');
      const details: PunchDetail[] = [];
      const processedPeriods = new Set<string>();

      punchDates.forEach((p, idx) => {
        const isFirst = idx === 0;
        const isLast = idx === punchDates.length - 1;
        const periodType = classifyPunch(p, isFirst, isLast) || "غير مصنفة";

        let isDuplicate = processedPeriods.has(periodType) && periodType !== "غير مصنفة";
        // Exit punch is NEVER duplicate per python logic
        if (periodType === "بصمة خروج") isDuplicate = false;

        details.push({
          time: p.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' }),
          period: periodType,
          is_duplicate: isDuplicate,
          raw_datetime: p
        });

        if (!isDuplicate && periodType !== "غير مصنفة") {
          processedPeriods.add(periodType);
        }
      });

      const validCount = processedPeriods.size;
      return {
        employee_id: id,
        employee_name: name,
        shift_date: shiftDate,
        punches_details: details,
        punches_count: validCount,
        status: validCount >= ATTENDANCE_RULES.REQUIRED_PUNCHES_PER_SHIFT ? 'مكتملة' : 'ناقصة'
      };
    });

    const totalValidPunches = shiftsReports.reduce((sum, s) => sum + s.punches_count, 0);
    const completedShifts = shiftsReports.filter(s => s.status === 'مكتملة').length;
    const completionRate = shiftsReports.length > 0 ? Math.round((completedShifts / shiftsReports.length) * 100) : 0;

    allSummaries.push({
      id,
      name,
      shifts: shiftsReports,
      totalPunches: totalValidPunches,
      completionRate,
      performanceScore: shiftsReports.length > 0 ? Math.round((totalValidPunches / (shiftsReports.length * 5)) * 100) : 0,
      isEligible: completedShifts === shiftsReports.length && shiftsReports.length > 0
    });
  });

  return allSummaries;
};

