import { ATTENDANCE_RULES } from '../constants';
import { ShiftReport, PunchDetail, EmployeeSummary } from '../types';

const parseTimeToMinutes = (h: number, m: number) => h * 60 + m;

const getTimeInMinutes = (date: Date) => date.getHours() * 60 + date.getMinutes();

const getRuleMinutes = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h * 60 + m;
};

/**
 * تصنيف البصمة بناءً على القواعد المذكورة في ملف Python (app.py)
 */
export const classifyPunch = (
  punchDate: Date,
  isFirst: boolean,
  isLast: boolean
): string | null => {
  const t = getTimeInMinutes(punchDate);
  const periods = ATTENDANCE_RULES.TIME_PERIODS;

  // الأولوية 1: بصمة الخروج (آخر بصمة وضمن فترة الخروج)
  const exitStart = getRuleMinutes(periods["فترة الخروج"].start);
  const exitEnd = getRuleMinutes(periods["فترة الخروج"].end);
  if (isLast && t >= exitStart && t <= exitEnd) {
    return "بصمة خروج";
  }

  // الأولوية 2: دخول صباحي (أول بصمة وضمن فترة الصباح)
  const mornStart = getRuleMinutes(periods["فترة الصباح"].start);
  const mornEnd = getRuleMinutes(periods["فترة الصباح"].end);
  if (isFirst && t >= mornStart && t <= mornEnd) {
    return "دخول صباحي";
  }

  // الأولوية 3: بصمة ليلية (تعبر منتصف الليل)
  const nightStart = getRuleMinutes(periods["بصمة ليلية"].start);
  const nightEnd = getRuleMinutes(periods["بصمة ليلية"].end);
  if (t >= nightStart || t <= nightEnd) {
    // حماية إضافية: تأكد من أن الوقت ليس قريبًا من فترة الصباح (أقل من 4 فجراً أو بعد نهاية الصباح)
    if (t > mornEnd || t < parseTimeToMinutes(4, 0)) {
      return "بصمة ليلية";
    }
  }

  // الأولوية 4: فترات وسطية ومسائية
  const midStart = getRuleMinutes(periods["بصمة وسطية"].start);
  const midEnd = getRuleMinutes(periods["بصمة وسطية"].end);
  if (t >= midStart && t <= midEnd) return "بصمة وسطية";

  const eveStart = getRuleMinutes(periods["بصمة مسائية"].start);
  const eveEnd = getRuleMinutes(periods["بصمة مسائية"].end);
  if (t >= eveStart && t <= eveEnd) return "بصمة مسائية";

  return null;
};

export const processExcelData = (rawData: any[]): EmployeeSummary[] => {
  if (!rawData || rawData.length === 0) return [];

  // تجميع البيانات لكل موظف
  const employeesMap: Map<string, { name: string, punches: Date[] }> = new Map();

  rawData.forEach(row => {
    const id = String(row['AC-No'] || row[1] || '0');
    if (id === '0' || id === 'undefined') return;

    const name = row['Name'] || row[2] || 'موظف غير معروف';
    const dateVal = row['Date'] || row[3];
    const timePart = String(row['Time'] || row[4] || "00:00");

    let dt: Date;
    if (typeof dateVal === 'number') {
      dt = new Date((dateVal - 25569) * 86400 * 1000);
    } else {
      dt = new Date(dateVal);
    }

    // معالجة احتمالية وجود أكثر من وقت في نفس الخلية (مفصولة بمسافات)
    const times = timePart.split(/\s+/).filter(t => t.includes(':'));

    if (!employeesMap.has(id)) {
      employeesMap.set(id, { name, punches: [] });
    }

    times.forEach(tStr => {
      const d = new Date(dt);
      const [h, m] = tStr.split(':').map(Number);
      d.setHours(h || 0, m || 0, 0, 0);
      employeesMap.get(id)?.punches.push(d);
    });
  });

  const allSummaries: EmployeeSummary[] = [];

  employeesMap.forEach((data, id) => {
    // ترتيب كافة بصمات الموظف زمنياً
    const sortedPunches = data.punches.sort((a, b) => a.getTime() - b.getTime());

    // تقسيم البصمات إلى "ورديات" بناءً على قاعدة الـ 12 ساعة
    const shiftsData: Date[][] = [];
    if (sortedPunches.length > 0) {
      let currentShift: Date[] = [sortedPunches[0]];
      for (let i = 1; i < sortedPunches.length; i++) {
        const diffHours = (sortedPunches[i].getTime() - sortedPunches[i-1].getTime()) / (1000 * 3600);
        if (diffHours > ATTENDANCE_RULES.MAX_HOURS_BETWEEN_PUNCHES) {
          shiftsData.push(currentShift);
          currentShift = [];
        }
        currentShift.push(sortedPunches[i]);
      }
      if (currentShift.length > 0) shiftsData.push(currentShift);
    }

    // معالجة كل وردية لإنشاء التقارير
    const shiftsReports: ShiftReport[] = shiftsData.map(punchDates => {
      const startDate = punchDates[0].toLocaleDateString('en-CA');
      const details: PunchDetail[] = [];
      const processedPeriods = new Set<string>();

      punchDates.forEach((p, idx) => {
        const isFirst = idx === 0;
        const isLast = idx === punchDates.length - 1;
        const periodType = classifyPunch(p, isFirst, isLast) || "غير مصنفة";

        let isDuplicate = processedPeriods.has(periodType) && periodType !== "غير مصنفة";
        // بصمة الخروج لا تعتبر مكررة حسب منطق Python
        if (periodType === "بصمة خروج") isDuplicate = false;

        details.push({
          time: p.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' }),
          period: periodType,
          is_duplicate: isDuplicate,
          raw_datetime: p
        });

        if (!isDuplicate && periodType !== "غير مصنفة") {
          processedPeriods.add(periodType);
        }
      });

      // حساب عدد الفترات الفريدة الصالحة (بما في ذلك بصمة الخروج)
      const uniqueValidPeriods = new Set(details.filter(d => !d.is_duplicate && d.period !== "غير مصنفة").map(d => d.period));
      const validCount = uniqueValidPeriods.size;

      return {
        employee_id: id,
        employee_name: data.name,
        shift_date: startDate,
        punches_details: details,
        punches_count: validCount,
        status: validCount >= ATTENDANCE_RULES.REQUIRED_PUNCHES_PER_SHIFT ? 'مكتملة' : 'ناقصة'
      };
    });

    const totalValidPunches = shiftsReports.reduce((sum, s) => sum + s.punches_count, 0);
    const completedShifts = shiftsReports.filter(s => s.status === 'مكتملة').length;
    const completionRate = shiftsReports.length > 0 ? Math.round((completedShifts / shiftsReports.length) * 100) : 0;

    allSummaries.push({
      id,
      name: data.name,
      shifts: shiftsReports,
      totalPunches: totalValidPunches,
      completionRate,
      performanceScore: shiftsReports.length > 0 ? Math.round((totalValidPunches / (shiftsReports.length * 5)) * 100) : 0,
      isEligible: completedShifts === shiftsReports.length && shiftsReports.length > 0
    });
  });

  return allSummaries.sort((a, b) => Number(a.id) - Number(b.id));
};

