const ShiftDetailsCard: React.FC<{ shift: ShiftReport }> = ({ shift }) => {
  const isComplete = shift.status === 'مكتملة';
  const dayName = new Date(shift.shift_date).toLocaleDateString('ar-SA', { weekday: 'long' });
  const capturedPeriods = new Set(shift.punches_details.filter(p => !p.is_duplicate && p.period !== "غير مصنفة").map(p => p.period));

  // تجميع البصمات المتتالية من نفس الفترة
  const groupedPunches = useMemo(() => {
    return shift.punches_details.reduce((acc, punch) => {
      const last = acc[acc.length - 1];
      if (last && last.period === punch.period && last.is_duplicate === punch.is_duplicate) {
        last.items.push(punch);
      } else {
        acc.push({ period: punch.period, is_duplicate: punch.is_duplicate, items: [punch] });
      }
      return acc;
    }, [] as { period: string; is_duplicate: boolean; items: PunchDetail[] }[]);
  }, [shift.punches_details]);

  return (
    <div className={`p-8 rounded-[2.5rem] bg-white border-2 transition-all relative overflow-hidden group hover:shadow-2xl ${isComplete ? 'border-emerald-50 shadow-emerald-500/5 hover:border-emerald-100' : 'border-rose-50 shadow-rose-500/5 hover:border-rose-100'}`}>
      <div className="flex items-center justify-between mb-8 relative z-10 text-right">
        <div className="flex items-center gap-4">
           <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shadow-lg transition-transform group-hover:scale-110 ${isComplete ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
              <Calendar size={20} />
           </div>
           <div>
             <h5 className="font-black text-base text-slate-800 leading-none mb-1.5">{shift.shift_date}</h5>
             <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">{dayName}</p>
           </div>
        </div>
        <div className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-tighter shadow-sm ${isComplete ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
          {shift.status}
        </div>
      </div>

      <div className="relative space-y-5 before:absolute before:inset-y-0 before:right-3 before:w-0.5 before:bg-slate-100">
        {groupedPunches.map((group, gIdx) => (
          <div key={gIdx} className="relative pr-10 group/punch text-right">
             <div className={`absolute right-0 top-0.5 w-6 h-6 rounded-full border-4 border-white shadow-md z-10 ${group.is_duplicate ? 'bg-amber-400' : group.period === "غير مصنفة" ? 'bg-slate-200' : 'bg-indigo-600'}`}></div>
             <div className="bg-slate-50/50 p-4 rounded-2xl border border-transparent group-hover/punch:bg-white group-hover/punch:border-slate-100 group-hover/punch:shadow-lg transition-all">
                <div className="flex items-center justify-between mb-1">
                  <span className={`text-[11px] font-black ${group.is_duplicate ? 'text-amber-600' : group.period === "غير مصنفة" ? 'text-slate-400 italic' : 'text-slate-800'}`}>
                    {group.period}
                    {group.is_duplicate && " (مكررة)"}
                    {group.items.length > 1 && ` (${group.items.length} بصمات)`}
                  </span>
                  <div className="flex flex-col items-end gap-1">
                    {group.items.map((it, i) => (
                      <span key={i} className="text-[10px] font-black text-indigo-700 bg-indigo-50 px-2.5 py-0.5 rounded-lg shadow-sm">
                        {it.time}
                      </span>
                    ))}
                  </div>
                </div>
                <div className="text-[8px] text-slate-400 font-bold uppercase flex items-center gap-2">
                   <span>تجميع {group.period}</span>
                   {group.is_duplicate && <span className="text-amber-500">• حركة مستبعدة</span>}
                </div>
             </div>
          </div>
        ))}
      </div>

      <div className="mt-10 pt-8 border-t border-slate-50 text-right">
         <div className="flex items-center justify-between mb-4">
            <h6 className="text-[9px] font-black text-slate-400 uppercase tracking-widest">تغطية فترات الوردية</h6>
            <span className="text-[10px] font-black text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded-full">{capturedPeriods.size} / 5</span>
         </div>
         <div className="grid grid-cols-1 gap-2">
            {Object.keys(ATTENDANCE_RULES.TIME_PERIODS).map((periodName) => {
              const hasIt = capturedPeriods.has(periodName);
              return (
                <div key={periodName} className={`flex items-center justify-between px-3 py-2.5 rounded-xl border transition-all ${hasIt ? 'bg-emerald-50/40 border-emerald-100' : 'bg-rose-50/20 border-rose-50 border-dashed opacity-50'}`}>
                   <span className={`text-[10px] font-black ${hasIt ? 'text-emerald-700' : 'text-rose-400'}`}>{periodName}</span>
                   {hasIt ? <Check size={12} className="text-emerald-500" strokeWidth={4} /> : <X size={10} className="text-rose-200" strokeWidth={4} />}
                </div>
              )
            })}
         </div>
      </div>

      {!isComplete && (
        <div className="mt-8 flex items-start gap-3 p-4 bg-rose-600 rounded-3xl text-white shadow-xl shadow-rose-200/50">
           <AlertCircle size={18} className="shrink-0 mt-0.5" />
           <div>
              <p className="text-xs font-black">وردية غير مكتملة</p>
              <p className="text-[9px] opacity-90 font-bold leading-relaxed mt-1">يفتقر الموظف إلى بصمات أساسية لاعتبار هذه الوردية نظامية.</p>
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

