          {stats && (
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
              <StatItem title="موظفون نشطون" value={stats.totalEmployees} subtitle="تم رصدهم في الملف" icon={<Users className="text-indigo-600" />} />
              <StatItem title="متوسط الانضباط" value={`${stats.completionRate}%`} subtitle="للأيام النشطة فقط" icon={<CheckCircle2 className="text-emerald-600" />} />
