    </div>
  </div>
);

const ShiftDetailsCard: React.FC<{ shift: ShiftReport }> = ({ shift }) => {
  const isComplete = shift.status === 'مكتملة';
  const capturedPeriods = new Set(shift.punches_details.filter(p => !p.is_duplicate && p.period !== "غير مصنفة").map(p => p.period));

  // تجميع البصمات المتتالية من نفس الفترة والنوع
  const groupedPunches = useMemo(() => {
    return shift.punches_details.reduce((acc, punch) => {
      const last = acc[acc.length - 1];
      if (last && last.period === punch.period && last.is_duplicate === punch.is_duplicate) {
        last.items.push(punch);
      } else {
        acc.push({ period: punch.period, is_duplicate: punch.is_duplicate, items: [punch] });
      }
      return acc;
    }, [] as { period: string; is_duplicate: boolean; items: PunchDetail[] }[]);
  }, [shift.punches_details]);

  return (
    <div className={`p-8 rounded-[2.5rem] bg-white border-2 transition-all relative overflow-hidden group hover:shadow-xl ${isComplete ? 'border-emerald-50 shadow-emerald-500/5 hover:border-emerald-100' : 'border-rose-50 shadow-rose-500/5 hover:border-rose-100'}`}>
      <div className="flex items-center justify-between mb-8 text-right relative z-10">
        <div className="flex items-center gap-4">
           <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${isComplete ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
             <Calendar size={20} />
           </div>
           <div>
             <h5 className="font-black text-base text-slate-800">{shift.shift_date}</h5>
             <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest">{new Date(shift.shift_date).toLocaleDateString('ar-SA', { weekday: 'long' })}</p>
           </div>
        </div>
        <div className={`px-4 py-1.5 rounded-xl text-[9px] font-black uppercase tracking-tighter shadow-sm ${isComplete ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
          {shift.status}
        </div>
      </div>

      <div className="relative space-y-4 before:absolute before:inset-y-0 before:right-3 before:w-0.5 before:bg-slate-100">
        {groupedPunches.map((group, gIdx) => (
          <div key={gIdx} className="relative pr-10 text-right group/punch">
             <div className={`absolute right-0 top-1 w-6 h-6 rounded-full border-4 border-white shadow-md z-10 flex items-center justify-center transition-transform group-hover/punch:scale-110 ${group.is_duplicate ? 'bg-amber-500' : group.period === "غير مصنفة" ? 'bg-slate-300' : 'bg-indigo-600'}`}>
                {group.is_duplicate ? <AlertTriangle size={10} className="text-white" /> : group.period === "غير مصنفة" ? <Info size={10} className="text-white" /> : <Fingerprint size={10} className="text-white" />}
             </div>

             <div className={`p-4 rounded-2xl border transition-all ${
               group.is_duplicate 
                ? 'bg-amber-50/60 border-amber-200 border-dashed shadow-inner' 
                : 'bg-slate-50/50 border-transparent hover:bg-white hover:border-slate-100 hover:shadow-lg'
             }`}>
                <div className="flex items-center justify-between mb-2">
                  <div className="flex flex-col">
                    <span className={`text-[11px] font-black leading-none ${group.is_duplicate ? 'text-amber-800' : 'text-slate-800'}`}>
                      {group.period}
                      {group.is_duplicate && <span className="mr-2 inline-flex px-1.5 py-0.5 rounded-md bg-amber-200 text-[8px] text-amber-900 font-black tracking-tighter">مكررة</span>}
                    </span>
                    {group.items.length > 1 && <span className="text-[8px] text-slate-400 font-bold mt-1 tracking-tight italic">تكرار الحركات المتتالية ({group.items.length})</span>}
                  </div>
                  <div className="flex flex-col items-end gap-1">
                    {group.items.map((it, i) => (
                      <span key={i} className={`text-[9px] font-black px-2.5 py-1 rounded-lg shadow-sm ${group.is_duplicate ? 'bg-amber-100 text-amber-900 border border-amber-200' : 'bg-indigo-50 text-indigo-700 border border-indigo-100'}`}>{it.time}</span>
                    ))}
                  </div>
                </div>
                {group.is_duplicate && <p className="text-[8px] text-amber-600 font-black mt-1 uppercase leading-none opacity-80">بيانات مستبعدة إدارياً لضمان الدقة</p>}
             </div>
          </div>
        ))}
      </div>

      <div className="mt-8 pt-6 border-t border-slate-50 text-right">
         <div className="flex items-center justify-between mb-4">
            <h6 className="text-[9px] font-black text-slate-400 uppercase tracking-widest">تغطية فترات الدوام</h6>
            <span className="text-[10px] font-black text-indigo-600 bg-indigo-50 px-2.5 py-1 rounded-lg">{capturedPeriods.size} / 5</span>
         </div>
         <div className="grid grid-cols-1 gap-1.5">
            {Object.keys(ATTENDANCE_RULES.TIME_PERIODS).map((periodName) => {
              const hasIt = capturedPeriods.has(periodName);
              return (
                <div key={periodName} className={`flex items-center justify-between px-3 py-2.5 rounded-xl border transition-all ${hasIt ? 'bg-emerald-50/40 border-emerald-100 shadow-sm' : 'bg-slate-50 border-slate-50 opacity-40 grayscale'}`}>
                   <span className={`text-[10px] font-black ${hasIt ? 'text-emerald-700' : 'text-slate-400'}`}>{periodName}</span>
                   {hasIt ? <Check size={12} className="text-emerald-500" strokeWidth={4} /> : <X size={10} className="text-slate-200" />}
                </div>
              )
            })}
         </div>
      </div>

      {!isComplete && (
        <div className="mt-6 p-4 bg-rose-600 rounded-3xl text-white shadow-xl shadow-rose-200/50 flex items-start gap-3">
           <AlertTriangle size={18} className="shrink-0 mt-0.5" />
           <div>
              <p className="text-[10px] font-black uppercase tracking-tight">تقرير وردية ناقصة</p>
              <p className="text-[9px] font-bold opacity-90 mt-1 leading-relaxed">لم يتم رصد 5 حركات بصمة صحيحة لهذه الوردية.</p>
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { 
  FileUp, Search, Users, CheckCircle2, Clock, TrendingUp, BrainCircuit, X, Menu,
  Calendar, AlertCircle, LayoutDashboard, Sparkles, ChevronDown, Download,
  Check, Info, Fingerprint, History, BarChart3, ShieldCheck, UserCircle,
  AlertTriangle, Flame
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { analyzeEmployeeAttendanceAI, analyzeCompanyTrendsAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';
import { ATTENDANCE_RULES, COLORS } from './constants';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [selectedEmployee, setSelectedEmployee] = useState<EmployeeSummary | null>(null);
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [companyInsight, setCompanyInsight] = useState<string | null>(null);

  // إحصائيات عامة بناءً على البيانات النشطة المستخرجة
  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalActiveDays = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeActiveDays = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: totalActiveDays > 0 ? Math.round((completeActiveDays / totalActiveDays) * 100) : 0,
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0)
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => 
      e.name.toLowerCase().includes(term) || String(e.id).includes(term)
    );
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        // @ts-ignore
        const workbook = XLSX.read(data, { type: 'array' });
        const firstSheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[firstSheetName];
        // @ts-ignore
        const json = XLSX.utils.sheet_to_json(worksheet);
        const processed = processExcelData(json);
        setEmployees(processed);
      } catch (err) {
        console.error("Upload Error:", err);
        alert("خطأ في قراءة ملف الإكسل. تأكد من وجود الأعمدة المطلوبة.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const getCompanyInsight = async () => {
    if (employees.length === 0) return;
    setIsAiLoading(true);
    const insight = await analyzeCompanyTrendsAI(employees);
    setCompanyInsight(insight);
    setIsAiLoading(false);
  };

  return (
    <div className="min-h-screen flex bg-[#f8fafc] text-slate-900 font-sans antialiased overflow-hidden">
      {/* Sidebar */}
      <aside className={`fixed inset-y-0 right-0 z-50 w-72 bg-[#0f172a] text-white transition-transform duration-500 ease-in-out lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'} shadow-2xl`}>
        <div className="p-8 h-full flex flex-col">
          <div className="flex items-center gap-4 mb-12">
            <div className="w-12 h-12 bg-indigo-500 rounded-2xl flex items-center justify-center shadow-lg shadow-indigo-500/30 rotate-3 transition-transform hover:rotate-0">
              <BrainCircuit size={28} className="text-white" />
            </div>
            <div>
              <h1 className="font-extrabold text-xl tracking-tight">بصمتي PRO</h1>
              <p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest">إدارة الذكاء الاصطناعي</p>
            </div>
          </div>

          <nav className="space-y-1.5 flex-1">
            <SidebarItem icon={<LayoutDashboard size={20}/>} label="لوحة التحكم" active />
            <SidebarItem icon={<Users size={20}/>} label="الموظفون" />
            <SidebarItem icon={<BarChart3 size={20}/>} label="تحليل البيانات" />
          </nav>

          <div className="bg-slate-800/50 p-5 rounded-2xl border border-slate-700/50 mb-6">
            <div className="flex items-center gap-2 mb-2">
              <ShieldCheck size={14} className="text-emerald-400" />
              <p className="text-[10px] font-bold text-slate-300">الفرز النشط مفعل</p>
            </div>
            <p className="text-[10px] text-slate-400 leading-relaxed">يتم استبعاد الأيام التي لا تحتوي على حركات بصمة من الحسابات والإحصائيات نهائياً.</p>
          </div>

          <div className="mt-auto">
            <label className="flex items-center justify-center gap-3 w-full p-4 bg-indigo-600 rounded-xl cursor-pointer hover:bg-indigo-700 transition-all active:scale-[0.98] shadow-xl shadow-indigo-600/20 font-bold text-sm">
              <FileUp size={18} />
              <span>رفع سجل البصمة</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
