          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 lg:pr-72 min-h-screen overflow-y-auto custom-scrollbar">
        <header className="sticky top-0 z-40 bg-white/80 backdrop-blur-xl border-b border-slate-200/60 px-6 py-4 sm:px-10">
          <div className="max-w-7xl mx-auto flex items-center justify-between gap-4">
            <button className="lg:hidden p-2 text-slate-600" onClick={() => setIsSidebarOpen(!isSidebarOpen)}>
              <Menu size={24} />
            </button>

            <div className="relative flex-1 max-w-xl group">
              <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-indigo-600 transition-colors" size={18} />
              <input 
                type="text" 
                placeholder="ابحث بالاسم أو الرقم الوظيفي..." 
                className="w-full bg-slate-100/50 border-none rounded-2xl pr-12 pl-4 py-3 outline-none focus:ring-4 focus:ring-indigo-500/10 focus:bg-white transition-all text-sm font-semibold"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
