            </div>

            <button 
              onClick={getCompanyInsight}
              disabled={employees.length === 0}
              className="flex items-center gap-2 px-6 py-3 bg-slate-900 text-white rounded-xl font-bold text-sm shadow-lg hover:shadow-slate-300/50 transition-all disabled:opacity-30"
            >
              <Sparkles size={16} className="text-indigo-400" />
              <span className="hidden sm:inline">التحليل العام للشركة</span>
            </button>
          </div>
        </header>

        <div className="p-6 sm:p-10 max-w-7xl mx-auto space-y-10">
          {companyInsight && (
            <div className="bg-indigo-900 text-white p-8 rounded-[2rem] shadow-2xl relative overflow-hidden animate-in fade-in zoom-in duration-500">
              <div className="relative flex flex-col md:flex-row gap-8 items-start">
                <div className="p-4 bg-white/10 backdrop-blur-lg rounded-2xl border border-white/10">
                  <BrainCircuit size={32} />
                </div>
                <div className="flex-1">
                  <h2 className="text-xl font-black mb-3 flex items-center gap-2">
                    توصيات إدارية ذكية (AI)
                    <span className="text-[9px] bg-white/10 px-2 py-0.5 rounded-full uppercase tracking-widest">Global Insights</span>
                  </h2>
                  <div className="text-indigo-100/90 leading-relaxed text-sm whitespace-pre-line font-medium">
                    {companyInsight}
                  </div>
                </div>
                <button onClick={() => setCompanyInsight(null)} className="p-2 hover:bg-white/10 rounded-full transition-colors"><X size={20} /></button>
              </div>
            </div>
          )}

          {stats && (
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
              <StatItem title="موظفون نشطون" value={stats.totalEmployees} subtitle="تم رصدهم في الملف" icon={<Users className="text-indigo-600" />} />
              <StatItem title="متوسط الانضباط" value={`${stats.completionRate}%`} subtitle="للأيام النشطة فقط" icon={<CheckCircle2 className="text-emerald-600" />} />
              <StatItem title="حركات البصمة" value={stats.totalPunches} subtitle="إجمالي البصمات الصالحة" icon={<Clock className="text-amber-600" />} />
            </div>
          )}

          <div className="space-y-6">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-slate-200 pb-4">
              <div>
                <h2 className="text-2xl font-black text-slate-800 tracking-tight">سجل الموظفين النشطين</h2>
                <p className="text-slate-400 text-xs font-bold mt-1">يتم استبعاد الأيام الفارغة من حساب "إجمالي البصمات" و "كفاءة البصمة".</p>
              </div>
            </div>

            {isAnalyzing ? (
              <div className="flex flex-col items-center justify-center py-32 bg-white rounded-[3rem] border border-slate-100 shadow-xl">
                <div className="w-16 h-16 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin mb-6"></div>
                <h3 className="text-xl font-black text-slate-800 tracking-tight">جاري تنقية البيانات...</h3>
              </div>
            ) : filteredEmployees.length > 0 ? (
              <div className="grid grid-cols-1 gap-6">
                {filteredEmployees.map((emp, i) => (
                  <EmployeeRow 
                    key={emp.id} 
                    employee={emp} 
                    index={i} 
                    onAnalyze={async () => {
                      setSelectedEmployee(emp);
                      setIsAiLoading(true);
                      const res = await analyzeEmployeeAttendanceAI(emp);
                      setAiAnalysis(res);
                      setIsAiLoading(false);
                    }}
                  />
                ))}
              </div>
            ) : (
              <div className="text-center py-32 bg-white rounded-[3rem] border-2 border-dashed border-slate-200">
                <Fingerprint size={48} className="mx-auto mb-6 text-slate-300" />
                <h3 className="text-2xl font-black text-slate-700 tracking-tight">يرجى رفع ملف سجل البصمة</h3>
                <p className="text-slate-400 text-sm mt-2 font-bold max-w-xs mx-auto">تأكد من أن الملف يحتوي على أعمدة AC-No, Name, Date, Time.</p>
              </div>
            )}
          </div>
        </div>
      </main>

      {/* AI Modal */}
      {selectedEmployee && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setSelectedEmployee(null)}></div>
          <div className="relative w-full max-w-2xl bg-white rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-8 bg-[#0f172a] text-white flex justify-between items-center">
              <div className="flex items-center gap-4">
                <Sparkles size={20} className="text-indigo-400" />
                <h3 className="font-black text-lg tracking-tight">تحليل Gemini 3 الذكي</h3>
              </div>
              <button onClick={() => setSelectedEmployee(null)} className="p-2 hover:bg-white/10 rounded-full transition-colors"><X size={20} /></button>
            </div>
            <div className="p-10">
              {isAiLoading ? (
                <div className="flex flex-col items-center py-10 space-y-4">
                  <div className="w-10 h-10 border-4 border-indigo-600 border-t-transparent animate-spin rounded-full"></div>
                  <p className="text-xs font-black text-slate-500 uppercase tracking-widest">Reviewing Attendance Patterns</p>
                </div>
              ) : (
                <div className="bg-slate-50 p-6 rounded-2xl border border-slate-100 text-slate-700 leading-relaxed whitespace-pre-line text-sm font-medium shadow-inner">
                  {aiAnalysis}
                </div>
              )}
              <div className="mt-8 flex justify-end">
                 <button onClick={() => setSelectedEmployee(null)} className="px-8 py-3 bg-slate-900 text-white rounded-xl font-black text-sm hover:scale-[1.02] transition-all">فهمت، إغلاق</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

