        <div className="flex items-center gap-6">
          <div className="w-16 h-16 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-300 font-black text-2xl border border-slate-100 group-hover:bg-indigo-600 transition-colors">
            {employee.name.charAt(0)}
          </div>
          <div>
            <h3 className="text-xl font-black text-slate-800 tracking-tight flex items-center gap-2">
              {employee.name}
              {employee.isEligible && <span className="text-[8px] bg-emerald-500 text-white px-2 py-0.5 rounded-full font-black uppercase">منضبط تماماً</span>}
