const SimpleStat: React.FC<{ label: string; value: string | number; status?: 'good' | 'bad'; isProgress?: boolean }> = ({ label, value, status, isProgress }) => (
  <div>
    <p className="text-[9px] uppercase font-black text-slate-400 mb-1">{label}</p>
