// تحسين حساب التوكنات للغة العربية (حيث أن كل حرف عربي غالباً ما يمثل توكن واحد أو أكثر في بعض النماذج)
const estimateTokens = (text: string) => Math.ceil(text.length / 1.5); 
const MAX_SAFE_TOKENS = 15000; // حد أمان لضمان سرعة الاستجابة وعدم التجاوز

/**
 * تقليص البيانات بذكاء للحفاظ على السياق المهم فقط في حال تجاوز الحدود
 */
const pruneEmployeeData = (employee: EmployeeSummary) => {
  // نركز على الأيام التي بها خلل أو نقص لأنها الأهم للتحليل
  const problematicShifts = employee.shifts.filter(s => s.status === 'ناقصة').slice(-15);
  const perfectShifts = employee.shifts.filter(s => s.status === 'مكتملة').slice(-5);

  const merged = [...problematicShifts, ...perfectShifts].sort((a,b) => 
    new Date(a.shift_date).getTime() - new Date(b.shift_date).getTime()
  );

  return merged.map(s => 
    `${s.shift_date}:${s.status === 'مكتملة' ? '✅' : '❌'}(${s.punches_count}بصمات)`
  ).join(' | ');
};

export const analyzeEmployeeAttendanceAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const dataSummary = pruneEmployeeData(employee);

  const prompt = `
    أنت خبير إداري ومحلل بيانات ذكاء اصطناعي. حلل سجل حضور الموظف التالي بدقة:
    اسم الموظف: ${employee.name}
    نظام الدوام: وردية 24 ساعة (يوم عمل و 3 أيام استراحة).
    إحصائيات الأداء:
    - إجمالي الأيام النشطة: ${employee.shifts.length}
    - نسبة الانضباط الكلي: ${employee.completionRate}%
    - كفاءة تغطية الفترات: ${employee.performanceScore}%

    سجل الحركات (مقتطع للأهمية):
    ${dataSummary}

    المطلوب تحليل "منطقي" عميق:
    1. هل هناك "فترة زمنية" محددة (مثلاً خروج الصباح أو بصمة الليل) ينساها الموظف باستمرار؟
    2. قارن بين كفاءة الموظف في البداية والنهاية.
    3. استنتج الحالة النفسية أو الالتزام بناءً على أنماط البصمة المكررة أو المفقودة.
    4. قدم 3 خطوات عملية "مخصصة" لهذا الموظف.

    اجعل الأسلوب مهني، مشجع، ومباشر باللغة العربية.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        temperature: 0.2, // تقليل العشوائية لزيادة المنطقية
        topP: 0.8,
        thinkingConfig: { thinkingBudget: 0 } // Flash doesn't need high budget for this
      }
    });
    return response.text || "فشل توليد التحليل الذكي.";
  } catch (error) {
    console.error("AI Analysis Error:", error);
    return "نعتذر، واجه الذكاء الاصطناعي صعوبة في معالجة هذه البيانات حالياً.";
  }
};

