    </div>
  </div>
);

const ShiftDetailsCard: React.FC<{ shift: ShiftReport }> = ({ shift }) => {
  const isComplete = shift.status === 'مكتملة';
  const capturedPeriods = new Set(shift.punches_details.filter(p => !p.is_duplicate && p.period !== "غير مصنفة").map(p => p.period));

  const groupedPunches = useMemo(() => {
    return shift.punches_details.reduce((acc, punch) => {
      const last = acc[acc.length - 1];
      if (last && last.period === punch.period && last.is_duplicate === punch.is_duplicate) {
        last.items.push(punch);
      } else {
        acc.push({ period: punch.period, is_duplicate: punch.is_duplicate, items: [punch] });
      }
      return acc;
    }, [] as { period: string; is_duplicate: boolean; items: PunchDetail[] }[]);
  }, [shift.punches_details]);

  return (
    <div className={`p-10 rounded-[3rem] bg-white border-2 transition-all relative overflow-hidden group/card hover:shadow-2xl ${isComplete ? 'border-emerald-50 shadow-emerald-500/5 hover:border-emerald-100' : 'border-rose-50 shadow-rose-500/5 hover:border-rose-100'}`}>
      <div className="flex items-center justify-between mb-10 text-right relative z-10">
        <div className="flex items-center gap-5">
           <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shadow-inner ${isComplete ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
             <Calendar size={22} />
           </div>
           <div>
             <h5 className="font-black text-lg text-slate-900 tracking-tighter leading-none">{shift.shift_date}</h5>
             <p className="text-[10px] text-slate-400 font-black uppercase tracking-[0.2em] mt-2">{new Date(shift.shift_date).toLocaleDateString('ar-SA', { weekday: 'long' })}</p>
           </div>
        </div>
        <div className={`px-5 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-lg ${isComplete ? 'bg-emerald-500 text-white shadow-emerald-200' : 'bg-rose-500 text-white shadow-rose-200'}`}>
          {shift.status}
        </div>
      </div>

      <div className="relative space-y-6 before:absolute before:inset-y-0 before:right-4 before:w-[1px] before:bg-slate-100">
        {groupedPunches.map((group, gIdx) => (
          <div key={gIdx} className="relative pr-12 text-right group/punch">
             <div className={`absolute right-0 top-1 w-8 h-8 rounded-full border-4 border-white shadow-lg z-10 flex items-center justify-center transition-all group-hover/punch:scale-125 ${
               group.is_duplicate 
                 ? 'bg-amber-500 ring-4 ring-amber-100 animate-pulse' 
                 : group.period === "غير مصنفة" 
                   ? 'bg-slate-300' 
                   : 'bg-indigo-600 shadow-indigo-200'
             }`}>
                {group.is_duplicate ? <AlertTriangle size={12} className="text-white" /> : group.period === "غير مصنفة" ? <Info size={12} className="text-white" /> : <Fingerprint size={12} className="text-white" />}
             </div>

             <div className={`p-6 rounded-[2rem] border transition-all ${
               group.is_duplicate 
                ? 'bg-amber-50/40 border-amber-200 border-dashed shadow-inner' 
                : 'bg-slate-50/50 border-transparent hover:bg-white hover:border-slate-100 hover:shadow-xl group-hover/card:bg-white'
             }`}>
                <div className="flex items-center justify-between mb-3">
                  <div className="flex flex-col">
                    <span className={`text-xs font-black tracking-tight ${group.is_duplicate ? 'text-amber-900' : 'text-slate-900'}`}>
                      {group.period}
                      {group.is_duplicate && (
                        <span className="mr-2 inline-flex items-center gap-1 px-2.5 py-1 rounded-lg bg-amber-200 text-[8px] text-amber-900 font-black tracking-tighter uppercase shadow-sm">
                          <Flame size={10} /> مكررة
                        </span>
                      )}
                    </span>
                    {group.items.length > 1 && <span className="text-[9px] text-slate-400 font-bold mt-1 italic opacity-70">تم رصد {group.items.length} حركات متلاحقة</span>}
                  </div>
                  <div className="flex flex-wrap justify-end gap-1.5 max-w-[120px]">
                    {group.items.map((it, i) => (
                      <span key={i} className={`text-[10px] font-black px-3 py-1 rounded-xl shadow-sm border transition-all hover:scale-110 ${
                        group.is_duplicate 
                          ? 'bg-amber-100 text-amber-900 border-amber-300' 
                          : 'bg-white text-indigo-700 border-indigo-100'
                      }`}>
                        {it.time}
                      </span>
                    ))}
                  </div>
                </div>
                {group.is_duplicate && (
                   <div className="mt-3 flex items-center gap-2 p-2 bg-white/60 rounded-xl border border-amber-200/50">
                      <AlertCircle size={12} className="text-amber-600 shrink-0" />
                      <p className="text-[9px] text-amber-800 font-bold leading-none opacity-80 uppercase tracking-tight">بيانات مستبعدة برمجياً لضمان دقة الكفاءة</p>
                   </div>
                )}
             </div>
          </div>
        ))}
      </div>

      <div className="mt-12 pt-10 border-t border-slate-50 text-right">
         <div className="flex items-center justify-between mb-6">
            <h6 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">تغطية الفترات (وردية 24 ساعة)</h6>
            <span className="text-[11px] font-black text-indigo-600 bg-indigo-50 px-4 py-1.5 rounded-full shadow-inner">{capturedPeriods.size} / 5</span>
         </div>
         <div className="grid grid-cols-1 gap-2">
            {Object.keys(ATTENDANCE_RULES.TIME_PERIODS).map((periodName) => {
              const hasIt = capturedPeriods.has(periodName);
              return (
                <div key={periodName} className={`flex items-center justify-between px-5 py-3 rounded-2xl border transition-all ${hasIt ? 'bg-emerald-50/50 border-emerald-100 shadow-sm opacity-100' : 'bg-slate-50 border-slate-50 opacity-30 grayscale group-hover/card:grayscale-0 group-hover/card:opacity-50'}`}>
                   <span className={`text-[10px] font-black ${hasIt ? 'text-emerald-800' : 'text-slate-400'}`}>{periodName}</span>
                   {hasIt ? (
                     <div className="w-5 h-5 bg-emerald-500 rounded-full flex items-center justify-center shadow-lg shadow-emerald-200">
                        <Check size={12} className="text-white" strokeWidth={4} />
                     </div>
                   ) : <X size={12} className="text-slate-300" />}
                </div>
              )
            })}
         </div>
      </div>

      {!isComplete && (
        <div className="mt-10 p-6 bg-gradient-to-br from-rose-600 to-rose-700 rounded-[2rem] text-white shadow-2xl shadow-rose-200 relative overflow-hidden">
           <div className="absolute top-0 right-0 w-24 h-24 bg-white/5 blur-2xl rounded-full"></div>
           <div className="relative flex items-start gap-4">
              <AlertTriangle size={24} className="shrink-0 mt-0.5 animate-bounce" />
              <div>
                 <p className="text-xs font-black uppercase tracking-widest leading-none">وردية غير مكتملة</p>
                 <p className="text-[10px] font-bold opacity-90 mt-2 leading-relaxed">بناءً على المنطق الذكي، يفتقد الموظف لبعض البصمات المحورية لإغلاق هذه الدورة بنجاح.</p>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

