);

const ShiftCard: React.FC<{ shift: ShiftReport }> = ({ shift }) => {
  const isComplete = shift.status === 'مكتملة';
  const capturedPeriods = new Set(shift.punches_details.filter(p => !p.is_duplicate && p.period !== "غير مصنفة").map(p => p.period));

  const grouped = useMemo(() => {
    return shift.punches_details.reduce((acc, punch) => {
      const last = acc[acc.length - 1];
      if (last && last.period === punch.period && last.is_duplicate === punch.is_duplicate) {
        last.items.push(punch);
      } else {
        acc.push({ period: punch.period, is_duplicate: punch.is_duplicate, items: [punch] });
      }
      return acc;
    }, [] as { period: string; is_duplicate: boolean; items: PunchDetail[] }[]);
  }, [shift.punches_details]);

  return (
    <div className={`p-10 rounded-[3.5rem] bg-white border-2 transition-all duration-500 relative overflow-hidden hover:shadow-3xl group/shift ${isComplete ? 'border-emerald-50 shadow-emerald-500/5 hover:border-emerald-100' : 'border-rose-50 shadow-rose-500/5 hover:border-rose-100'}`}>
      <div className="flex items-center justify-between mb-10 text-right relative z-10">
        <div className="flex items-center gap-6">
           <div className={`w-14 h-14 rounded-3xl flex items-center justify-center shadow-inner ${isComplete ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
             <Calendar size={24} />
           </div>
           <div>
             <h5 className="font-black text-xl text-slate-900 tracking-tighter leading-none">{shift.shift_date}</h5>
             <p className="text-[11px] text-slate-400 font-bold mt-2 uppercase tracking-widest">{new Date(shift.shift_date).toLocaleDateString('ar-SA', { weekday: 'long' })}</p>
           </div>
        </div>
        <div className={`px-6 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl ${isComplete ? 'bg-emerald-500 text-white shadow-emerald-200' : 'bg-rose-500 text-white shadow-rose-200'}`}>
          {shift.status}
        </div>
      </div>

      <div className="relative space-y-6 before:absolute before:inset-y-0 before:right-5 before:w-[2px] before:bg-slate-100 group-hover/shift:before:bg-indigo-50">
        {grouped.map((group, gIdx) => (
          <div key={gIdx} className="relative pr-14 text-right group/item">
             <div className={`absolute right-0 top-1 w-10 h-10 rounded-full border-4 border-white shadow-xl z-10 flex items-center justify-center transition-all group-hover/item:scale-125 ${
               group.is_duplicate 
                 ? 'bg-amber-500 ring-4 ring-amber-100 animate-pulse' 
                 : group.period === "غير مصنفة" 
                   ? 'bg-slate-300' 
                   : 'bg-indigo-600 shadow-indigo-100'
             }`}>
                {group.is_duplicate ? <AlertTriangle size={14} className="text-white" /> : group.period === "غير مصنفة" ? <Info size={14} className="text-white" /> : <Fingerprint size={14} className="text-white" />}
             </div>

             <div className={`p-6 rounded-[2.5rem] border transition-all ${
               group.is_duplicate 
                ? 'bg-amber-50/40 border-amber-200 border-dashed shadow-inner' 
                : 'bg-slate-50/50 border-transparent hover:bg-white hover:border-slate-100 hover:shadow-2xl'
             }`}>
                <div className="flex items-center justify-between mb-4">
                  <div className="flex flex-col">
                    <span className={`text-sm font-black tracking-tight ${group.is_duplicate ? 'text-amber-900' : 'text-slate-900'}`}>
                      {group.period}
                      {group.is_duplicate && (
                        <span className="mr-3 inline-flex items-center gap-1.5 px-3 py-1 rounded-xl bg-amber-200 text-[9px] text-amber-900 font-black tracking-tighter uppercase shadow-sm">
                          <Flame size={12} /> مكررة
                        </span>
                      )}
                    </span>
                    {group.items.length > 1 && <span className="text-[10px] text-slate-400 font-bold mt-2 italic opacity-80">رصد {group.items.length} حركات متلاحقة في دقيقة واحدة</span>}
                  </div>
                  <div className="flex flex-wrap justify-end gap-2 max-w-[140px]">
                    {group.items.map((it, i) => (
                      <span key={i} className={`text-[11px] font-black px-4 py-1.5 rounded-2xl shadow-sm border transition-all hover:scale-110 ${
                        group.is_duplicate 
                          ? 'bg-amber-100 text-amber-900 border-amber-300' 
                          : 'bg-white text-indigo-700 border-indigo-100'
                      }`}>
                        {it.time}
                      </span>
                    ))}
                  </div>
                </div>
                {group.is_duplicate && (
                   <div className="mt-4 flex items-center gap-3 p-3 bg-white/60 rounded-2xl border border-amber-200/50">
                      <AlertCircle size={14} className="text-amber-600 shrink-0" />
                      <p className="text-[10px] text-amber-800 font-bold leading-none opacity-80 uppercase tracking-tight">مستبعدة برمجياً لتجنب تضخم الكفاءة</p>
                   </div>
                )}
             </div>
          </div>
        ))}
      </div>

      <div className="mt-12 pt-10 border-t border-slate-50 text-right">
         <div className="flex items-center justify-between mb-8">
            <h6 className="text-[11px] font-black text-slate-400 uppercase tracking-widest">تغطية الـ 24 ساعة</h6>
            <span className="text-xs font-black text-indigo-600 bg-indigo-50 px-5 py-2 rounded-full border border-indigo-100">{capturedPeriods.size} / 5 فترات</span>
         </div>
         <div className="grid grid-cols-1 gap-2.5">
            {Object.keys(ATTENDANCE_RULES.TIME_PERIODS).map((period) => {
              const has = capturedPeriods.has(period);
              return (
                <div key={period} className={`flex items-center justify-between px-6 py-4 rounded-2xl border transition-all ${has ? 'bg-emerald-50/50 border-emerald-100' : 'bg-slate-50 border-slate-100 opacity-40 group-hover/shift:opacity-60 grayscale group-hover/shift:grayscale-0'}`}>
                   <span className={`text-[11px] font-black ${has ? 'text-emerald-800' : 'text-slate-500'}`}>{period}</span>
                   {has ? <div className="w-6 h-6 bg-emerald-500 rounded-full flex items-center justify-center text-white shadow-lg"><Check size={14} strokeWidth={4} /></div> : <X size={14} className="text-slate-300" />}
                </div>
              )
            })}
         </div>
      </div>

      {!isComplete && (
        <div className="mt-10 p-8 bg-gradient-to-br from-rose-600 to-rose-700 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden group/warning">
           <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 blur-2xl rounded-full translate-x-1/2 -translate-y-1/2 group-hover/warning:scale-150 transition-transform duration-700"></div>
           <div className="relative flex items-start gap-5">
              <AlertTriangle size={28} className="shrink-0 mt-1 animate-pulse" />
              <div>
                 <p className="text-sm font-black uppercase tracking-widest leading-none">وردية غير مكتملة</p>
                 <p className="text-[11px] font-medium opacity-90 mt-3 leading-relaxed">لم يستوفِ الموظف جميع الحركات الإلزامية المطلوبة لإغلاق الوردية وفقاً لمعايير المؤسسة.</p>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

