      {!isComplete && (
        <div className="mt-10 p-8 bg-gradient-to-br from-rose-600 to-rose-700 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden group/warning">
           <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 blur-2xl rounded-full translate-x-1/2 -translate-y-1/2 group-hover/warning:scale-150 transition-transform duration-700"></div>
           <div className="relative flex items-start gap-5">
              <AlertTriangle size={28} className="shrink-0 mt-1 animate-pulse" />
              <div>
                 <p className="text-sm font-black uppercase tracking-widest leading-none">وردية غير مكتملة</p>
                 <p className="text-[11px] font-medium opacity-90 mt-3 leading-relaxed">لم يستوفِ الموظف جميع الحركات الإلزامية المطلوبة لإغلاق الوردية وفقاً لمعايير المؤسسة.</p>
