import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary, ShiftReport } from "../types";

export const auditShiftWithAI = async (shift: ShiftReport): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const punchSummary = shift.punches_details
    .map(p => `${p.time} (${p.period}${p.is_duplicate ? '-مكرر' : ''})`)
    .join(' -> ');

  const prompt = `
    بصفتك مدقق حضور وانصراف، راجع الوردية التالية لنظام دوام (24 ساعة عمل / 72 ساعة استراحة):
    التاريخ: ${shift.shift_date}
    الحالة البرمجية: ${shift.status}
    تسلسل البصمات: ${punchSummary}

    المطلوب:
    قدم "رأي تدقيقي" مختصر جداً (سطر واحد) يوضح هل النقص نسيان بصمة أم تقصير في الدوام، وهل الفجوات الزمنية منطقية.
    مثال: "نقص في بصمة الوسط رغم تواجد الموظف المستمر لمدة 24 ساعة، الدوام يبدو مكتملاً فعلياً."
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0.1, maxOutputTokens: 100 }
    });
    return response.text?.trim() || "لا يوجد تعليق تدقيقي.";
  } catch (error) {
    return "تعذر التدقيق الذكي حالياً.";
  }
};

export const analyzeCompanyTrendsAI = async (employees: EmployeeSummary[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const stats = {
    total: employees.length,
    avgRate: employees.reduce((a, b) => a + b.completionRate, 0) / employees.length,
    missingMorning: employees.filter(e => e.shifts.some(s => s.punches_details.every(p => p.period !== 'دخول صباحي'))).length
  };

  const prompt = `حلل أداء ${stats.total} موظف بنظام 24 ساعة. المتوسط العام ${stats.avgRate}%. عدد الموظفين الذين يعانون من نقص الدخول الصباحي: ${stats.missingMorning}. قدم توصية إدارية واحدة حازمة.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "التحليل غير متاح.";
  } catch (error) {
    return "خطأ في الاتصال بالذكاء الاصطناعي.";
  }
};

import React, { useState, useMemo } from 'react';
import { 
  FileUp, Search, Users, BrainCircuit, X, Menu,
  Calendar, LayoutDashboard, Sparkles, ChevronDown, Check, Info, 
  Fingerprint, BarChart3, ShieldCheck, AlertTriangle, Flame, Zap, Target, Award,
  TrendingUp, UserCheck, AlertCircle, RefreshCcw
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { auditShiftWithAI, analyzeCompanyTrendsAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';
import { ATTENDANCE_RULES } from './constants';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [companyInsight, setCompanyInsight] = useState<string | null>(null);

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / totalShifts) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        // @ts-ignore
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        setEmployees(processExcelData(json));
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  return (
    <div className="min-h-screen bg-[#f4f7fa] text-slate-900 font-sans flex flex-col lg:flex-row rtl">
      {/* Sidebar - More Compact */}
      <aside className={`fixed inset-y-0 right-0 z-50 w-64 bg-[#0f172a] text-white transition-transform lg:static lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="h-full flex flex-col p-6">
          <div className="flex items-center gap-3 mb-10">
            <div className="p-2 bg-indigo-500 rounded-xl shadow-lg shadow-indigo-500/20">
              <BrainCircuit size={24} />
            </div>
            <h1 className="font-bold text-lg tracking-tight">بصمتي <span className="text-indigo-400">PRO</span></h1>
          </div>

          <nav className="space-y-1 flex-1">
            <SidebarLink icon={<LayoutDashboard size={18}/>} label="الرئيسية" active />
            <SidebarLink icon={<Users size={18}/>} label="الموظفون" />
            <SidebarLink icon={<BarChart3 size={18}/>} label="التقارير" />
          </nav>

          <div className="mt-auto pt-6 border-t border-slate-800">
            <label className="flex items-center justify-center gap-2 w-full p-3 bg-indigo-600 rounded-xl cursor-pointer hover:bg-indigo-700 transition-all font-bold text-sm">
              <FileUp size={18} />
              <span>رفع البيانات</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
            </label>
          </div>
        </div>
      </aside>

      {/* Content Area - Fluid Grid */}
      <main className="flex-1 flex flex-col max-h-screen overflow-hidden">
        <header className="bg-white border-b border-slate-200 px-6 py-4 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4 flex-1">
            <button className="lg:hidden p-2 text-slate-500" onClick={() => setIsSidebarOpen(!isSidebarOpen)}>
              <Menu size={20} />
            </button>
            <div className="relative w-full max-w-md">
              <Search className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
              <input 
                type="text" 
                placeholder="ابحث عن اسم أو رقم وظيفي..." 
                className="w-full bg-slate-100 border-none rounded-xl pr-10 pl-4 py-2 text-sm outline-none focus:ring-2 focus:ring-indigo-500/20"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
          </div>
          <button 
            onClick={() => analyzeCompanyTrendsAI(employees).then(setCompanyInsight)}
            disabled={employees.length === 0}
            className="flex items-center gap-2 px-4 py-2 bg-slate-900 text-white rounded-xl text-xs font-bold hover:bg-slate-800 transition-all disabled:opacity-30"
          >
            <Sparkles size={14} className="text-indigo-400" />
            تحليل المؤسسة
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-6 space-y-6 custom-scrollbar">
          {companyInsight && (
            <div className="bg-indigo-900 text-white p-6 rounded-2xl shadow-xl relative overflow-hidden animate-in fade-in slide-in-from-top-4">
              <div className="relative flex justify-between items-start">
                <div className="flex gap-4">
                  <BrainCircuit size={24} className="text-indigo-300 shrink-0" />
                  <p className="text-sm font-medium leading-relaxed">{companyInsight}</p>
                </div>
                <button onClick={() => setCompanyInsight(null)} className="p-1 hover:bg-white/10 rounded-lg"><X size={16} /></button>
              </div>
            </div>
          )}

          {stats && (
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              <StatItem title="الموظفون" value={stats.totalEmployees} icon={<Users size={16}/>} />
              <StatItem title="معدل الانضباط" value={`${stats.completionRate}%`} icon={<Target size={16}/>} color="emerald" />
              <StatItem title="إجمالي الحركات" value={stats.totalPunches} icon={<Fingerprint size={16}/>} color="amber" />
            </div>
          )}

          <div className="space-y-4">
            {isAnalyzing ? (
              <div className="flex flex-col items-center justify-center py-20 bg-white rounded-2xl border border-slate-200">
                <RefreshCcw className="text-indigo-600 animate-spin mb-4" size={32} />
                <p className="text-sm font-bold text-slate-500 uppercase tracking-widest">جاري تدقيق البيانات...</p>
              </div>
            ) : filteredEmployees.length > 0 ? (
              filteredEmployees.map((emp) => <EmployeeSection key={emp.id} employee={emp} />)
            ) : (
              <div className="text-center py-20 bg-white rounded-2xl border-2 border-dashed border-slate-200">
                <p className="text-slate-400 font-medium">يرجى رفع ملف السجل لبدء التدقيق الذكي</p>
              </div>
            )}
          </div>
        </div>
      </main>
    </div>
  );
};

const StatItem = ({ title, value, icon, color = "indigo" }: any) => (
  <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex items-center justify-between">
    <div>
      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1">{title}</p>
      <h4 className="text-xl font-black text-slate-900">{value}</h4>
    </div>
    <div className={`p-2 bg-${color}-50 text-${color}-600 rounded-lg`}>{icon}</div>
