      <div className="flex flex-wrap gap-2">
        {shift.punches_details.map((p, i) => (
          <div key={i} className={`px-2 py-1.5 rounded-lg border text-[10px] font-bold flex flex-col items-center min-w-[60px] ${p.is_duplicate ? 'bg-amber-50 border-amber-100 text-amber-700' : 'bg-white border-slate-100 text-slate-600'}`}>
            <span>{p.time}</span>
            <span className="text-[8px] opacity-60 truncate max-w-[50px]">{p.period}</span>
          </div>
        ))}
      </div>

      <div className="pt-3 border-t border-slate-50">
        {!aiAudit ? (
          <button 
            onClick={triggerAudit}
            className="w-full py-2 bg-indigo-50 text-indigo-600 rounded-xl text-[10px] font-bold hover:bg-indigo-100 transition-all flex items-center justify-center gap-2"
          >
            {loadingAudit ? <RefreshCcw size={12} className="animate-spin" /> : <Sparkles size={12} />}
            تدقيق البصمات بالذكاء الاصطناعي
          </button>
        ) : (
          <div className="bg-slate-900 text-white p-3 rounded-xl text-[10px] leading-relaxed relative group">
            <Sparkles size={10} className="absolute -top-1 -right-1 text-indigo-400" />
            <p className="font-medium italic">"{aiAudit}"</p>
          </div>
        )}
      </div>
    </div>
  );
};

