            className="flex items-center gap-2 px-4 py-2 bg-slate-900 text-white rounded-xl text-xs font-bold hover:bg-slate-800 transition-all disabled:opacity-30"
          >
            <Sparkles size={14} className="text-indigo-400" />
            تحليل المؤسسة
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-6 space-y-6 custom-scrollbar">
          {companyInsight && (
            <div className="bg-indigo-900 text-white p-6 rounded-2xl shadow-xl relative overflow-hidden animate-in fade-in slide-in-from-top-4">
              <div className="relative flex justify-between items-start">
                <div className="flex gap-4">
                  <BrainCircuit size={24} className="text-indigo-300 shrink-0" />
                  <p className="text-sm font-medium leading-relaxed">{companyInsight}</p>
                </div>
                <button onClick={() => setCompanyInsight(null)} className="p-1 hover:bg-white/10 rounded-lg"><X size={16} /></button>
              </div>
            </div>
          )}

          {stats && (
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              <StatItem title="الموظفون" value={stats.totalEmployees} icon={<Users size={16}/>} />
