const MiniStat = ({ label, value, color = "slate" }: any) => (
  <div className="text-center">
    <p className="text-[9px] font-bold text-slate-400 uppercase mb-0.5">{label}</p>
    <p className={`text-sm font-black text-${color}-600`}>{value}</p>
  </div>
);

const ShiftAuditCard = ({ shift }: { shift: ShiftReport }) => {
  const [aiAudit, setAiAudit] = useState<string | null>(null);
  const [loadingAudit, setLoadingAudit] = useState(false);

  const triggerAudit = async () => {
    setLoadingAudit(true);
    const res = await auditShiftWithAI(shift);
    setAiAudit(res);
    setLoadingAudit(false);
  };

  return (
    <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm space-y-4">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Calendar size={14} className="text-slate-400" />
          <span className="text-xs font-bold text-slate-700">{shift.shift_date}</span>
        </div>
        <span className={`px-2 py-1 rounded-lg text-[9px] font-bold uppercase ${shift.status === 'مكتملة' ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>
          {shift.status}
        </span>
      </div>

      <div className="flex flex-wrap gap-2">
        {shift.punches_details.map((p, i) => (
          <div key={i} className={`px-2 py-1.5 rounded-lg border text-[10px] font-bold flex flex-col items-center min-w-[60px] ${p.is_duplicate ? 'bg-amber-50 border-amber-100 text-amber-700' : 'bg-white border-slate-100 text-slate-600'}`}>
            <span>{p.time}</span>
            <span className="text-[8px] opacity-60 truncate max-w-[50px]">{p.period}</span>
          </div>
        ))}
      </div>

      <div className="pt-3 border-t border-slate-50">
        {!aiAudit ? (
          <button 
            onClick={triggerAudit}
            className="w-full py-2 bg-indigo-50 text-indigo-600 rounded-xl text-[10px] font-bold hover:bg-indigo-100 transition-all flex items-center justify-center gap-2"
          >
            {loadingAudit ? <RefreshCcw size={12} className="animate-spin" /> : <Sparkles size={12} />}
            تدقيق البصمات بالذكاء الاصطناعي
          </button>
        ) : (
          <div className="bg-slate-900 text-white p-3 rounded-xl text-[10px] leading-relaxed relative group">
            <Sparkles size={10} className="absolute -top-1 -right-1 text-indigo-400" />
            <p className="font-medium italic">"{aiAudit}"</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default App;

import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary, ShiftReport } from "../types";

export const auditShiftWithAI = async (shift: ShiftReport): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const punchSummary = shift.punches_details
    .map(p => `${p.time} (${p.period}${p.is_duplicate ? '-مكرر' : ''})`)
    .join(' -> ');

  const prompt = `
    بصفتك مدقق حضور وانصراف، راجع الوردية التالية لنظام دوام (24 ساعة عمل / 72 ساعة استراحة):
    التاريخ: ${shift.shift_date}
    الحالة البرمجية: ${shift.status}
    تسلسل البصمات: ${punchSummary}

    المطلوب:
    قدم "رأي تدقيقي" مختصر جداً (سطر واحد) يوضح هل النقص نسيان بصمة أم تقصير في الدوام، وهل الفجوات الزمنية منطقية.
    مثال: "نقص في بصمة الوسط رغم تواجد الموظف المستمر لمدة 24 ساعة، الدوام يبدو مكتملاً فعلياً."
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      // Fix: When setting maxOutputTokens, you must also set thinkingBudget to reserve tokens for final response
      config: { 
        temperature: 0.1, 
        maxOutputTokens: 100,
        thinkingConfig: { thinkingBudget: 50 } 
      }
    });
    return response.text?.trim() || "لا يوجد تعليق تدقيقي.";
  } catch (error) {
    return "تعذر التدقيق الذكي حالياً.";
  }
};

export const analyzeCompanyTrendsAI = async (employees: EmployeeSummary[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const stats = {
    total: employees.length,
    avgRate: employees.reduce((a, b) => a + b.completionRate, 0) / employees.length,
    missingMorning: employees.filter(e => e.shifts.some(s => s.punches_details.every(p => p.period !== 'دخول صباحي'))).length
  };

  const prompt = `حلل أداء ${stats.total} موظف بنظام 24 ساعة. المتوسط العام ${stats.avgRate}%. عدد الموظفين الذين يعانون من نقص الدخول الصباحي: ${stats.missingMorning}. قدم توصية إدارية واحدة حازمة.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "التحليل غير متاح.";
  } catch (error) {
    return "خطأ في الاتصال بالذكاء الاصطناعي.";
  }
};

