import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary, ShiftReport } from "../types";

export const auditShiftWithAI = async (shift: ShiftReport): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const punchSummary = shift.punches_details
    .map(p => `${p.time} (${p.period}${p.is_duplicate ? '-مكرر' : ''})`)
    .join(' -> ');

  const prompt = `
    بصفتك مدقق حضور وانصراف خبير، قم بتحليل وردية العمل التالية لنظام (24 ساعة عمل / 72 ساعة استراحة):

    التاريخ: ${shift.shift_date}
    الحالة التقنية: ${shift.status} (بصمات مكتملة/ناقصة)
    تسلسل حركات البصمة: ${punchSummary}

    المهمة:
    1. حدد ما إذا كانت الفجوات الزمنية بين البصمات تدل على تواجد الموظف الفعلي أم خروجه المبكر.
    2. هل النقص في البصمات (إن وجد) هو نسيان "بصمة إدارية" أم غياب فعلي عن الموقع؟
    3. إذا كانت البصمات تدور حول الـ 24 ساعة (مثلاً من 8 صباحاً إلى 8 صباحاً اليوم التالي)، فهل الدوام مكتملاً فعلياً رغم أي نقص تقني؟

    المخرج:
    قدم حكماً تدقيقياً حازماً ومختصراً جداً (سطر واحد فقط) باللغة العربية.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        temperature: 0.2, 
        maxOutputTokens: 120,
        thinkingConfig: { thinkingBudget: 50 } 
      }
    });
    return response.text?.trim() || "لا توجد ملاحظات تدقيقية لهذه الوردية.";
  } catch (error) {
    console.error("Audit Error:", error);
    return "تعذر التدقيق الذكي حالياً بسبب خطأ فني.";
  }
};

export const analyzeCompanyTrendsAI = async (employees: EmployeeSummary[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const stats = {
    total: employees.length,
    avgRate: employees.reduce((a, b) => a + b.completionRate, 0) / employees.length,
    missingMorning: employees.filter(e => e.shifts.some(s => s.punches_details.every(p => p.period !== 'دخول صباحي'))).length
  };

  const prompt = `بصفتك مستشاراً إدارياً، حلل أداء ${stats.total} موظفاً يعملون بنظام الورديات الطويلة. المتوسط العام للانضباط هو ${stats.avgRate.toFixed(1)}%. هناك ${stats.missingMorning} موظف لديهم خلل في "دخول الصباح". قدم رؤية استراتيجية لتحسين ثقافة الالتزام بكلمات قليلة وقوية.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "لا توجد رؤية تحليلية متاحة.";
  } catch (error) {
    return "خطأ في الاتصال بنظام التحليل الذكي.";
  }
};

