import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary, ShiftReport } from "../types";

export const auditEmployeeFullPerformanceAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // تلخيص البيانات لتقليل استهلاك التوكنات وضمان البقاء في النطاق الذكي
  const performanceSummary = employee.shifts.map(s => {
    const punchTimes = s.punches_details.map(p => p.time).join(', ');
    return `تاريخ ${s.shift_date}: [${punchTimes}] - الحالة: ${s.status}`;
  }).join('\n');

  const prompt = `
    بصفتك كبير مدققي الموارد البشرية، قم بتحليل سجل الحضور الكامل للموظف التالي (نظام 24 ساعة عمل):
    الاسم: ${employee.name}
    إجمالي الورديات: ${employee.shifts.length}
    معدل الانضباط التقني: ${employee.completionRate}%
    سجل الورديات:
    ${performanceSummary}

    المطلوب:
    1. حدد الأنماط المتكررة (مثلاً: هل ينسى دائماً بصمة معينة؟).
    2. هل الفجوات الزمنية تشير إلى "تلاعب" أم "نسيان إداري" أم "التزام فعلي"؟
    3. قدم حكماً نهائياً (توصية) للإدارة حول مصداقية دوام هذا الموظف.

    القيود:
    - كن صارماً جداً ودقيقاً.
    - المخرج يجب أن يكون فقرة واحدة مركزة جداً باللغة العربية.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        temperature: 0.1, 
        maxOutputTokens: 250,
        thinkingConfig: { thinkingBudget: 100 } 
      }
    });
    return response.text?.trim() || "تعذر استخلاص نتيجة تدقيقية.";
  } catch (error) {
    return "خطأ في الاتصال بالمدقق الذكي.";
  }
};

export const analyzeCompanyTrendsAI = async (employees: EmployeeSummary[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const stats = {
    total: employees.length,
    avgRate: employees.reduce((a, b) => a + b.completionRate, 0) / (employees.length || 1),
  };

  const prompt = `حلل أداء المؤسسة لـ ${stats.total} موظف. متوسط الانضباط ${stats.avgRate.toFixed(1)}%. قدم رؤية استراتيجية لتحسين الأداء العام بنظام الـ 24 ساعة. سطر واحد فقط.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { maxOutputTokens: 100 }
    });
    return response.text || "التحليل الاستراتيجي غير متاح.";
  } catch (error) {
    return "خطأ في تحليل البيانات الجماعية.";
  }
};

