            <div>
              <h1 className="font-extrabold text-xl tracking-tight leading-none">بصمتي <span className="text-indigo-400">PRO</span></h1>
              <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1">Audit Engine v3</p>
            </div>
          </div>

          <nav className="space-y-2 flex-1">
            <SidebarLink icon={<LayoutDashboard size={20}/>} label="لوحة التحكم" active />
            <SidebarLink icon={<Users size={20}/>} label="إدارة الموظفين" />
            <SidebarLink icon={<BarChart3 size={20}/>} label="تقارير الأداء" />
          </nav>

          <div className="mt-auto space-y-6">
             <div className="p-5 bg-white/5 rounded-2xl border border-white/10">
                <div className="flex items-center gap-2 mb-2 text-indigo-400">
                  <ShieldCheck size={16} />
                  <span className="text-[10px] font-black uppercase tracking-widest">التدقيق المتقدم نشط</span>
                </div>
                <p className="text-[10px] text-slate-400 leading-relaxed">يتم الكشف تلقائياً عن مسميات البصمات المفقودة في كل وردية.</p>
             </div>
            <label className="flex items-center justify-center gap-3 w-full p-4 bg-indigo-600 rounded-2xl cursor-pointer hover:bg-indigo-700 transition-all font-black text-sm text-white shadow-lg shadow-indigo-900/40 active:scale-95">
              <FileUp size={20} />
              <span>رفع سجل البصمة</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
            </label>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden">
        <header className="bg-white/80 backdrop-blur-md border-b border-slate-200 px-8 py-5 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-6 flex-1">
            <button className="lg:hidden p-2 text-slate-500" onClick={() => setIsSidebarOpen(!isSidebarOpen)}>
              <Menu size={24} />
            </button>
            <div className="relative w-full max-w-xl">
              <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input 
                type="text" 
                placeholder="البحث بالاسم أو الرقم الوظيفي..." 
                className="w-full bg-slate-100 border-none rounded-2xl pr-12 pl-4 py-3 text-sm outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all font-medium"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
          </div>
          <button 
            onClick={() => analyzeCompanyTrendsAI(employees).then(setCompanyInsight)}
            disabled={employees.length === 0}
            className="flex items-center gap-2 px-6 py-3 bg-slate-900 text-white rounded-2xl text-xs font-black hover:bg-slate-800 transition-all active:scale-95 disabled:opacity-20 mr-4 shadow-lg"
          >
            <Sparkles size={16} className="text-indigo-400" />
            تحليل المؤسسة
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-6 lg:p-10 space-y-10 custom-scrollbar">
          {companyInsight && (
            <div className="bg-gradient-to-r from-indigo-900 to-slate-900 text-white p-8 rounded-[2.5rem] shadow-2xl relative overflow-hidden animate-in fade-in slide-in-from-top-4 duration-500">
               <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/10 blur-[80px] rounded-full"></div>
              <div className="relative flex justify-between items-center">
                <div className="flex gap-5 items-center">
                  <div className="p-3 bg-white/10 rounded-2xl backdrop-blur-xl">
                    <BrainCircuit size={32} className="text-indigo-300" />
                  </div>
                  <div>
                    <h3 className="text-lg font-black tracking-tight">الرؤية الاستراتيجية الذكية</h3>
                    <p className="text-indigo-100/70 text-sm mt-1 font-medium">{companyInsight}</p>
                  </div>
                </div>
                <button onClick={() => setCompanyInsight(null)} className="p-2 hover:bg-white/10 rounded-full transition-colors"><X size={20} /></button>
              </div>
            </div>
          )}

          {stats && (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              <StatBox title="القوى العاملة" value={stats.totalEmployees} icon={<Users size={20}/>} color="indigo" />
              <StatBox title="معدل الانضباط العام" value={`${stats.completionRate}%`} icon={<Target size={20}/>} color="emerald" />
              <StatBox title="حركات البصمة الموثقة" value={stats.totalPunches.toLocaleString()} icon={<Fingerprint size={20}/>} color="amber" />
            </div>
