  <button className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl transition-all font-black text-sm tracking-tight ${active ? 'bg-indigo-600 text-white shadow-2xl shadow-indigo-600/30 translate-x-1' : 'text-slate-500 hover:bg-white/5 hover:text-slate-200'}`}>
    {icon} <span>{label}</span>
  </button>
);

