          </div>
        </div>

        <div className="flex items-center gap-12 px-12 border-x border-slate-100 hidden 2xl:flex">
          <BigMiniStat label="معدل الانضباط" value={`${employee.completionRate}%`} color={employee.completionRate > 80 ? "emerald" : "rose"} />
          <BigMiniStat label="كفاءة البصمات" value={`${employee.performanceScore}%`} />
