            <div className="flex items-center gap-4">
              <div className="p-3 bg-indigo-50 text-indigo-600 rounded-2xl">
                <History size={24} />
              </div>
              <div>
                <h4 className="font-black text-slate-800 text-lg">سجل الحركات التفصيلي</h4>
                <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">تحليل ومراجعة كافة الورديات والأنماط</p>
