const BigMiniStat = ({ label, value, color = "slate" }: any) => {
  const textColors: any = { emerald: "text-emerald-600", rose: "text-rose-600", slate: "text-slate-900" };
  return (
    <div className="text-right">
      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{label}</p>
      <p className={`text-3xl font-black ${textColors[color]}`}>{value}</p>
    </div>
  );
};

const ShiftAuditCard = ({ shift }: { shift: ShiftReport }) => {
  const groupedPunches = useMemo(() => {
    const groups: { period: string; punches: PunchDetail[] }[] = [];
    shift.punches_details.forEach((p) => {
      const last = groups[groups.length - 1];
      if (last && last.period === p.period) {
        last.punches.push(p);
      } else {
        groups.push({ period: p.period, punches: [p] });
      }
    });
    return groups;
  }, [shift.punches_details]);

  const isComplete = shift.status === 'مكتملة';

  // تحديد البصمات الناقصة بناءً على القواعد الإلزامية الخمس
  const missingPunches = useMemo(() => {
    if (isComplete) return [];
    const required = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
    const present = new Set(shift.punches_details.filter(p => !p.is_duplicate).map(p => p.period));
    return required.filter(r => !present.has(r));
  }, [shift.punches_details, isComplete]);

  return (
    <div className={`bg-white p-6 rounded-[2.5rem] border shadow-sm transition-all duration-500 hover:shadow-xl group/card flex flex-col ${isComplete ? 'border-emerald-50 hover:border-emerald-200' : 'border-rose-50 hover:border-rose-200'}`}>
      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-slate-100 rounded-xl text-slate-500 group-hover/card:bg-indigo-50 group-hover/card:text-indigo-600 transition-colors">
            <Calendar size={18} />
          </div>
          <div>
            <span className="text-sm font-black text-slate-800 block leading-none">{shift.shift_date}</span>
            <span className="text-[10px] font-bold text-slate-400 mt-1 block uppercase">{new Date(shift.shift_date).toLocaleDateString('ar-SA', { weekday: 'long' })}</span>
          </div>
        </div>
        <div className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest flex items-center gap-2 ${isComplete ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-200' : 'bg-rose-500 text-white shadow-lg shadow-rose-200'}`}>
          {isComplete ? <Check size={12} strokeWidth={4} /> : <AlertTriangle size={12} strokeWidth={4} />}
          {shift.status}
        </div>
      </div>

      <div className="space-y-4 relative flex-1">
        <div className="absolute right-4 inset-y-0 w-0.5 bg-slate-100"></div>
        {groupedPunches.map((group, idx) => (
          <div key={idx} className="relative pr-10">
            <div className={`absolute right-2 top-1 w-4 h-4 rounded-full border-4 border-white shadow-md z-10 ${group.period === 'غير مصنفة' ? 'bg-slate-300' : 'bg-indigo-600'}`}></div>
            <div className="bg-slate-50/50 p-4 rounded-2xl border border-transparent hover:bg-white hover:border-slate-100 hover:shadow-md transition-all">
              <div className="flex items-center justify-between mb-3">
                 <span className="text-[11px] font-black text-slate-600 uppercase tracking-tight">{group.period}</span>
                 {group.punches.length > 1 && <span className="text-[9px] font-bold text-indigo-400 bg-indigo-50 px-2 py-0.5 rounded-md">تجميع {group.punches.length} بصمات</span>}
              </div>
              <div className="flex flex-wrap gap-2">
                {group.punches.map((p, pIdx) => (
                  <div key={pIdx} className={`px-3 py-1.5 rounded-xl text-[10px] font-black flex items-center gap-2 border transition-all ${p.is_duplicate ? 'bg-amber-50 border-amber-100 text-amber-600 line-through opacity-60' : 'bg-white border-slate-200 text-slate-700 shadow-sm'}`}>
                    {p.is_duplicate ? <Flame size={12} /> : <Clock size={12} className="text-slate-300" />}
                    {p.time}
                  </div>
                ))}
              </div>
            </div>
          </div>
        ))}
      </div>

      {!isComplete && (
        <div className="mt-6 p-5 bg-rose-50 rounded-[1.5rem] border border-rose-100 flex flex-col gap-2">
          <div className="flex items-center gap-2 text-rose-600">
            <AlertCircle size={18} className="shrink-0" />
            <span className="text-[11px] font-black uppercase tracking-tight">نقص في الحركات الإلزامية:</span>
          </div>
          <div className="flex flex-wrap gap-2">
            {missingPunches.map((m, idx) => (
              <span key={idx} className="text-[10px] bg-white px-2 py-1 rounded-lg border border-rose-200 text-rose-700 font-bold shadow-sm">
                {m}
              </span>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

