const BigMiniStat = ({ label, value, color = "slate" }: any) => {
  const textColors: any = { emerald: "text-emerald-600", rose: "text-rose-600", slate: "text-slate-900" };
  return (
    <div className="text-right">
      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{label}</p>
      <p className={`text-3xl font-black ${textColors[color]}`}>{value}</p>
    </div>
  );
};

const ShiftAuditCard = ({ shift }: { shift: ShiftReport }) => {
  const groupedPunches = useMemo(() => {
    const groups: { period: string; punches: PunchDetail[] }[] = [];
    shift.punches_details.forEach((p) => {
      const last = groups[groups.length - 1];
      if (last && last.period === p.period) {
        last.punches.push(p);
      } else {
        groups.push({ period: p.period, punches: [p] });
      }
    });
    return groups;
  }, [shift.punches_details]);

  const isComplete = shift.status === 'مكتملة';

  // تحديد البصمات الناقصة بناءً على القواعد الإلزامية الخمس المحدثة
  const missingPunches = useMemo(() => {
    if (isComplete) return [];
    const required = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
    const present = new Set(shift.punches_details.filter(p => !p.is_duplicate).map(p => p.period));
    return required.filter(r => !present.has(r));
  }, [shift.punches_details, isComplete]);

  // الكشف عن الفجوات الزمنية الكبيرة داخل الوردية الواحدة
  const largeGaps = useMemo(() => {
    const gaps: number[] = [];
    for (let i = 1; i < shift.punches_details.length; i++) {
      const diffHours = (shift.punches_details[i].raw_datetime.getTime() - shift.punches_details[i-1].raw_datetime.getTime()) / (1000 * 3600);
      // فجوة تزيد عن 12 ساعة في وردية واحدة تعتبر تنبيهاً
      if (diffHours > 12) gaps.push(i);
    }
    return gaps;
  }, [shift.punches_details]);

  return (
    <div className={`bg-white p-8 rounded-[3rem] border shadow-sm transition-all duration-500 hover:shadow-2xl group/card flex flex-col relative overflow-hidden ${isComplete ? 'border-emerald-50 hover:border-emerald-200' : 'border-rose-50 hover:border-rose-200'}`}>
      {/* Visual background indicator for missing punches */}
      {!isComplete && <div className="absolute top-0 right-0 w-2 h-full bg-rose-400/20"></div>}

      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-slate-100 rounded-2xl text-slate-500 group-hover/card:bg-indigo-600 group-hover/card:text-white transition-all duration-500">
            <Calendar size={22} />
          </div>
          <div>
            <span className="text-base font-black text-slate-800 block leading-none">{shift.shift_date}</span>
            <span className="text-[11px] font-bold text-slate-400 mt-2 block uppercase tracking-wide">{new Date(shift.shift_date).toLocaleDateString('ar-SA', { weekday: 'long' })}</span>
          </div>
        </div>
        <div className={`px-5 py-2 rounded-full text-[11px] font-black uppercase tracking-[0.1em] flex items-center gap-2.5 shadow-sm ${isComplete ? 'bg-emerald-500 text-white shadow-emerald-200' : 'bg-rose-500 text-white shadow-rose-200'}`}>
          {isComplete ? <Check size={14} strokeWidth={4} /> : <AlertTriangle size={14} strokeWidth={4} />}
          {shift.status}
        </div>
      </div>

      <div className="space-y-6 relative flex-1">
        <div className="absolute right-4 inset-y-0 w-1 bg-slate-100/50 rounded-full"></div>
        {groupedPunches.map((group, idx) => {
          const isInvalid = group.period === 'غير مصنفة';
          return (
            <div key={idx} className="relative pr-12">
              <div className={`absolute right-[0.625rem] top-2 w-5 h-5 rounded-full border-4 border-white shadow-lg z-10 transition-colors duration-500 ${isInvalid ? 'bg-amber-500 animate-pulse' : 'bg-indigo-600'}`}></div>
              <div className={`p-5 rounded-[2rem] border transition-all duration-500 ${isInvalid ? 'bg-amber-50 border-amber-100' : 'bg-slate-50/50 border-transparent hover:bg-white hover:border-slate-100 hover:shadow-xl'}`}>
                <div className="flex items-center justify-between mb-4">
                   <div className="flex items-center gap-2">
                     <span className={`text-[12px] font-black uppercase tracking-tight ${isInvalid ? 'text-amber-700' : 'text-slate-600'}`}>{group.period}</span>
                     {/* Fix: Wrapped AlertCircle in a span with title to avoid TypeScript prop error on the icon component itself */}
                     {isInvalid && <span title="بصمة خارج النطاقات الزمنية المحددة"><AlertCircle size={14} className="text-amber-600" /></span>}
                   </div>
                   {group.punches.length > 1 && <span className="text-[10px] font-black text-indigo-500 bg-indigo-50 px-3 py-1 rounded-xl">مجمعة ({group.punches.length})</span>}
                </div>
                <div className="flex flex-wrap gap-2.5">
                  {group.punches.map((p, pIdx) => (
                    <div key={pIdx} className={`px-4 py-2 rounded-2xl text-[11px] font-black flex items-center gap-2 border transition-all relative ${p.is_duplicate ? 'bg-slate-200/50 border-slate-200 text-slate-400 line-through' : 'bg-white border-slate-200 text-slate-700 shadow-sm hover:border-indigo-400'}`}>
                      {p.is_duplicate ? <Flame size={14} /> : <Clock size={14} className="text-slate-400" />}
                      {p.time}
                      {/* Check if this punch is the start of a large gap */}
                      {shift.punches_details.findIndex(pd => pd === p) > 0 && largeGaps.includes(shift.punches_details.findIndex(pd => pd === p)) && (
                        <div className="absolute -top-2 -left-2 p-1 bg-rose-500 text-white rounded-full shadow-lg" title="فجوة زمنية كبيرة">
                           <Timer size={10} />
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {!isComplete && (
        <div className="mt-8 p-6 bg-rose-50 rounded-[2.5rem] border border-rose-100 flex flex-col gap-4 shadow-inner">
          <div className="flex items-center gap-3 text-rose-600">
            <AlertCircle size={22} className="shrink-0" />
            <span className="text-xs font-black uppercase tracking-[0.1em]">الحركات الإلزامية المفقودة:</span>
          </div>
          <div className="flex flex-wrap gap-2.5">
            {missingPunches.map((m, idx) => (
              <span key={idx} className="text-[11px] bg-white px-4 py-2 rounded-2xl border border-rose-200 text-rose-700 font-black shadow-sm flex items-center gap-2">
                <div className="w-1.5 h-1.5 bg-rose-400 rounded-full"></div>
                {m}
              </span>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, X, Menu,
  Calendar, LayoutDashboard, Sparkles, ChevronDown, Check, Info, 
  Fingerprint, BarChart3, ShieldCheck, AlertTriangle, Flame, Zap, Target, Award,
  TrendingUp, UserCheck, AlertCircle, RefreshCcw, Layers, Clock, ShieldAlert,
  History, Timer, LogOut
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { auditEmployeeFullPerformanceAI, analyzeCompanyTrendsAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';
import { ATTENDANCE_RULES } from './constants';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
