            </div>
          </div>

          <nav className="space-y-2 flex-1">
            <SidebarLink icon={<LayoutDashboard size={20}/>} label="لوحة التحكم" active />
            <SidebarLink icon={<Users size={20}/>} label="إدارة الموظفين" />
            <SidebarLink icon={<BarChart3 size={20}/>} label="تقارير الأداء" />
          </nav>

          <div className="mt-auto space-y-6">
             <div className="p-5 bg-white/5 rounded-2xl border border-white/10">
                <div className="flex items-center gap-2 mb-2 text-indigo-400">
                  <ShieldCheck size={16} />
                  <span className="text-[10px] font-black uppercase tracking-widest">تحليل النواقص نشط</span>
                </div>
                <p className="text-[10px] text-slate-400 leading-relaxed">يتم استثناء التواريخ الفارغة وتحديد أنواع البصمات المفقودة بدقة متناهية.</p>
             </div>
            <label className="flex items-center justify-center gap-3 w-full p-4 bg-indigo-600 rounded-2xl cursor-pointer hover:bg-indigo-700 transition-all font-black text-sm text-white shadow-lg shadow-indigo-900/40 active:scale-95">
