            onClick={() => analyzeCompanyTrendsAI(employees).then(setCompanyInsight)}
            disabled={employees.length === 0}
            className="flex items-center gap-2 px-6 py-3 bg-slate-900 text-white rounded-2xl text-xs font-black hover:bg-slate-800 transition-all active:scale-95 disabled:opacity-20 mr-4 shadow-lg shadow-slate-900/10"
          >
            <Sparkles size={16} className="text-indigo-400" />
            تحليل المؤسسة
