                <button onClick={() => setCompanyInsight(null)} className="p-2 hover:bg-white/10 rounded-full transition-colors"><X size={20} /></button>
              </div>
            </div>
          )}

          {stats && (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              <StatBox title="القوى العاملة" value={stats.totalEmployees} icon={<Users size={20}/>} color="indigo" />
              <StatBox title="معدل الانضباط العام" value={`${stats.completionRate}%`} icon={<Target size={20}/>} color="emerald" />
              <StatBox title="حركات البصمة الموثقة" value={stats.totalPunches.toLocaleString()} icon={<Fingerprint size={20}/>} color="amber" />
