          <div className="space-y-8">
            {isAnalyzing ? (
              <div className="flex flex-col items-center justify-center py-32 bg-white rounded-[3rem] border border-slate-200 shadow-sm relative overflow-hidden">
                <div className="absolute inset-0 bg-indigo-50/30 animate-pulse"></div>
                <RefreshCcw className="text-indigo-600 animate-spin mb-6 relative" size={48} />
                <p className="text-xl font-black text-slate-700 relative uppercase tracking-widest">جاري معالجة وتدقيق البيانات...</p>
              </div>
            ) : filteredEmployees.length > 0 ? (
