import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary } from "../types";

// محرك التدقيق الفردي المدمج
export const auditEmployeeFullPerformanceAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // ضغط البيانات: نرسل فقط الخلاصة الرقمية والأنماط المفقودة لتوفير التوكن
  const missingSummary = employee.shifts
    .filter(s => s.status === 'ناقصة')
    .map(s => s.shift_date)
    .join(', ');

  const prompt = `
    حلل أداء الموظف ${employee.name}:
    - الانضباط: ${employee.completionRate}%
    - الكفاءة: ${employee.performanceScore}%
    - تواريخ النقص: [${missingSummary}]
    المطلوب: جملة واحدة فقط تشخص المشكلة وتوصي بحل. (بالعربية)
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        temperature: 0.1, 
        maxOutputTokens: 100 // تقييد حاد لتوفير التوكن
      }
    });
    return response.text?.trim() || "لا توجد توصية ذكية حالياً.";
  } catch (error) {
    return "نظام التدقيق مشغول حالياً.";
  }
};

// محرك التحليل الجماعي (لأكثر من 400 موظف)
export const analyzeCompanyTrendsAI = async (employees: EmployeeSummary[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // استراتيجية الضغط الإحصائي: تحويل 400 موظف إلى مصفوفة بيانات مركزة
  const total = employees.length;
  const avgCompletion = employees.reduce((a, b) => a + b.completionRate, 0) / total;
  const topPerformers = employees.filter(e => e.completionRate >= 95).length;
  const criticalPerformers = employees.filter(e => e.completionRate < 50).length;

  // حساب أكثر البصمات المفقودة شيوعاً برمجياً قبل الإرسال للذكاء الاصطناعي لتوفير التوكن
  const missingCounts: Record<string, number> = {};
  employees.forEach(e => {
    e.shifts.forEach(s => {
      const required = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
      const present = new Set(s.punches_details.map(p => p.period));
      required.forEach(r => {
        if (!present.has(r)) missingCounts[r] = (missingCounts[r] || 0) + 1;
      });
    });
  });
  const mostMissing = Object.entries(missingCounts).sort((a,b) => b[1] - a[1])[0]?.[0] || "لا يوجد";

  const prompt = `
    بصفتك مستشاراً ذكياً، حلل بيانات المؤسسة التالية:
    - إجمالي الموظفين: ${total}
    - معدل الانضباط العام: ${avgCompletion.toFixed(1)}%
    - المتميزون: ${topPerformers}
    - حالات حرجة: ${criticalPerformers}
    - البصمة الأكثر نقصاً: ${mostMissing}

    المطلوب: رؤية استراتيجية من سطر واحد فقط للمدير التنفيذي. (بالعربية)
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        maxOutputTokens: 120,
        temperature: 0.2
      }
    });
    return response.text?.trim() || "التحليل الاستراتيجي جاهز للمراجعة.";
  } catch (error) {
    return "خطأ في معالجة الدفعة الكبيرة.";
  }
};

