                <div className="flex flex-wrap gap-2">
                  {group.punches.map((p, pIdx) => (
                    <div key={pIdx} className={`px-3 py-1.5 rounded-xl text-[10px] font-black border ${p.is_duplicate ? 'bg-rose-50 border-rose-100 text-rose-300 line-through' : 'bg-white border-slate-200 text-slate-700 shadow-sm'}`}>
