            className="p-4 bg-indigo-50 text-indigo-600 rounded-2xl hover:bg-indigo-600 hover:text-white transition-all disabled:opacity-50"
          >
            {loadingAudit ? <RefreshCcw size={20} className="animate-spin" /> : <Sparkles size={20} />}
          </button>
          <div className="p-4 bg-slate-50 rounded-2xl text-slate-400">
            <ChevronDown size={24} className={`transition-transform ${isExpanded ? 'rotate-180' : ''}`} />
