            <div className="mb-8 p-6 bg-indigo-600 text-white rounded-[2rem] shadow-xl flex items-center gap-5 animate-in slide-in-from-right-4">
              <div className="p-3 bg-white/20 rounded-xl backdrop-blur-md">
