const BigMiniStat = ({ label, value, color = "slate" }: any) => {
  const textColors: any = { emerald: "text-emerald-600", rose: "text-rose-600", slate: "text-slate-900" };
  return (
    <div className="text-right">
      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{label}</p>
      <p className={`text-3xl font-black ${textColors[color]}`}>{value}</p>
    </div>
  );
};

const ShiftAuditCard = ({ shift }: { shift: ShiftReport }) => {
  const groupedPunches = useMemo(() => {
    const groups: { period: string; punches: PunchDetail[] }[] = [];
    shift.punches_details.forEach((p) => {
      const last = groups[groups.length - 1];
      if (last && last.period === p.period) {
        last.punches.push(p);
      } else {
        groups.push({ period: p.period, punches: [p] });
      }
    });
    return groups;
  }, [shift.punches_details]);

  const isComplete = shift.status === 'مكتملة';
  const missingPunches = useMemo(() => {
    if (isComplete) return [];
    const required = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
    const present = new Set(shift.punches_details.filter(p => !p.is_duplicate).map(p => p.period));
    return required.filter(r => !present.has(r));
  }, [shift.punches_details, isComplete]);

  return (
    <div className={`bg-white p-8 rounded-[3rem] border shadow-sm transition-all hover:shadow-2xl flex flex-col relative overflow-hidden ${isComplete ? 'border-emerald-50 hover:border-emerald-200' : 'border-rose-50 hover:border-rose-200'}`}>
      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-slate-100 rounded-2xl text-slate-500 group-hover/card:bg-indigo-600 group-hover/card:text-white transition-all">
            <Calendar size={22} />
          </div>
          <div>
            <span className="text-base font-black text-slate-800 block">{shift.shift_date}</span>
            <span className="text-[11px] font-bold text-slate-400 mt-1 uppercase">{new Date(shift.shift_date).toLocaleDateString('ar-SA', { weekday: 'long' })}</span>
          </div>
        </div>
        <div className={`px-5 py-2 rounded-full text-[11px] font-black flex items-center gap-2 ${isComplete ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
          {isComplete ? <Check size={14} /> : <AlertTriangle size={14} />}
          {shift.status}
        </div>
      </div>

      <div className="space-y-6 flex-1">
        {groupedPunches.map((group, idx) => {
          const isExit = group.period === 'بصمة خروج';
          const isInvalid = group.period === 'غير مصنفة';
          return (
            <div key={idx} className="relative pr-10">
              <div className={`absolute right-0 top-2 w-3 h-3 rounded-full ${isInvalid ? 'bg-amber-400' : isExit ? 'bg-emerald-500' : 'bg-indigo-500'}`}></div>
              <div className={`p-4 rounded-[1.5rem] border ${isInvalid ? 'bg-amber-50 border-amber-100' : 'bg-slate-50/50 border-transparent hover:bg-white hover:border-slate-100 transition-all'}`}>
                <div className="flex items-center justify-between mb-3">
                   <span className={`text-[11px] font-black uppercase ${isInvalid ? 'text-amber-700' : isExit ? 'text-emerald-700' : 'text-slate-600'}`}>{group.period}</span>
                   {group.punches.length > 1 && <span className="text-[9px] font-black text-indigo-400">مجمعة ({group.punches.length})</span>}
                </div>
                <div className="flex flex-wrap gap-2.5">
                  {group.punches.map((p, pIdx) => (
                    <div 
                      key={pIdx} 
                      className={`px-4 py-2 rounded-xl text-[10px] font-black border-2 transition-all relative flex items-center gap-2 shadow-sm ${
                        p.is_duplicate 
                          ? 'bg-rose-100 border-rose-500 text-rose-600 line-through ring-2 ring-rose-200 ring-offset-1 opacity-90 scale-95 origin-right' 
                          : 'bg-white border-slate-200 text-slate-700 hover:border-indigo-300'
                      }`}
                    >
                      {p.is_duplicate && <Flame size={12} className="text-rose-500 shrink-0 animate-pulse" />}
                      {p.time}
                      {p.is_duplicate && <span className="text-[8px] font-bold opacity-60 mr-1">مكرر</span>}
                    </div>
                  ))}
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {!isComplete && (
        <div className="mt-8 p-5 bg-rose-50 rounded-[2rem] border border-rose-100">
          <div className="flex items-center gap-2 text-rose-600 mb-3">
            <AlertCircle size={18} />
            <span className="text-xs font-black uppercase tracking-tight">النواقص التقنية:</span>
          </div>
          <div className="flex flex-wrap gap-2">
            {missingPunches.map((m, idx) => (
              <span key={idx} className="text-[10px] bg-white px-3 py-1.5 rounded-xl border border-rose-200 text-rose-700 font-bold shadow-sm">
                {m}
              </span>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

