    const present = new Set(shift.punches_details.filter(p => !p.is_duplicate).map(p => p.period));
    return required.filter(r => !present.has(r));
  }, [shift.punches_details, isComplete]);

  return (
    <div className={`bg-white p-6 md:p-8 rounded-[2.5rem] border shadow-sm transition-all hover:shadow-xl flex flex-col relative overflow-hidden group/card ${isComplete ? 'border-emerald-50 hover:border-emerald-200 bg-emerald-50/5' : 'border-rose-50 hover:border-rose-200 bg-rose-50/5'}`}>
      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-slate-100 rounded-2xl text-slate-500 group-hover/card:bg-indigo-600 group-hover/card:text-white transition-all">
            <Calendar size={20} />
          </div>
          <div>
            <span className="text-sm font-black text-slate-800 block">{shift.shift_date}</span>
            <span className="text-[10px] font-bold text-slate-400 mt-1 uppercase tracking-wider">{new Date(shift.shift_date).toLocaleDateString('ar-SA', { weekday: 'long' })}</span>
          </div>
        </div>
        <div className={`px-4 py-2 rounded-xl text-[10px] font-black flex items-center gap-2 shadow-sm ${isComplete ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
          {isComplete ? <Check size={14} /> : <AlertTriangle size={14} />}
          {shift.status}
        </div>
      </div>

      <div className="space-y-6 flex-1">
        {groupedPunches.map((group, idx) => {
          const isExit = group.period === 'بصمة خروج';
          const isInvalid = group.period === 'غير مصنفة';
          return (
            <div key={idx} className="relative pr-10">
              <div className={`absolute right-0 top-3 w-3 h-3 rounded-full shadow-sm ring-4 ring-white ${isInvalid ? 'bg-amber-400' : isExit ? 'bg-emerald-500' : 'bg-indigo-500'}`}></div>
              <div className={`p-4 rounded-[1.8rem] border-2 transition-all ${isInvalid ? 'bg-amber-50 border-amber-100' : 'bg-slate-50/40 border-transparent hover:bg-white hover:border-slate-100 shadow-sm'}`}>
                <div className="flex items-center justify-between mb-3">
                   <span className={`text-[10px] font-black uppercase tracking-widest ${isInvalid ? 'text-amber-700' : isExit ? 'text-emerald-700' : 'text-slate-600'}`}>{group.period}</span>
                   {group.punches.length > 1 && <span className="text-[8px] font-black bg-indigo-100 text-indigo-600 px-2 py-0.5 rounded-md">مجمعة ({group.punches.length})</span>}
                </div>
                <div className="flex flex-wrap gap-2.5">
                  {group.punches.map((p, pIdx) => (
                    <div 
                      key={pIdx} 
                      className={`px-4 py-2 rounded-xl text-[10px] font-black border-2 transition-all relative flex items-center gap-2 shadow-sm origin-right ${
                        p.is_duplicate 
                          ? 'bg-rose-100 border-rose-500 text-rose-600 line-through ring-2 ring-rose-200 ring-offset-1 opacity-90 scale-95 shadow-inner' 
                          : 'bg-white border-slate-200 text-slate-700 hover:border-indigo-400 hover:text-indigo-600'
                      }`}
                    >
                      {p.is_duplicate && <Flame size={12} className="text-rose-500 shrink-0 animate-pulse" />}
                      {p.time}
                      {p.is_duplicate && <span className="text-[7px] font-black opacity-50 mr-1">مكرر</span>}
                    </div>
                  ))}
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {!isComplete && (
        <div className="mt-8 p-5 bg-rose-50 border border-rose-100 rounded-[2rem] shadow-inner">
          <div className="flex items-center gap-2 text-rose-600 mb-3">
            <AlertCircle size={18} />
            <span className="text-[10px] font-black uppercase tracking-tight">نواقص الوردية:</span>
          </div>
          <div className="flex flex-wrap gap-2">
            {missingPunches.map((m, idx) => (
              <span key={idx} className="text-[9px] bg-white px-3 py-1.5 rounded-lg border border-rose-200 text-rose-700 font-black shadow-sm">
                {m}
              </span>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

