import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary } from "../types";

export const auditEmployeeFullPerformanceAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const incompleteShifts = employee.shifts.filter(s => s.status === 'ناقصة');
  const missingSummary = incompleteShifts
    .map(s => `${s.shift_date}: نقص ${5 - s.punches_count} بصمات`)
    .slice(0, 5) // تحديد العدد لتوفير التوكن
    .join(' | ');

  const prompt = `
    حلل سلوك الموظف ${employee.name} (ID: ${employee.id}):
    - معدل الالتزام: ${employee.completionRate}%
    - كفاءة الحضور: ${employee.performanceScore}%
    - تفاصيل النقص: [${missingSummary}]

    المطلوب: قدم "تحليلاً تشخيصياً" في سطر واحد فقط يوضح هل المشكلة (تأخير صباحي، نسيان خروج، أو عدم التزام بالفترات الوسطى) مع نصيحة إدارية مختصرة جداً.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        temperature: 0.3, 
        maxOutputTokens: 150,
        thinkingConfig: { thinkingBudget: 0 } 
      }
    });
    return response.text?.trim() || "لا توجد أنماط واضحة للتحليل حالياً.";
  } catch (error) {
    return "نظام التحليل الذكي غير متاح حالياً.";
  }
};

export const analyzeCompanyTrendsAI = async (employees: EmployeeSummary[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const total = employees.length;
  const avgComp = employees.reduce((a, b) => a + b.completionRate, 0) / total;
  const lowCommitment = employees.filter(e => e.completionRate < 60).length;

  const prompt = `
    بصفتك محلل بيانات خبير، حلل الوضع العام للمؤسسة:
    - عدد الموظفين: ${total}
    - متوسط الانضباط: ${avgComp.toFixed(1)}%
    - حالات حرجة (أقل من 60%): ${lowCommitment}

    المطلوب: جملة واحدة استراتيجية للمدير العام تركز على "تحسين كفاءة التشغيل" بناءً على هذه الأرقام.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        maxOutputTokens: 150,
        temperature: 0.2
      }
    });
    return response.text?.trim() || "التقرير الاستراتيجي قيد المعالجة.";
  } catch (error) {
    return "فشل في إنشاء الرؤية العامة.";
  }
};

