const ShiftAuditCard = ({ shift }: { shift: ShiftReport }) => {
  const groupedPunches = useMemo(() => {
    const groups: { period: string; punches: PunchDetail[] }[] = [];
    shift.punches_details.forEach((p) => {
      const last = groups[groups.length - 1];
      if (last && last.period === p.period) {
        last.punches.push(p);
      } else {
        groups.push({ period: p.period, punches: [p] });
      }
    });
    return groups;
  }, [shift.punches_details]);

  const isComplete = shift.status === 'مكتملة';
  const missingPunches = useMemo(() => {
    if (isComplete) return [];
    const required = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
    const present = new Set(shift.punches_details.filter(p => !p.is_duplicate).map(p => p.period));
    return required.filter(r => !present.has(r));
  }, [shift.punches_details, isComplete]);

  return (
    <div className={`bg-white p-7 md:p-9 rounded-[2.5rem] border shadow-sm transition-all hover:shadow-xl flex flex-col relative overflow-hidden group/card ${isComplete ? 'border-emerald-50 hover:border-emerald-200 bg-emerald-50/10' : 'border-rose-50 hover:border-rose-200 bg-rose-50/10'}`}>
      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center gap-4">
          <div className="p-3.5 bg-slate-100 rounded-2xl text-slate-500 group-hover/card:bg-indigo-600 group-hover/card:text-white transition-all shadow-sm">
            <Calendar size={22} />
          </div>
          <div>
            <span className="text-base font-black text-slate-800 block">{shift.shift_date}</span>
            <span className="text-[11px] font-bold text-slate-400 mt-1 uppercase tracking-wider">{new Date(shift.shift_date).toLocaleDateString('ar-SA', { weekday: 'long' })}</span>
          </div>
        </div>
        <div className={`px-5 py-2.5 rounded-2xl text-[11px] font-black flex items-center gap-2 shadow-sm ${isComplete ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
          {isComplete ? <Check size={16} /> : <AlertTriangle size={16} />}
          {shift.status}
        </div>
      </div>

      <div className="space-y-7 flex-1">
        {groupedPunches.map((group, idx) => {
          const isExit = group.period === 'بصمة خروج';
          const isInvalid = group.period === 'غير مصنفة';
          return (
            <div key={idx} className="relative pr-10">
              <div className={`absolute right-0 top-3.5 w-3.5 h-3.5 rounded-full shadow-sm ring-4 ring-white transition-all group-hover/card:scale-125 ${isInvalid ? 'bg-amber-400' : isExit ? 'bg-emerald-500' : 'bg-indigo-500'}`}></div>
              <div className={`p-5 rounded-[2rem] border-2 transition-all ${isInvalid ? 'bg-amber-50 border-amber-100' : 'bg-slate-50/50 border-transparent hover:bg-white hover:border-slate-100 shadow-sm'}`}>
                <div className="flex items-center justify-between mb-4">
                   <span className={`text-[11px] font-black uppercase tracking-widest ${isInvalid ? 'text-amber-700' : isExit ? 'text-emerald-700' : 'text-slate-600'}`}>{group.period}</span>
                   {group.punches.length > 1 && <span className="text-[9px] font-black bg-indigo-100 text-indigo-600 px-3 py-1 rounded-lg">مجموعة ({group.punches.length})</span>}
                </div>
                <div className="flex flex-wrap gap-3">
                  {group.punches.map((p, pIdx) => (
                    <div 
                      key={pIdx} 
                      className={`px-5 py-2.5 rounded-xl text-[11px] font-black border-2 transition-all relative flex items-center gap-2.5 shadow-sm origin-right ${
                        p.is_duplicate 
                          ? 'bg-rose-100 border-rose-500 text-rose-600 line-through ring-2 ring-rose-200 ring-offset-2 opacity-90 scale-95 shadow-inner' 
                          : 'bg-white border-slate-200 text-slate-700 hover:border-indigo-400 hover:text-indigo-600 hover:scale-105'
                      }`}
                    >
                      {p.is_duplicate && <Flame size={14} className="text-rose-500 shrink-0 animate-pulse" />}
                      {p.time}
                      {p.is_duplicate && <span className="text-[8px] font-black opacity-60 mr-1 uppercase">مكرر</span>}
                    </div>
                  ))}
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {!isComplete && (
        <div className="mt-10 p-6 bg-rose-50 border-2 border-dashed border-rose-200 rounded-[2.2rem] shadow-inner">
          <div className="flex items-center gap-2 text-rose-600 mb-4">
            <ShieldAlert size={20} />
            <span className="text-[11px] font-black uppercase tracking-tight">الفجوات الزمنية المكتشفة:</span>
          </div>
          <div className="flex flex-wrap gap-2.5">
            {missingPunches.map((m, idx) => (
              <span key={idx} className="text-[10px] bg-white px-4 py-2 rounded-xl border-2 border-rose-100 text-rose-700 font-black shadow-sm">
                {m}
              </span>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

