                <>
                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                    <StatBox title="إجمالي السجلات" value={stats.totalEmployees} icon={<Users size={20}/>} color="indigo" />
                    <StatBox title="موثوقية البيانات" value={`${stats.completionRate}%`} icon={<ShieldCheck size={20}/>} color="emerald" />
