            <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 max-w-5xl mx-auto space-y-10">
              <div className="bg-gradient-to-br from-indigo-900 via-slate-900 to-slate-900 text-white p-12 rounded-[3.5rem] shadow-2xl relative overflow-hidden border border-white/10">
