const EmployeeSection = ({ employee }: { employee: EmployeeSummary }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [auditResult, setAuditResult] = useState<string | null>(null);
  const [loadingAudit, setLoadingAudit] = useState(false);

  const completedShiftsCount = employee.shifts.filter(s => s.status === 'مكتملة').length;
  const totalShiftsCount = employee.shifts.length;

  const runSmartAudit = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoadingAudit(true);
    try {
      const res = await auditEmployeeFullPerformanceAI(employee);
      setAuditResult(res);
    } catch (err) {
      setAuditResult("⚠️ فشل في إتمام التدقيق.");
    } finally {
      setLoadingAudit(false);
    }
  };

  return (
    <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden transition-all duration-500 hover:shadow-2xl hover:border-indigo-200 group">
      <div 
        className="p-6 md:p-8 flex flex-col md:flex-row items-center gap-6 cursor-pointer select-none" 
        onClick={() => setIsExpanded(!isExpanded)}
      >
        <div className="relative shrink-0">
          <div className="w-20 h-20 bg-gradient-to-br from-slate-100 to-slate-200 rounded-[2.2rem] flex items-center justify-center font-black text-slate-500 text-3xl shadow-inner group-hover:from-indigo-600 group-hover:to-indigo-500 group-hover:text-white transition-all duration-500">
            {employee.name.charAt(0)}
          </div>
          <div className={`absolute -bottom-1 -right-1 w-9 h-9 rounded-full border-4 border-white flex items-center justify-center shadow-lg transition-colors duration-500 ${employee.isEligible ? 'bg-emerald-500' : 'bg-rose-500'}`}>
             {employee.isEligible ? <ShieldCheck size={16} className="text-white" /> : <ShieldAlert size={16} className="text-white" />}
          </div>
        </div>

        <div className="flex-1 text-center md:text-right">
          <div className="flex flex-col md:flex-row items-center gap-3 mb-4">
            <h3 className="font-black text-2xl text-slate-900 tracking-tighter group-hover:text-indigo-600 transition-colors">
              {employee.name}
            </h3>
            {employee.isEligible ? (
              <span className="flex items-center gap-1.5 px-3 py-1 bg-emerald-50 text-emerald-600 rounded-full text-[10px] font-black border border-emerald-100 uppercase">
                <Check size={14} /> بيانات موثوقة
              </span>
            ) : (
              <span className="flex items-center gap-1.5 px-3 py-1 bg-rose-50 text-rose-600 rounded-full text-[10px] font-black border border-rose-100 uppercase">
                <AlertCircle size={14} /> يتطلب فحص فني
              </span>
            )}
          </div>
          <div className="flex flex-wrap justify-center md:justify-start gap-3">
             <span className="flex items-center gap-2 text-[10px] bg-slate-100 px-4 py-2 rounded-xl font-black text-slate-500 border border-slate-200 shadow-sm">
               <Fingerprint size={14} className="text-slate-400" /> {employee.id}
             </span>
             <span className="flex items-center gap-2 text-[10px] bg-indigo-50 px-4 py-2 rounded-xl font-black text-indigo-600 border border-indigo-100 shadow-sm">
               <Layers size={14} /> {completedShiftsCount} / {totalShiftsCount} وردية كاملة
             </span>
             <span className="flex items-center gap-2 text-[10px] bg-amber-50 px-4 py-2 rounded-xl font-black text-amber-600 border border-amber-100 shadow-sm">
               <Zap size={14} /> {employee.totalPunches} بصمة فريدة
             </span>
          </div>
        </div>

        <div className="hidden lg:flex items-center gap-10 px-10 border-x border-slate-100">
          <div className="text-center">
             <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-2">معيار الالتزام</p>
             <div className="flex items-center gap-3">
                <div className="w-20 h-2 bg-slate-100 rounded-full overflow-hidden shadow-inner">
                   <div className={`h-full transition-all duration-1000 ${employee.completionRate >= 80 ? 'bg-emerald-500' : employee.completionRate >= 50 ? 'bg-amber-500' : 'bg-rose-500'}`} style={{ width: isExpanded ? `${employee.completionRate}%` : '0%' }}></div>
                </div>
                <span className={`text-xl font-black ${employee.completionRate >= 80 ? 'text-emerald-600' : 'text-rose-600'}`}>{employee.completionRate}%</span>
             </div>
          </div>
        </div>

        <div className="flex items-center gap-3 shrink-0">
          <button 
            onClick={runSmartAudit}
            disabled={loadingAudit}
            className="group/btn relative w-12 h-12 flex items-center justify-center bg-white border border-slate-200 text-indigo-600 rounded-2xl hover:bg-indigo-600 hover:text-white hover:border-indigo-600 transition-all shadow-sm active:scale-90 disabled:opacity-50"
            title="فحص تقني ذكي"
          >
            {loadingAudit ? <RefreshCcw size={20} className="animate-spin" /> : <ShieldCheck size={20} className="group-hover/btn:scale-110" />}
          </button>
          <div className="w-12 h-12 flex items-center justify-center bg-slate-50 rounded-2xl text-slate-400 group-hover:bg-slate-100 transition-all">
