            <div className={`mb-10 p-8 rounded-[2.5rem] shadow-xl flex items-center gap-8 border relative overflow-hidden animate-in zoom-in-95 duration-300 ${auditResult.includes('⚠️') || auditResult.includes('خلل') ? 'bg-rose-600 text-white border-rose-500' : 'bg-gradient-to-br from-emerald-600 to-emerald-800 text-white border-emerald-500'}`}>
               <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 blur-[80px] rounded-full translate-x-1/2 translate-y-[-50%]"></div>
