import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary, ShiftReport } from "../types";

/**
 * التدقيق الفني الفردي: مطابقة تسلسل البصمات مع القواعد المنطقية للزمن الخاص بالنوبة
 */
export const auditEmployeeFullPerformanceAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // اختيار العينات الأكثر تعقيداً فقط (التي تحتوي على بصمات غير مصنفة أو نواقص في النوبة)
  const complexitySample = employee.shifts
    .filter(s => s.status === 'ناقصة' || s.punches_details.some(p => p.period === 'غير مصنفة'))
    .slice(0, 2); 

  if (complexitySample.length === 0 && employee.completionRate === 100) {
    return "✅ فحص تقني ناجح: البيانات مطابقة تماماً للمنطق الزمني لنوبات المحطة. لا توجد ثغرات رقمية مكتشفة.";
  }

  const shiftData = complexitySample.map(s => ({
    date: s.shift_date,
    sequence: s.punches_details.map(p => `${p.time} [${p.period}]`)
  }));

  const prompt = `
    بصفتك "مدقق جودة بيانات رقمي" لنظام حضور وانصراف بمحطة كهرباء:
    قم بإجراء فحص (Technical Validation) للبيانات التالية للموظف ${employee.name}:
    بيانات النوبات: ${JSON.stringify(shiftData)}
    إحصائيات عامة: انضباط ${employee.completionRate}%، مجموع بصمات فريدة ${employee.totalPunches}.

    المطلوب:
    1. رصد أي "قفزة زمنية" غير منطقية أو بصمة في توقيت غير مبرر خارج حدود النوبة.
    2. التأكد من أن البصمات المصنفة كـ "غير مصنفة" لا تنتمي فعلياً لأي فترة رسمية داخل النوبة.
    3. جملة فنية واحدة فقط تبدأ بـ "النتيجة الفنية:" توضح سلامة بيانات النوبة أو الخلل التقني المحدد.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        temperature: 0.1, 
        maxOutputTokens: 180,
        thinkingConfig: { thinkingBudget: 0 } 
      }
    });
    return response.text?.trim() || "تعذر الحصول على نتيجة تدقيق دقيقة للنوبة.";
  } catch (error) {
    return "⚠️ خطأ في الاتصال بمحرك التدقيق الذكي.";
  }
};

/**
 * تقرير النزاهة العام: تحليل إحصائي رقمي لموثوقية سجلات النوبات للمؤسسة بالكامل
 */
export const analyzeCompanyTrendsAI = async (employees: EmployeeSummary[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const total = employees.length;
  const avgPerformance = employees.reduce((a, b) => a + b.performanceScore, 0) / (total || 1);
  const criticalCases = employees.filter(e => e.completionRate < 50).length;
  const perfectCases = employees.filter(e => e.completionRate === 100).length;
  const totalDuplicates = employees.reduce((acc, e) => acc + e.shifts.reduce((sacc, s) => sacc + s.punches_details.filter(p => p.is_duplicate).length, 0), 0);

  const prompt = `
    بصفتك "كبير مدققي أنظمة الرقابة" بمؤسسة صناعية كبرى:
    حلل ملخص "نزاهة الحضور" الخاص بنوبات العمل:
    - إجمالي الموظفين: ${total}
    - متوسط جودة بيانات النوبات: ${avgPerformance.toFixed(1)}%
    - حالات "انضباط كامل بالنوبات": ${perfectCases}
    - حالات "حرجة في النوبات": ${criticalCases}
    - بصمات مكررة تم حظرها برمجياً: ${totalDuplicates}

    المطلوب: تقديم تقييم فني (Executive Summary) في سطرين فقط حول "موثوقية نظام النوبات الرقمي حالياً" وتقديم نصيحة واحدة لتحسين دقة بيانات النوبة وتفادي التلاعب.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        maxOutputTokens: 250,
        temperature: 0.2
      }
    });
    return response.text?.trim() || "تقرير نزاهة النوبات غير متاح حالياً.";
  } catch (error) {
    return "فشل المحرك في توليد تقرير النزاهة.";
  }
};

