          </div>
        </div>

        <div className="flex items-center gap-2">
          <button onClick={runSmartAudit} disabled={loadingAudit} className="w-10 h-10 flex items-center justify-center bg-white border border-slate-200 text-indigo-600 rounded-xl hover:bg-indigo-600 hover:text-white transition-all shadow-sm">
