          {shift.status}
        </div>
      </div>

      <div className="space-y-3 flex-1">
        {groupedPunches.map((group, idx) => (
          <div key={idx} className="flex flex-col gap-1 pr-4 relative">
             <div className={`absolute right-0 top-1.5 w-2 h-2 rounded-full ${group.period === 'غير مصنفة' ? 'bg-amber-400' : 'bg-indigo-500'}`}></div>
             <span className="text-[8px] font-bold text-slate-400 mr-2">{group.period}</span>
             <div className="flex flex-wrap gap-1.5">
               {group.punches.map((p, pIdx) => (
                 <div key={pIdx} className={`px-2 py-1 rounded-lg text-[9px] font-black border ${p.is_duplicate ? 'bg-rose-50 border-rose-200 text-rose-400 line-through' : 'bg-white border-slate-100 text-slate-600'}`}>
                   {p.time}
                 </div>
               ))}
             </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, X, Menu,
  Calendar, LayoutDashboard, Sparkles, ChevronDown, Check, Info, 
  Fingerprint, BarChart3, ShieldCheck, AlertTriangle, Flame, Zap, Target, Award,
  TrendingUp, UserCheck, AlertCircle, RefreshCcw, Clock, ShieldAlert,
  History, Timer, LogOut, Lightbulb, Activity, Layers, Shield, FileText, Download
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { auditEmployeeFullPerformanceAI, analyzeCompanyTrendsAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';

type ViewType = 'dashboard' | 'employees' | 'integrity';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [companyInsight, setCompanyInsight] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setCompanyInsight(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const generateIntegrityReport = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    try {
      const result = await analyzeCompanyTrendsAI(employees);
      setCompanyInsight(result);
      setCurrentView('integrity');
    } catch (e) {
      console.error(e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 font-sans flex flex-col lg:flex-row rtl overflow-hidden">
      <aside className={`fixed inset-y-0 right-0 z-50 w-64 bg-[#0f172a] text-white transition-transform lg:static lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="h-full flex flex-col p-6">
          <div className="flex items-center gap-3 mb-10">
            <div className="p-2.5 bg-indigo-600 rounded-xl shadow-lg rotate-3">
              <ShieldCheck size={24} className="text-white" />
            </div>
            <div>
              <h1 className="font-extrabold text-lg text-white">بصمتي <span className="text-indigo-400">PRO</span></h1>
              <p className="text-[8px] text-slate-500 font-bold uppercase mt-1">نظام تدقيق النوبات</p>
            </div>
          </div>
          <nav className="space-y-2 flex-1">
            <SidebarLink icon={<LayoutDashboard size={18}/>} label="لوحة التحكم" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Users size={18}/>} label="سجل الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<FileText size={18}/>} label="تقرير النزاهة" active={currentView === 'integrity'} onClick={() => { setCurrentView('integrity'); setIsSidebarOpen(false); }} />
          </nav>
          <div className="mt-auto space-y-4">
            <label className="flex items-center justify-center gap-2 w-full p-3 bg-indigo-600 rounded-xl cursor-pointer hover:bg-indigo-700 transition-all font-bold text-xs text-white shadow-lg active:scale-95">
              <FileUp size={16} />
              <span>استيراد Excel</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
            </label>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="bg-white/80 backdrop-blur-md border-b border-slate-200 px-6 py-4 flex items-center justify-between shrink-0 z-10">
          <div className="flex items-center gap-4 flex-1">
            <button className="lg:hidden p-2 text-slate-500" onClick={() => setIsSidebarOpen(!isSidebarOpen)}>
              <Menu size={22} />
            </button>
            <div className="relative w-full max-md:max-w-md max-w-md">
              <Search className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
              <input 
                type="text" 
                placeholder="ابحث عن موظف..." 
                className="w-full bg-slate-100 border-none rounded-xl pr-10 pl-4 py-2 text-xs outline-none focus:ring-2 focus:ring-indigo-500/20"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
          </div>
          <button 
            onClick={generateIntegrityReport}
            disabled={employees.length === 0 || isAnalyzing}
            className="flex items-center gap-2 px-5 py-2.5 bg-slate-900 text-white rounded-xl text-[10px] font-black hover:bg-slate-800 transition-all active:scale-95 disabled:opacity-20 shadow-md"
          >
            {isAnalyzing && currentView === 'integrity' ? <RefreshCcw size={14} className="animate-spin" /> : <ShieldCheck size={14} className="text-indigo-400" />}
            تدقيق النزاهة
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8 space-y-6 custom-scrollbar pb-24">
          {currentView === 'dashboard' && (
            <div className="animate-in fade-in duration-500 space-y-8">
              {stats ? (
                <>
                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                    <StatBox title="إجمالي السجلات" value={stats.totalEmployees} icon={<Users size={18}/>} color="indigo" />
                    <StatBox title="موثوقية النوبات" value={`${stats.completionRate}%`} icon={<ShieldCheck size={18}/>} color="emerald" />
                    <StatBox title="إجمالي البصمات" value={stats.totalPunches.toLocaleString()} icon={<Fingerprint size={18}/>} color="amber" />
                  </div>
                  <EmployeeListSection employees={filteredEmployees.slice(0, 5)} isAnalyzing={isAnalyzing} />
                </>
              ) : <EmptyState />}
            </div>
          )}

          {currentView === 'employees' && (
            <div className="animate-in fade-in duration-500 space-y-6">
              <SectionTitle icon={<Users size={20}/>} title="سجل نوبات الموظفين" />
              <EmployeeListSection employees={filteredEmployees} isAnalyzing={isAnalyzing} />
            </div>
          )}

          {currentView === 'integrity' && (
            <div className="animate-in fade-in duration-500 max-w-4xl mx-auto space-y-8">
              <div className="bg-slate-900 text-white p-8 rounded-[2rem] shadow-xl relative overflow-hidden border border-white/5">
                <div className="relative z-10">
                  <h2 className="text-2xl font-black mb-6 flex items-center gap-3"><ShieldCheck className="text-indigo-400" /> تقرير نزاهة النوبات الذكي</h2>
                  <div className="bg-white/5 p-6 rounded-2xl border border-white/10 mb-6 font-medium italic text-indigo-100">
                    {isAnalyzing ? "جاري التوليد..." : companyInsight || "بانتظار التحليل..."}
                  </div>
                  <div className="grid grid-cols-3 gap-4">
                     <IntegrityMetric label="تكرار محظور" value={employees.reduce((acc, e) => acc + e.shifts.reduce((sacc, s) => sacc + s.punches_details.filter(p => p.is_duplicate).length, 0), 0)} />
                     <IntegrityMetric label="نوبات حرجة" value={employees.filter(e => !e.isEligible).length} />
                     <IntegrityMetric label="الدقة العامة" value="99.9%" />
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

