const EmployeeSection: React.FC<{ employee: EmployeeSummary }> = ({ employee }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [auditResult, setAuditResult] = useState<string | null>(null);
  const [loadingAudit, setLoadingAudit] = useState(false);

  const runSmartAudit = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoadingAudit(true);
    try {
      const res = await auditEmployeeFullPerformanceAI(employee);
      setAuditResult(res);
    } catch (err) {
      setAuditResult("⚠️ خطأ.");
    } finally {
      setLoadingAudit(false);
    }
  };

  return (
    <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden group">
      <div className="p-4 md:p-6 flex flex-col md:flex-row items-center gap-4 cursor-pointer" onClick={() => setIsExpanded(!isExpanded)}>
        <div className="relative">
          <div className="w-14 h-14 bg-slate-100 rounded-2xl flex items-center justify-center font-black text-slate-500 text-xl group-hover:bg-indigo-600 group-hover:text-white transition-all">
            {employee.name.charAt(0)}
          </div>
        </div>

        <div className="flex-1 text-center md:text-right">
          <div className="flex flex-col md:flex-row items-center gap-2 mb-2">
            <h3 className="font-black text-lg text-slate-900">{employee.name}</h3>
            <span className={`px-2 py-0.5 rounded-full text-[8px] font-black uppercase border ${employee.isEligible ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-rose-50 text-rose-600 border-rose-100'}`}>
              {employee.isEligible ? 'سليم' : 'يتطلب فحص'}
            </span>
          </div>
          <div className="flex flex-wrap justify-center md:justify-start gap-2">
             <span className="text-[8px] bg-slate-50 px-3 py-1 rounded-lg font-black text-slate-500 border border-slate-100">ID: {employee.id}</span>
             <span className="text-[8px] bg-indigo-50 px-3 py-1 rounded-lg font-black text-indigo-600 border border-indigo-100">{employee.shifts.length} نوبات</span>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <button onClick={runSmartAudit} disabled={loadingAudit} className="w-10 h-10 flex items-center justify-center bg-white border border-slate-200 text-indigo-600 rounded-xl hover:bg-indigo-600 hover:text-white transition-all shadow-sm">
            {loadingAudit ? <RefreshCcw size={16} className="animate-spin" /> : <ShieldCheck size={18} />}
          </button>
          <ChevronDown size={20} className={`text-slate-300 transition-transform ${isExpanded ? 'rotate-180 text-indigo-500' : ''}`} />
        </div>
      </div>

      {isExpanded && (
        <div className="bg-slate-50/30 p-4 md:p-6 border-t border-slate-100 space-y-4">
          {auditResult && (
            <div className={`p-4 rounded-2xl border text-xs font-black shadow-sm flex items-center gap-3 ${auditResult.includes('اختلاف') ? 'bg-rose-50 text-rose-600 border-rose-100' : 'bg-emerald-50 text-emerald-600 border-emerald-100'}`}>
               <ShieldCheck size={16} /> {auditResult}
            </div>
          )}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {employee.shifts.map((shift, i) => <ShiftAuditCard key={i} shift={shift} />)}
          </div>
        </div>
      )}
    </div>
  );
};

const ShiftAuditCard: React.FC<{ shift: ShiftReport }> = ({ shift }) => {
  const groupedPunches = useMemo(() => {
    const groups: { period: string; punches: PunchDetail[] }[] = [];
    shift.punches_details.forEach((p) => {
      const last = groups[groups.length - 1];
      if (last && last.period === p.period) last.punches.push(p);
      else groups.push({ period: p.period, punches: [p] });
    });
    return groups;
  }, [shift.punches_details]);

  const isComplete = shift.status === 'مكتملة';

  return (
    <div className={`p-4 rounded-2xl border bg-white shadow-sm flex flex-col ${isComplete ? 'border-emerald-100' : 'border-rose-100'}`}>
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <Calendar size={14} className="text-slate-400" />
          <span className="text-[10px] font-black text-slate-700">{shift.shift_date}</span>
        </div>
        <div className={`px-2 py-0.5 rounded-lg text-[8px] font-black ${isComplete ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
          {shift.status}
        </div>
      </div>

      <div className="space-y-3 flex-1">
        {groupedPunches.map((group, idx) => {
          const isExit = group.period === 'بصمة خروج';
          const isInvalid = group.period === 'غير مصنفة';
          return (
            <div key={idx} className={`flex flex-col gap-1 pr-4 relative py-1.5 px-2 rounded-xl transition-all ${isExit ? 'bg-emerald-50/70 border border-emerald-200 ring-1 ring-emerald-100/50 shadow-sm shadow-emerald-100' : ''}`}>
               <div className={`absolute right-0 top-3 w-2 h-2 rounded-full ${isInvalid ? 'bg-amber-400 shadow-amber-200 shadow-lg' : isExit ? 'bg-emerald-500 shadow-emerald-200 shadow-lg' : 'bg-indigo-500 shadow-indigo-100 shadow-lg'}`}></div>
               <span className={`flex items-center gap-1.5 text-[8px] font-black mr-2 ${isExit ? 'text-emerald-700' : isInvalid ? 'text-amber-700' : 'text-slate-400'}`}>
                 {isExit && <LogOut size={10} className="text-emerald-500" />}
                 {group.period}
               </span>
               <div className="flex flex-wrap gap-1.5">
                 {group.punches.map((p, pIdx) => (
                   <div 
                    key={pIdx} 
                    className={`px-2 py-1 rounded-lg text-[9px] font-black border transition-all flex items-center gap-1 ${
                      p.is_duplicate 
                        ? 'bg-rose-50 border-rose-300 text-rose-500 line-through ring-1 ring-rose-100 opacity-90' 
                        : isExit 
                          ? 'bg-white border-emerald-200 text-emerald-700 shadow-sm' 
                          : 'bg-white border-slate-100 text-slate-600'
                    }`}
                    style={p.is_duplicate ? { 
                      backgroundImage: 'repeating-linear-gradient(45deg, transparent, transparent 4px, rgba(244, 63, 94, 0.04) 4px, rgba(244, 63, 94, 0.04) 8px)' 
                    } : {}}
                  >
                     {p.is_duplicate && <AlertCircle size={8} className="text-rose-400" />}
                     {p.time}
                   </div>
                 ))}
               </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default App;

