import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary, ShiftReport } from "../types";

/**
 * التدقيق الفني الفردي: مطابقة تسلسل البصمات مع النظام البرمجي بدون شروحات
 */
export const auditEmployeeFullPerformanceAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const complexitySample = employee.shifts
    .filter(s => s.status === 'ناقصة' || s.punches_details.some(p => p.period === 'غير مصنفة'))
    .slice(0, 3); 

  if (complexitySample.length === 0 && employee.completionRate === 100) {
    return "✅ مطابق لتدقيق النظام: كافة السجلات سليمة تقنياً.";
  }

  const shiftData = complexitySample.map(s => ({
    date: s.shift_date,
    system_status: s.status,
    sequence: s.punches_details.map(p => `${p.time}[${p.period}]`)
  }));

  const prompt = `
    دقق البيانات التالية وقارنها بحالة النظام المذكورة (system_status).
    الموظف: ${employee.name}
    البيانات: ${JSON.stringify(shiftData)}

    المطلوب: رد بكلمة واحدة "مطابق" إذا كان تدقيق النظام صحيحاً، أو "يوجد اختلاف" مع ذكر اسم الفترة التي بها الخلل فقط.
    ممنوع كتابة أي شرح أو مبررات.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        temperature: 0.1, 
        maxOutputTokens: 50,
        thinkingConfig: { thinkingBudget: 0 } 
      }
    });
    return `النتيجة: ${response.text?.trim()}` || "تعذر التدقيق.";
  } catch (error) {
    return "⚠️ خطأ في محرك التدقيق.";
  }
};

/**
 * توليد ملخص تدقيق مفصل يحدد النواقص بالتواريخ والفترات
 */
export const generateDetailedAuditSummaryAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // نركز على النوبات الناقصة فقط لتوفير التوكنات والحصول على دقة أعلى
  const faultyShifts = employee.shifts
    .filter(s => s.status === 'ناقصة' || s.punches_details.some(p => p.is_duplicate))
    .map(s => ({
      date: s.shift_date,
      missing_periods: ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
        .filter(p => !s.punches_details.some(pd => pd.period === p && !pd.is_duplicate)),
      duplicates: s.punches_details.filter(pd => pd.is_duplicate).map(pd => pd.period)
    }));

  if (faultyShifts.length === 0) {
    return "لا توجد نواقص في سجلات الموظف، جميع النوبات مكتملة ومنتظمة.";
  }

  const prompt = `
    أنت مدقق موارد بشرية محترف. بناءً على البيانات التالية للموظف ${employee.name}، قم بصياغة ملخص تدقيق واضح واحترافي.
    البيانات: ${JSON.stringify(faultyShifts)}

    المطلوب:
    - ذكر التواريخ التي بها نقص وتحديد الفترة الناقصة (مثلاً: نقص بصمة وسطية في تاريخ 2023-10-01).
    - ذكر التواريخ التي بها بصمات مكررة بشكل لافت.
    - استخدم نقاط واضحة.
    - اجعل الأسلوب تقريري ومباشر.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        temperature: 0.2,
        maxOutputTokens: 500
      }
    });
    return response.text?.trim() || "لم يتم العثور على ملاحظات.";
  } catch (error) {
    return "⚠️ حدث خطأ أثناء توليد ملخص التدقيق.";
  }
};

/**
 * تقرير النزاهة العام للمؤسسة
 */
export const analyzeCompanyTrendsAI = async (employees: EmployeeSummary[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const total = employees.length;
  const avgPerformance = employees.reduce((a, b) => a + b.performanceScore, 0) / (total || 1);
  const criticalCases = employees.filter(e => e.completionRate < 50).length;
  const totalDuplicates = employees.reduce((acc, e) => acc + e.shifts.reduce((sacc, s) => sacc + s.punches_details.filter(p => p.is_duplicate).length, 0), 0);

  const prompt = `
    حلل النزاهة الرقمية للمؤسسة:
    موظفين: ${total}
    جودة: ${avgPerformance.toFixed(1)}%
    حرجة: ${criticalCases}
    تكرار: ${totalDuplicates}
    أعطِ حكماً نهائياً في سطر واحد فقط عن موثوقية البيانات.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        maxOutputTokens: 100,
        temperature: 0.2
      }
    });
    return response.text?.trim() || "التقرير غير متاح.";
  } catch (error) {
    return "فشل تحليل النزاهة.";
  }
};

