} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { auditEmployeeFullPerformanceAI, analyzeCompanyTrendsAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';

type ViewType = 'dashboard' | 'employees' | 'integrity';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [companyInsight, setCompanyInsight] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setCompanyInsight(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const generateIntegrityReport = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    try {
      const result = await analyzeCompanyTrendsAI(employees);
      setCompanyInsight(result);
      setCurrentView('integrity');
    } catch (e) {
      console.error(e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#f1f5f9] text-slate-900 font-sans flex flex-col lg:flex-row rtl overflow-hidden">
      <aside className={`fixed inset-y-0 right-0 z-50 w-72 bg-[#020617] text-white transition-transform lg:static lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="h-full flex flex-col p-8">
          <div className="flex items-center gap-4 mb-12">
            <div className="p-3 bg-gradient-to-tr from-indigo-600 to-violet-500 rounded-2xl shadow-xl shadow-indigo-500/20 rotate-3">
              <ShieldCheck size={28} className="text-white" />
            </div>
            <div>
              <h1 className="font-extrabold text-xl text-white tracking-tight">بصمتي <span className="text-indigo-400">PRO</span></h1>
              <p className="text-[10px] text-slate-500 font-bold uppercase mt-1 tracking-widest">التدقيق الفائق</p>
            </div>
          </div>
          <nav className="space-y-3 flex-1">
            <SidebarLink icon={<LayoutDashboard size={20}/>} label="لوحة التحكم" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Users size={20}/>} label="سجل الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<FileText size={20}/>} label="تقرير النزاهة" active={currentView === 'integrity'} onClick={() => { setCurrentView('integrity'); setIsSidebarOpen(false); }} />
          </nav>
          <div className="mt-auto pt-6 border-t border-slate-800">
            <label className="group flex items-center justify-center gap-3 w-full p-4 bg-indigo-600 rounded-2xl cursor-pointer hover:bg-indigo-500 transition-all font-black text-sm text-white shadow-xl shadow-indigo-600/10 active:scale-95">
              <FileUp size={20} className="group-hover:scale-110 transition-transform" />
              <span>استيراد ملف Excel</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
            </label>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="bg-white/70 backdrop-blur-xl border-b border-slate-200 px-8 py-5 flex items-center justify-between shrink-0 z-20">
          <div className="flex items-center gap-6 flex-1">
            <button className="lg:hidden p-2 text-slate-500 hover:bg-slate-100 rounded-xl" onClick={() => setIsSidebarOpen(!isSidebarOpen)}>
              <Menu size={24} />
            </button>
            <div className="relative w-full max-w-lg">
              <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input 
                type="text" 
                placeholder="ابحث بالاسم أو الرقم الوظيفي..." 
                className="w-full bg-slate-100 border-none rounded-2xl pr-12 pl-5 py-3 text-sm outline-none focus:ring-2 focus:ring-indigo-500/30 transition-shadow"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
          </div>
          <button 
            onClick={generateIntegrityReport}
            disabled={employees.length === 0 || isAnalyzing}
            className="flex items-center gap-3 px-6 py-3 bg-[#020617] text-white rounded-2xl text-xs font-black hover:bg-slate-800 transition-all active:scale-95 disabled:opacity-20 shadow-xl shadow-slate-900/10"
          >
            {isAnalyzing && currentView === 'integrity' ? <RefreshCcw size={18} className="animate-spin" /> : <ShieldCheck size={18} className="text-indigo-400" />}
            تحليل النزاهة الشامل
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-6 lg:p-10 space-y-8 custom-scrollbar pb-32">
          {currentView === 'dashboard' && (
            <div className="animate-in fade-in duration-500 space-y-10">
              {stats ? (
                <>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <StatBox title="عدد الموظفين" value={stats.totalEmployees} icon={<Users size={24}/>} color="indigo" />
                    <StatBox title="اكتمال الوردية" value={`${stats.completionRate}%`} icon={<ShieldCheck size={24}/>} color="emerald" />
                    <StatBox title="إجمالي البصمات" value={stats.totalPunches.toLocaleString()} icon={<Fingerprint size={24}/>} color="amber" />
                  </div>
                  <div>
                    <div className="flex items-center justify-between mb-6 px-2">
                       <SectionTitle icon={<Activity size={20}/>} title="أحدث السجلات النشطة" />
                       <button onClick={() => setCurrentView('employees')} className="text-xs font-bold text-indigo-600 hover:underline">عرض الكل</button>
                    </div>
                    <EmployeeListSection employees={filteredEmployees.slice(0, 5)} isAnalyzing={isAnalyzing} />
                  </div>
                </>
              ) : <EmptyState />}
            </div>
          )}

          {currentView === 'employees' && (
            <div className="animate-in fade-in duration-500 space-y-8">
              <SectionTitle icon={<Users size={24}/>} title="سجل الموظفين والتدقيق" />
              <EmployeeListSection employees={filteredEmployees} isAnalyzing={isAnalyzing} />
            </div>
          )}

          {currentView === 'integrity' && (
            <div className="animate-in fade-in duration-500 max-w-5xl mx-auto space-y-8">
              <div className="bg-[#020617] text-white p-10 rounded-[3rem] shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-br from-indigo-500/10 to-transparent pointer-events-none"></div>
                <div className="relative z-10">
                  <h2 className="text-3xl font-black mb-8 flex items-center gap-4"><ShieldCheck className="text-indigo-400" size={32} /> تقرير النزاهة الرقمي</h2>
                  <div className="bg-white/5 backdrop-blur-md p-8 rounded-3xl border border-white/10 mb-8 font-medium italic text-indigo-100 text-lg leading-relaxed shadow-inner">
                    {isAnalyzing ? "جاري استخلاص النتائج..." : companyInsight || "يرجى الضغط على زر التحليل في الأعلى..."}
                  </div>
                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
                     <IntegrityMetric label="بصمات مكررة" value={employees.reduce((acc, e) => acc + e.shifts.reduce((sacc, s) => sacc + s.punches_details.filter(p => p.is_duplicate).length, 0), 0)} />
                     <IntegrityMetric label="حالات حرجة" value={employees.filter(e => !e.isEligible).length} />
                     <IntegrityMetric label="دقة المصادقة" value="99.9%" />
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

const IntegrityMetric = ({ label, value }: any) => (
  <div className="p-6 bg-white/5 rounded-2xl border border-white/10 hover:bg-white/10 transition-colors">
     <div className="text-indigo-300 text-[10px] font-black uppercase mb-2 tracking-widest">{label}</div>
     <div className="text-2xl font-black text-white">{value}</div>
  </div>
);

const SectionTitle = ({ icon, title }: any) => (
  <h2 className="text-xl font-black text-slate-800 flex items-center gap-3">
    <div className="p-2 bg-white text-indigo-600 rounded-xl shadow-sm">{icon}</div>
    {title}
  </h2>
);

const EmptyState = () => (
  <div className="text-center py-40 bg-white rounded-[3rem] border-2 border-dashed border-slate-200 shadow-sm">
    <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-6">
      <Fingerprint size={40} className="text-slate-300" />
    </div>
    <h3 className="text-xl font-black text-slate-800 uppercase mb-3">لا توجد بيانات حالياً</h3>
    <p className="text-slate-400 text-sm font-medium">ابدأ برفع ملف Excel الخاص بالحضور والإنصراف.</p>
  </div>
);

const EmployeeListSection = ({ employees, isAnalyzing }: { employees: EmployeeSummary[], isAnalyzing: boolean }) => (
  <div className="space-y-6">
    {isAnalyzing ? (
      <div className="flex flex-col items-center py-32 bg-white rounded-[3rem] border border-slate-100 shadow-sm">
        <div className="relative mb-6">
           <div className="w-16 h-16 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
        </div>
        <p className="text-sm font-black text-slate-400 tracking-[0.2em] uppercase">جاري تحليل البيانات</p>
      </div>
    ) : employees.map((emp) => <EmployeeSection key={emp.id} employee={emp} />)}
  </div>
);

const StatBox = ({ title, value, icon, color }: any) => {
  const gradients: any = {
    indigo: "from-indigo-600 to-indigo-500 shadow-indigo-200",
    emerald: "from-emerald-600 to-emerald-500 shadow-emerald-200",
    amber: "from-amber-500 to-amber-400 shadow-amber-200"
  };
  return (
    <div className={`bg-gradient-to-br ${gradients[color]} p-8 rounded-[2rem] text-white shadow-xl relative overflow-hidden group transition-transform hover:-translate-y-1`}>
       <div className="absolute -right-4 -bottom-4 bg-white/10 w-32 h-32 rounded-full blur-2xl group-hover:scale-150 transition-transform"></div>
       <div className="relative flex justify-between items-center">
          <div>
            <p className="text-[10px] font-black uppercase opacity-70 mb-2 tracking-widest">{title}</p>
            <h4 className="text-3xl font-extrabold">{value}</h4>
          </div>
          <div className="p-4 bg-white/20 backdrop-blur-sm rounded-2xl border border-white/20">
            {icon}
          </div>
       </div>
    </div>
  );
};

const SidebarLink = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl transition-all font-bold text-sm ${active ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/20 translate-x-1' : 'text-slate-400 hover:bg-white/5 hover:text-slate-200'}`}>
    {icon} <span>{label}</span>
  </button>
);

const EmployeeSection: React.FC<{ employee: EmployeeSummary }> = ({ employee }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [auditResult, setAuditResult] = useState<string | null>(null);
  const [detailedSummary, setDetailedSummary] = useState<string | null>(null);
  const [loadingAudit, setLoadingAudit] = useState(false);
  const [loadingSummary, setLoadingSummary] = useState(false);

  const runSmartAudit = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoadingAudit(true);
    try {
      const res = await auditEmployeeFullPerformanceAI(employee);
      setAuditResult(res);
    } catch (err) {
      setAuditResult("⚠️ فشل الاتصال.");
    } finally {
      setLoadingAudit(false);
    }
  };

  const showDetailedSummary = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoadingSummary(true);
    try {
      const res = await generateDetailedAuditSummaryAI(employee);
      setDetailedSummary(res);
    } catch (err) {
      setDetailedSummary("⚠️ فشل توليد الملخص.");
    } finally {
      setLoadingSummary(false);
    }
  };

  const completedShiftsCount = employee.shifts.filter(s => s.status === 'مكتملة').length;
  const isAllComplete = completedShiftsCount === employee.shifts.length;

  return (
    <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm hover:shadow-xl hover:shadow-slate-200/50 transition-all overflow-hidden">
      <div className="p-6 md:p-8 flex flex-col lg:flex-row items-center gap-8 cursor-pointer group" onClick={() => setIsExpanded(!isExpanded)}>
        {/* Profile/ID Section */}
        <div className="flex items-center gap-5 min-w-[300px]">
          <div className="relative">
            <div className={`w-16 h-16 rounded-2xl flex items-center justify-center font-black text-2xl transition-all shadow-lg ${isAllComplete ? 'bg-emerald-500 text-white shadow-emerald-200' : 'bg-rose-500 text-white shadow-rose-200'}`}>
              {employee.name.charAt(0)}
            </div>
            {isAllComplete && (
              <div className="absolute -bottom-2 -right-2 bg-white p-1 rounded-full shadow-md border border-slate-100">
                <CheckCircle2 size={16} className="text-emerald-500" />
              </div>
            )}
          </div>
          <div>
            <h3 className="font-extrabold text-xl text-slate-900 group-hover:text-indigo-600 transition-colors">{employee.name}</h3>
            <div className="flex items-center gap-2 mt-1">
              <span className="text-[10px] font-black text-slate-400 tracking-wider">ID: #{employee.id}</span>
              <span className={`px-2 py-0.5 rounded-full text-[9px] font-black uppercase ${employee.isEligible ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                {employee.isEligible ? 'سجل مكتمل' : 'سجل غير مكتمل'}
              </span>
            </div>
          </div>
        </div>

        {/* Stats Strip */}
        <div className="flex-1 flex flex-wrap justify-around items-center bg-slate-50/50 rounded-3xl py-4 px-6 border border-slate-100/50">
          <HeaderStat icon={<Fingerprint className="text-amber-500" size={16}/>} label="إجمالي البصمات" value={employee.totalPunches} />
          <div className="w-[1px] h-8 bg-slate-200"></div>
          <HeaderStat icon={<Timer className="text-indigo-500" size={16}/>} label="إجمالي النوبات" value={employee.shifts.length} />
          <div className="w-[1px] h-8 bg-slate-200"></div>
          <HeaderStat icon={<CheckCircle2 className="text-emerald-500" size={16}/>} label="نوبات مكتملة" value={`${completedShiftsCount} / ${employee.shifts.length}`} />
          <div className="w-[1px] h-8 bg-slate-200"></div>
          <HeaderStat icon={<TrendingUp className="text-violet-500" size={16}/>} label="نسبة الأداء" value={`${employee.performanceScore}%`} />
        </div>

        {/* Action Buttons */}
        <div className="flex items-center gap-3">
          <button 
            onClick={showDetailedSummary} 
            disabled={loadingSummary} 
            className="flex items-center gap-3 px-4 py-3 bg-indigo-50 text-indigo-700 rounded-2xl hover:bg-indigo-600 hover:text-white transition-all shadow-sm font-black text-xs"
          >
            {loadingSummary ? <RefreshCcw size={16} className="animate-spin" /> : <ClipboardList size={18} />}
            <span className="hidden xl:inline">ملخص التدقيق</span>
          </button>
          <button 
            onClick={runSmartAudit} 
            disabled={loadingAudit} 
            className="flex items-center gap-3 px-4 py-3 bg-white border border-slate-200 text-slate-600 rounded-2xl hover:bg-indigo-600 hover:text-white transition-all shadow-sm font-black text-xs"
          >
            {loadingAudit ? <RefreshCcw size={16} className="animate-spin" /> : <ShieldCheck size={18} />}
            <span className="hidden xl:inline">تدقيق سريع</span>
          </button>
          <div className={`p-2 rounded-xl bg-slate-50 text-slate-400 group-hover:text-indigo-500 transition-colors ${isExpanded ? 'rotate-180 bg-indigo-50 text-indigo-600' : ''}`}>
             <ChevronDown size={20} />
          </div>
        </div>
      </div>

      {isExpanded && (
        <div className="bg-slate-50/20 p-8 pt-0 border-t border-slate-100 animate-in slide-in-from-top duration-300">

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 mt-8">
            {/* Audit Results Section */}
            <div className="lg:col-span-1 space-y-6">
              {detailedSummary && (
                <div className="bg-white p-8 rounded-[2.5rem] border border-indigo-100 shadow-xl shadow-indigo-500/5 animate-in zoom-in-95 duration-300">
                  <div className="flex items-center gap-3 mb-6">
                    <div className="p-3 bg-indigo-600 text-white rounded-2xl">
                      <ClipboardList size={22} />
                    </div>
                    <div>
                      <h4 className="font-black text-lg text-slate-900">ملخص التدقيق المفصل</h4>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">تحليل النواقص والتواريخ</p>
                    </div>
                  </div>
                  <div className="text-sm text-slate-600 leading-relaxed whitespace-pre-line font-medium">
                    {detailedSummary}
                  </div>
                </div>
              )}

              {auditResult && (
                <div className={`p-6 rounded-[2rem] border-2 text-sm font-black shadow-lg flex items-center gap-4 animate-in zoom-in-95 duration-200 ${auditResult.includes('اختلاف') ? 'bg-rose-50 text-rose-600 border-rose-100 shadow-rose-200/20' : 'bg-emerald-50 text-emerald-600 border-emerald-100 shadow-emerald-200/20'}`}>
                   <ShieldCheck size={24} className={auditResult.includes('اختلاف') ? 'text-rose-500' : 'text-emerald-500'} />
                   <div>
                      <div className="text-[10px] opacity-70 uppercase tracking-widest mb-1">نتيجة التدقيق السريع</div>
                      <div className="text-base">{auditResult}</div>
                   </div>
                </div>
              )}

              {/* Individual Shift Stats Helper */}
              {!detailedSummary && !auditResult && (
                <div className="bg-indigo-50/30 p-8 rounded-[2.5rem] border border-dashed border-indigo-200 text-center">
                  <Sparkles size={32} className="mx-auto text-indigo-300 mb-4" />
                  <p className="text-xs font-black text-indigo-400 uppercase tracking-widest">استخدم أزرار التدقيق أعلاه لتحليل أعمق للسجلات</p>
                </div>
              )}
            </div>

            {/* Shifts Grid Section */}
            <div className="lg:col-span-2 grid grid-cols-1 md:grid-cols-2 gap-6 h-fit">
              {employee.shifts.map((shift, i) => <ShiftAuditCard key={i} shift={shift} />)}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const HeaderStat = ({ icon, label, value }: any) => (
  <div className="flex items-center gap-3">
    <div className="w-8 h-8 rounded-lg bg-white flex items-center justify-center shadow-sm border border-slate-100">
      {icon}
    </div>
    <div>
       <div className="text-[9px] font-bold text-slate-400 uppercase tracking-tight">{label}</div>
       <div className="text-sm font-black text-slate-800">{value}</div>
    </div>
  </div>
);

const ShiftAuditCard: React.FC<{ shift: ShiftReport }> = ({ shift }) => {
  const groupedPunches = useMemo(() => {
    const groups: { period: string; punches: PunchDetail[] }[] = [];
    shift.punches_details.forEach((p) => {
      const last = groups[groups.length - 1];
      if (last && last.period === p.period) last.punches.push(p);
      else groups.push({ period: p.period, punches: [p] });
    });
    return groups;
  }, [shift.punches_details]);

  const isComplete = shift.status === 'مكتملة';

  return (
    <div className={`p-6 rounded-[2rem] border bg-white shadow-sm flex flex-col group/card hover:shadow-xl transition-all ${isComplete ? 'border-emerald-100 hover:border-emerald-200' : 'border-rose-100 hover:border-rose-200'}`}>
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <div className={`p-2 rounded-xl ${isComplete ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
            <Calendar size={16} />
          </div>
          <span className="text-xs font-black text-slate-700 tracking-wide">{shift.shift_date}</span>
        </div>
        <div className={`px-4 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest border shadow-sm ${isComplete ? 'bg-emerald-500 text-white border-emerald-400' : 'bg-rose-500 text-white border-rose-400'}`}>
          {shift.status}
        </div>
      </div>

      <div className="space-y-4 flex-1">
        {groupedPunches.map((group, idx) => {
          const isEntry = group.period === 'دخول صباحي';
          const isExit = group.period === 'بصمة خروج';
          const isInvalid = group.period === 'غير مصنفة';

          return (
            <div key={idx} className={`flex flex-col gap-1.5 pr-5 relative py-2.5 px-3 rounded-2xl transition-all border border-transparent ${
              isExit ? 'bg-emerald-50/70 border-emerald-100 shadow-sm shadow-emerald-100/30' : 
              isEntry ? 'bg-indigo-50/70 border-indigo-100 shadow-sm shadow-indigo-100/30' : ''
            }`}>
               <div className={`absolute right-0 top-4 w-2.5 h-2.5 rounded-full border-2 border-white ${
                 isInvalid ? 'bg-amber-400 shadow-amber-200 shadow-lg' : 
                 isExit ? 'bg-emerald-500 shadow-emerald-200 shadow-lg' : 
                 isEntry ? 'bg-indigo-500 shadow-indigo-200 shadow-lg' : 'bg-slate-300'
               }`}></div>

               <span className={`flex items-center gap-2 text-[9px] font-black mr-2 ${
                 isExit ? 'text-emerald-700' : 
                 isEntry ? 'text-indigo-700' : 
                 isInvalid ? 'text-amber-700' : 'text-slate-400'
               }`}>
                 {isExit && <LogOut size={12} className="text-emerald-500" />}
                 {isEntry && <LogIn size={12} className="text-indigo-500" />}
                 {group.period}
               </span>

               <div className="flex flex-wrap gap-2">
                 {group.punches.map((p, pIdx) => (
                   <div 
                    key={pIdx} 
                    className={`px-3 py-1.5 rounded-xl text-[10px] font-black border transition-all flex items-center gap-1.5 ${
                      p.is_duplicate 
                        ? 'bg-rose-50 border-rose-300 text-rose-500 line-through ring-1 ring-rose-100 opacity-90' 
                        : isExit 
                          ? 'bg-white border-emerald-200 text-emerald-700 shadow-sm' 
                          : isEntry 
                            ? 'bg-white border-indigo-200 text-indigo-700 shadow-sm' 
                            : 'bg-white border-slate-100 text-slate-600'
                    }`}
                    style={p.is_duplicate ? { 
                      backgroundImage: 'repeating-linear-gradient(45deg, transparent, transparent 4px, rgba(244, 63, 94, 0.05) 4px, rgba(244, 63, 94, 0.05) 8px)' 
                    } : {}}
                  >
                     {p.is_duplicate && <AlertCircle size={10} className="text-rose-400" />}
                     {p.time}
                   </div>
                 ))}
               </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

