import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary, ShiftReport } from "../types";

/**
 * التدقيق الفني الفردي السريع
 */
export const auditEmployeeFullPerformanceAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const complexitySample = employee.shifts
    .filter(s => s.status === 'ناقصة' || s.punches_details.some(p => p.period === 'غير مصنفة'))
    .slice(0, 5); 

  if (complexitySample.length === 0 && employee.completionRate === 100) {
    return "✅ كافة السجلات مطابقة للمعايير التقنية ولا توجد ملاحظات.";
  }

  const shiftData = complexitySample.map(s => ({
    date: s.shift_date,
    status: s.status,
    punches: s.punches_details.map(p => `${p.time}(${p.period}${p.is_duplicate ? '-مكرر' : ''})`)
  }));

  const prompt = `
    دقق سجلات الموظف: ${employee.name}
    البيانات: ${JSON.stringify(shiftData)}
    قارن البيانات أعلاه. هل ترتيب البصمات منطقي؟ 
    الرد يجب أن يكون مختصراً جداً: "مطابق" أو "يوجد خلل في [اسم الفترة]". 
    لا تشرح، فقط أعطِ الحكم التقني.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0.1, maxOutputTokens: 60 }
    });
    return response.text?.trim() || "تعذر التحليل.";
  } catch (error) {
    return "⚠️ خطأ في محرك التدقيق.";
  }
};

/**
 * توليد ملخص تدقيق احترافي يحدد التواريخ والنواقص بدقة (طلب المستخدم الأساسي)
 */
export const generateDetailedAuditSummaryAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // تجميع كافة البيانات التي بها مشاكل لإرسالها للذكاء الاصطناعي
  const faultyData = employee.shifts
    .filter(s => s.status === 'ناقصة' || s.punches_details.some(pd => pd.is_duplicate || pd.period === 'غير مصنفة'))
    .map(s => ({
      date: s.shift_date,
      missing: ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
        .filter(p => !s.punches_details.some(pd => pd.period === p && !pd.is_duplicate)),
      duplicates: s.punches_details.filter(pd => pd.is_duplicate).map(pd => pd.period),
      unclassified: s.punches_details.filter(pd => pd.period === 'غير مصنفة').length
    }));

  if (faultyData.length === 0) {
    return "✨ سجلات الموظف مثالية. جميع نوبات العمل (عدد " + employee.shifts.length + ") مكتملة الأركان ولا يوجد بها أي نقص أو تكرار في البصمات.";
  }

  const prompt = `
    بصفتك مدقق حضور وانصراف خبير، حلل البيانات التالية للموظف "${employee.name}":
    ${JSON.stringify(faultyData)}

    المطلوب صياغة تقرير بصيغة نقاط واضحة:
    1. اذكر التاريخ ثم نوع النقص (مثال: في تاريخ 2023-10-01 يوجد نقص في البصمة الوسطية).
    2. اذكر إذا كان هناك أكثر من بصمة مكررة في نفس التاريخ.
    3. إذا وجد نقص في بصمة المساء أو الخروج، حدد ذلك بالتواريخ.
    4. اختم بنصيحة توجيهية للموظف.

    يجب أن يكون النص باللغة العربية، احترافياً، ومنظماً جداً.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview', // استخدام برو لضمان دقة التقارير المفصلة
      contents: prompt,
      config: { temperature: 0.3 }
    });
    return response.text?.trim() || "لم يتم استخلاص نتائج مفصلة.";
  } catch (error) {
    console.error(error);
    return "⚠️ عذراً، واجه نظام التدقيق مشكلة فنية أثناء توليد الملخص.";
  }
};

/**
 * تقرير النزاهة العام
 */
export const analyzeCompanyTrendsAI = async (employees: EmployeeSummary[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const stats = {
    total: employees.length,
    critical: employees.filter(e => !e.isEligible).length,
    avgPerf: (employees.reduce((s, e) => s + e.performanceScore, 0) / employees.length).toFixed(1)
  };

  const prompt = `أعطِ حكماً نهائياً قصيراً جداً (سطر واحد) عن مستوى نزاهة الالتزام بالبصمة في هذه المؤسسة بناءً على: ${JSON.stringify(stats)}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0.4 }
    });
    return response.text?.trim() || "لا توجد بيانات كافية.";
  } catch (error) {
    return "فشل التحليل.";
  }
};

