    </div>
  </div>
);

const ShiftAuditCard: React.FC<{ shift: ShiftReport }> = ({ shift }) => {
  const groupedPunches = useMemo(() => {
    const groups: { period: string; punches: PunchDetail[] }[] = [];
    shift.punches_details.forEach((p) => {
      const last = groups[groups.length - 1];
      if (last && last.period === p.period) last.punches.push(p);
      else groups.push({ period: p.period, punches: [p] });
    });
    return groups;
  }, [shift.punches_details]);

  const isComplete = shift.status === 'مكتملة';

  return (
    <div className={`p-8 rounded-[3rem] border bg-white flex flex-col group/card hover:-translate-y-1 transition-all duration-500 ${isComplete ? 'shadow-sm border-slate-100' : 'shadow-lg shadow-rose-500/5 border-rose-100'}`}>
      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center gap-4">
          <div className={`p-3 rounded-[1.25rem] shadow-sm ${isComplete ? 'bg-indigo-50 text-indigo-600 border border-indigo-100' : 'bg-rose-50 text-rose-600 border border-rose-100'}`}>
            <Calendar size={18} />
          </div>
          <div>
             <span className="text-sm font-black text-slate-800 block">{shift.shift_date}</span>
             <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">تاريخ الوردية</span>
          </div>
        </div>
        <div className={`px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-[0.1em] border shadow-sm flex items-center gap-2 ${isComplete ? 'bg-emerald-500 text-white border-emerald-400' : 'bg-rose-500 text-white border-rose-400'}`}>
          {isComplete ? <Check size={12} /> : <AlertCircle size={12} />}
          {shift.status}
        </div>
      </div>

      <div className="space-y-5 flex-1">
        {groupedPunches.map((group, idx) => {
          const isEntry = group.period === 'دخول صباحي';
          const isExit = group.period === 'بصمة خروج';
          const isInvalid = group.period === 'غير مصنفة';

          return (
            <div key={idx} className={`flex flex-col gap-2 pr-6 relative py-3 px-4 rounded-[1.5rem] transition-all border border-transparent hover:border-slate-200/50 hover:bg-slate-50/50 ${
              isExit ? 'bg-emerald-50/40' : 
              isEntry ? 'bg-indigo-50/40' : 
              isInvalid ? 'bg-amber-50/40' : 'bg-slate-50/20'
            }`}>
               <div className={`absolute right-0 top-1/2 -translate-y-1/2 w-1.5 h-8 rounded-full ${
                 isInvalid ? 'bg-amber-400 shadow-[0_0_8px_rgba(251,191,36,0.3)]' : 
                 isExit ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.3)]' : 
                 isEntry ? 'bg-indigo-500 shadow-[0_0_8px_rgba(79,70,229,0.3)]' : 'bg-slate-300'
               }`}></div>

               <div className="flex items-center justify-between">
                  <span className={`flex items-center gap-2 text-[10px] font-black uppercase tracking-widest ${
                    isExit ? 'text-emerald-700' : 
                    isEntry ? 'text-indigo-700' : 
                    isInvalid ? 'text-amber-700' : 'text-slate-400'
                  }`}>
                    {isExit && <LogOut size={14} className="text-emerald-500" />}
                    {isEntry && <LogIn size={14} className="text-indigo-500" />}
                    {isInvalid && <CircleDashed size={14} className="text-amber-500" />}
                    {group.period}
                  </span>
                  {!isInvalid && group.punches.some(p => p.is_duplicate) && (
                     <span className="text-[9px] font-bold text-rose-500 bg-rose-50 px-2 py-0.5 rounded-lg border border-rose-100 uppercase tracking-tighter">تكرار محتمل</span>
                  )}
               </div>

               <div className="flex flex-wrap gap-2">
                 {group.punches.map((p, pIdx) => (
                   <div 
                    key={pIdx} 
                    className={`px-4 py-2 rounded-xl text-[11px] font-black border transition-all flex items-center gap-2 group/time ${
                      p.is_duplicate 
                        ? 'bg-rose-50 border-rose-200 text-rose-400 line-through opacity-70' 
                        : isExit 
                          ? 'bg-white border-emerald-200 text-emerald-700 shadow-sm' 
                          : isEntry 
                            ? 'bg-white border-indigo-200 text-indigo-700 shadow-sm' 
                            : 'bg-white border-slate-200 text-slate-600'
                    }`}
                  >
                     {p.is_duplicate ? <AlertTriangle size={10} /> : <Clock size={10} className="opacity-40 group-hover/time:opacity-100 transition-opacity" />}
                     {p.time}
                   </div>
                 ))}
               </div>
            </div>
          );
        })}

        {/* Missing Badge Case */}
        {groupedPunches.length < 5 && (
           <div className="pt-2">
              <div className="flex items-center gap-2 text-rose-400 text-[10px] font-bold px-4">
                 <ShieldAlert size={14} />
                 <span>يوجد فترات زمنية ناقصة في هذه النوبة</span>
              </div>
           </div>
        )}
      </div>
    </div>
  );
};

