import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary, ShiftReport } from "../types";

/**
 * التدقيق التقني السريع (مطابق/غير مطابق)
 */
export const auditEmployeeFullPerformanceAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const complexitySample = employee.shifts
    .filter(s => s.status === 'ناقصة')
    .slice(0, 5); 

  if (complexitySample.length === 0) return "✅ السجل التقني سليم.";

  const prompt = `
    دقق بيانات الموظف: ${employee.name}
    النواقص: ${JSON.stringify(complexitySample.map(s => ({d: s.shift_date, p: s.punches_count})))}
    أجب بكلمتين فقط: "سجل سليم" أو "خلل مزامنة".
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0.1, maxOutputTokens: 20 }
    });
    return response.text?.trim() || "تم التدقيق.";
  } catch (error) {
    return "⚠️ خطأ.";
  }
};

/**
 * ملخص التدقيق المختصر جداً (التاريخ -> النقص)
 */
export const generateDetailedAuditSummaryAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const faultyData = employee.shifts
    .filter(s => s.status === 'ناقصة')
    .map(s => ({
      date: s.shift_date,
      missing: ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
        .filter(p => !s.punches_details.some(pd => pd.period === p && !pd.is_duplicate))
    }));

  if (faultyData.length === 0) return "✨ لا توجد أي نواقص في سجل البصمة.";

  const prompt = `
    أنت مدقق نظام حضور. بناءً على البيانات التالية للموظف "${employee.name}":
    ${JSON.stringify(faultyData)}

    المطلوب رد مختصر جداً على شكل قائمة نقطية فقط:
    - [التاريخ]: نقص [اسم الفترة].
    بدون أي مقدمات أو نصائح أو شروحات. فقط التواريخ والنواقص.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0.1 }
    });
    return response.text?.trim() || "لا توجد ملاحظات.";
  } catch (error) {
    return "⚠️ تعذر توليد الملخص.";
  }
};

/**
 * تحليل نزاهة المؤسسة
 */
export const analyzeCompanyTrendsAI = async (employees: EmployeeSummary[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const stats = { total: employees.length, critical: employees.filter(e => !e.isEligible).length };

  const prompt = `اعط حكماً من 5 كلمات عن انضباط هذه المؤسسة: ${JSON.stringify(stats)}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text?.trim() || "التحليل متاح.";
  } catch (error) {
    return "فشل التحليل.";
  }
};

import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Sparkles, ChevronDown, Check,
  Fingerprint, ShieldCheck, AlertTriangle, Target,
  TrendingUp, RefreshCcw, Clock, ShieldAlert,
  History, Timer, LogOut, LogIn, Activity, FileText,
  CheckCircle2, ClipboardList, Copy, CheckCircle
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { auditEmployeeFullPerformanceAI, analyzeCompanyTrendsAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';

type ViewType = 'dashboard' | 'employees' | 'integrity';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [companyInsight, setCompanyInsight] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setCompanyInsight(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const generateIntegrityReport = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    try {
      const result = await analyzeCompanyTrendsAI(employees);
      setCompanyInsight(result);
      setCurrentView('integrity');
    } catch (e) {
      console.error(e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 font-sans flex flex-col lg:flex-row rtl overflow-hidden selection:bg-indigo-100">
      <aside className={`fixed inset-y-0 right-0 z-50 w-64 bg-[#0a0f1e] text-white transition-all lg:static lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="h-full flex flex-col p-6">
          <div className="flex items-center gap-3 mb-10 group cursor-pointer">
            <div className="p-2.5 bg-indigo-600 rounded-xl shadow-lg shadow-indigo-500/20">
              <ShieldCheck size={24} className="text-white" />
            </div>
            <div>
              <h1 className="font-extrabold text-lg text-white">بصمتي <span className="text-indigo-400">PRO</span></h1>
              <p className="text-[9px] text-slate-500 font-bold uppercase tracking-widest mt-0.5">التدقيق الفائق</p>
            </div>
          </div>
          <nav className="space-y-2 flex-1">
            <SidebarLink icon={<LayoutDashboard size={18}/>} label="لوحة التحكم" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Users size={18}/>} label="سجل الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<FileText size={18}/>} label="تقرير النزاهة" active={currentView === 'integrity'} onClick={() => { setCurrentView('integrity'); setIsSidebarOpen(false); }} />
          </nav>
          <div className="mt-auto pt-6 border-t border-slate-800">
            <label className="flex items-center justify-center gap-2 w-full p-3.5 bg-indigo-600 rounded-xl cursor-pointer hover:bg-indigo-500 transition-all font-black text-xs text-white shadow-xl shadow-indigo-600/10 active:scale-95">
              <FileUp size={18} />
              <span>رفع ملف Excel</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
            </label>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="bg-white border-b border-slate-100 px-6 py-4 flex items-center justify-between shrink-0 z-20">
          <div className="flex items-center gap-4 flex-1">
            <button className="lg:hidden p-2 text-slate-500" onClick={() => setIsSidebarOpen(!isSidebarOpen)}>
              <Menu size={22} />
            </button>
            <div className="relative w-full max-w-md">
              <Search className="absolute right-3.5 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
              <input 
                type="text" 
                placeholder="بحث..." 
                className="w-full bg-slate-50 border border-slate-200 rounded-xl pr-10 pl-4 py-2 text-xs outline-none focus:ring-2 focus:ring-indigo-500/10 transition-all"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
          </div>
          <button 
            onClick={generateIntegrityReport}
            disabled={employees.length === 0 || isAnalyzing}
            className="flex items-center gap-2 px-5 py-2.5 bg-[#0a0f1e] text-white rounded-xl text-[10px] font-black hover:bg-slate-800 transition-all active:scale-95 disabled:opacity-20 shadow-md shadow-slate-900/10"
          >
            {isAnalyzing && currentView === 'integrity' ? <RefreshCcw size={16} className="animate-spin" /> : <ShieldCheck size={16} className="text-indigo-400" />}
            <span className="hidden sm:inline">تحليل النزاهة</span>
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8 space-y-6 bg-[#f8fafc] custom-scrollbar pb-32">
          {currentView === 'dashboard' && (
            <div className="animate-in fade-in duration-500 space-y-8">
              {stats ? (
                <>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <StatBox title="إجمالي الكادر" value={stats.totalEmployees} icon={<Users size={20}/>} color="indigo" />
                    <StatBox title="معدل الانضباط" value={`${stats.completionRate}%`} icon={<Target size={20}/>} color="emerald" />
                    <StatBox title="سجلات البصمة" value={stats.totalPunches.toLocaleString()} icon={<Fingerprint size={20}/>} color="amber" />
                  </div>
                  <div>
                    <SectionTitle icon={<Activity size={18}/>} title="نظرة سريعة" />
                    <EmployeeListSection employees={filteredEmployees.slice(0, 5)} isAnalyzing={isAnalyzing} />
                  </div>
                </>
              ) : <EmptyState />}
            </div>
          )}

          {currentView === 'employees' && (
            <div className="animate-in fade-in duration-500 space-y-6">
              <SectionTitle icon={<Users size={18}/>} title="قاعدة بيانات الموظفين" />
              <EmployeeListSection employees={filteredEmployees} isAnalyzing={isAnalyzing} />
            </div>
          )}

          {currentView === 'integrity' && (
            <div className="animate-in fade-in duration-500 max-w-4xl mx-auto space-y-8">
              <div className="bg-[#0a0f1e] text-white p-10 rounded-[2.5rem] shadow-xl relative overflow-hidden">
                <div className="relative z-10">
                  <h2 className="text-2xl font-black mb-6 flex items-center gap-3"><ShieldCheck className="text-indigo-400" size={28} /> تقرير النزاهة الذكي</h2>
                  <div className="bg-white/5 backdrop-blur-md p-8 rounded-2xl border border-white/10 mb-8 font-medium italic text-indigo-50 leading-relaxed">
                    {isAnalyzing ? "جاري التوليد..." : companyInsight || "اضغط على زر التحليل للبدء."}
                  </div>
                  <div className="grid grid-cols-3 gap-6">
                     <IntegrityMetric label="بصمات مكررة" value={employees.reduce((acc, e) => acc + e.shifts.reduce((sacc, s) => sacc + s.punches_details.filter(p => p.is_duplicate).length, 0), 0)} />
                     <IntegrityMetric label="نواقص" value={employees.filter(e => !e.isEligible).length} />
                     <IntegrityMetric label="ثقة" value={`${(stats?.completionRate || 0)}%`} />
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

