const SidebarLink = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-bold text-xs ${active ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-white/5 hover:text-slate-200'}`}>
    {icon} <span>{label}</span>
  </button>
);

const EmployeeSection: React.FC<{ employee: EmployeeSummary }> = ({ employee }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [auditResult, setAuditResult] = useState<string | null>(null);
  const [detailedSummary, setDetailedSummary] = useState<string | null>(null);
  const [loadingAudit, setLoadingAudit] = useState(false);
  const [loadingSummary, setLoadingSummary] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);

  const runSmartAudit = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoadingAudit(true);
    try {
      const res = await auditEmployeeFullPerformanceAI(employee);
      setAuditResult(res);
    } catch (err) {
      setAuditResult("⚠️ خطأ.");
    } finally {
      setLoadingAudit(false);
    }
  };

  const showDetailedSummary = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoadingSummary(true);
    try {
      const res = await generateDetailedAuditSummaryAI(employee);
      setDetailedSummary(res);
    } catch (err) {
      setDetailedSummary("⚠️ فشل التوليد.");
    } finally {
      setLoadingSummary(false);
    }
  };

  const copyToClipboard = () => {
    if (detailedSummary) {
      navigator.clipboard.writeText(detailedSummary);
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    }
  };

  const completedCount = employee.shifts.filter(s => s.status === 'مكتملة').length;
  const isAllComplete = completedCount === employee.shifts.length;

  return (
    <div className={`bg-white rounded-2xl border transition-all ${isExpanded ? 'shadow-xl border-indigo-100 ring-1 ring-indigo-50' : 'shadow-sm border-slate-200 hover:border-indigo-200'}`}>
      <div className="p-4 md:p-5 flex flex-col lg:flex-row items-center gap-5 cursor-pointer group" onClick={() => setIsExpanded(!isExpanded)}>

        {/* Profile */}
        <div className="flex items-center gap-4 min-w-[260px]">
          <div className="relative">
            <div className={`w-12 h-12 rounded-xl flex items-center justify-center font-black text-xl shadow-md ${isAllComplete ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
              {employee.name.charAt(0)}
            </div>
            <div className="absolute -bottom-1 -right-1 bg-white p-1 rounded-full shadow border border-slate-50">
               {isAllComplete ? <CheckCircle size={12} className="text-emerald-500" /> : <ShieldAlert size={12} className="text-rose-500" />}
            </div>
          </div>
          <div>
            <h3 className="font-bold text-base text-slate-900 group-hover:text-indigo-600 transition-colors tracking-tight truncate max-w-[180px]">{employee.name}</h3>
            <div className="flex items-center gap-2 mt-0.5">
              <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">ID: {employee.id}</span>
              <span className={`px-1.5 py-0.5 rounded text-[8px] font-black uppercase ${employee.isEligible ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                {employee.isEligible ? 'سليم' : 'نواقص'}
              </span>
            </div>
          </div>
        </div>

        {/* Mini Stats */}
        <div className="flex-1 w-full grid grid-cols-4 items-center bg-slate-50/50 rounded-xl py-3 px-4 border border-slate-100 gap-2">
          <StatMini label="بصمة" value={employee.totalPunches} />
          <StatMini label="وردية" value={employee.shifts.length} />
          <StatMini label="مكتمل" value={completedCount} />
          <StatMini label="أداء" value={`${employee.performanceScore}%`} />
        </div>

        {/* Actions */}
        <div className="flex items-center gap-2">
          <button 
            onClick={showDetailedSummary} 
            disabled={loadingSummary} 
            className="flex items-center justify-center w-9 h-9 bg-indigo-50 text-indigo-600 rounded-lg hover:bg-indigo-600 hover:text-white transition-all disabled:opacity-50"
            title="ملخص النواقص"
          >
            {loadingSummary ? <RefreshCcw size={14} className="animate-spin" /> : <ClipboardList size={16} />}
          </button>
          <button 
            onClick={runSmartAudit} 
            disabled={loadingAudit} 
            className="flex items-center justify-center w-9 h-9 bg-white border border-slate-200 text-slate-500 rounded-lg hover:bg-indigo-600 hover:text-white transition-all disabled:opacity-50"
            title="تدقيق تقني"
          >
            {loadingAudit ? <RefreshCcw size={14} className="animate-spin" /> : <ShieldCheck size={16} />}
          </button>
          <div className={`p-1.5 rounded-lg text-slate-400 transition-all ${isExpanded ? 'rotate-180 text-indigo-500 bg-indigo-50' : ''}`}>
             <ChevronDown size={18} />
          </div>
        </div>
      </div>

      {isExpanded && (
        <div className="bg-slate-50/30 p-6 pt-2 border-t border-slate-100 animate-in slide-in-from-top-2 duration-300">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

            {/* Insights Column */}
            <div className="lg:col-span-4 space-y-4">
              {detailedSummary && (
                <div className="bg-white p-5 rounded-2xl border border-indigo-50 shadow-sm relative group/report">
                  <button onClick={copyToClipboard} className="absolute top-4 left-4 p-2 text-slate-300 hover:text-indigo-600 transition-all">
                     {copySuccess ? <Check size={14} className="text-emerald-500" /> : <Copy size={14} />}
                  </button>
                  <div className="flex items-center gap-2 mb-4">
                    <div className="p-2 bg-indigo-600 text-white rounded-lg">
                      <ClipboardList size={16} />
                    </div>
                    <span className="font-black text-xs text-slate-800">ملخص النواقص المكتشفة</span>
                  </div>
                  <div className="text-[11px] text-slate-600 leading-relaxed whitespace-pre-line font-medium bg-slate-50 p-4 rounded-xl border border-slate-100">
                    {detailedSummary}
                  </div>
                </div>
              )}

              {auditResult && (
                <div className={`p-4 rounded-xl border text-[10px] font-black flex items-center gap-3 ${auditResult.includes('خلل') ? 'bg-rose-50 text-rose-600 border-rose-100' : 'bg-emerald-50 text-emerald-600 border-emerald-100'}`}>
                   <ShieldCheck size={16} />
                   <span>الحالة: {auditResult}</span>
                </div>
              )}
            </div>

            {/* Shifts Column */}
            <div className="lg:col-span-8 grid grid-cols-1 md:grid-cols-2 gap-4">
              {employee.shifts.map((shift, i) => <ShiftAuditCard key={i} shift={shift} />)}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const StatMini = ({ label, value }: any) => (
  <div className="text-center">
     <div className="text-[8px] font-bold text-slate-400 uppercase tracking-tighter mb-0.5">{label}</div>
     <div className="text-xs font-black text-slate-800">{value}</div>
  </div>
);

const ShiftAuditCard: React.FC<{ shift: ShiftReport }> = ({ shift }) => {
  const groupedPunches = useMemo(() => {
    const groups: { period: string; punches: PunchDetail[] }[] = [];
    shift.punches_details.forEach((p) => {
      const last = groups[groups.length - 1];
      if (last && last.period === p.period) last.punches.push(p);
      else groups.push({ period: p.period, punches: [p] });
    });
    return groups;
  }, [shift.punches_details]);

  const isComplete = shift.status === 'مكتملة';

  return (
    <div className={`p-4 rounded-2xl border bg-white flex flex-col transition-all ${isComplete ? 'border-slate-100' : 'border-rose-100 bg-rose-50/10'}`}>
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <Calendar size={14} className="text-slate-400" />
          <span className="text-[10px] font-black text-slate-700">{shift.shift_date}</span>
        </div>
        <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase ${isComplete ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
          {shift.status}
        </span>
      </div>

      <div className="space-y-2 flex-1">
        {groupedPunches.map((group, idx) => {
          const isEntry = group.period === 'دخول صباحي';
          const isExit = group.period === 'بصمة خروج';
          const isInvalid = group.period === 'غير مصنفة';

          return (
            <div key={idx} className={`flex flex-col gap-1 pr-3 relative py-1.5 px-2 rounded-lg ${
              isExit ? 'bg-emerald-50/50' : isEntry ? 'bg-indigo-50/50' : 'bg-slate-50/50'
            }`}>
               <div className={`absolute right-0 top-1/2 -translate-y-1/2 w-1 h-4 rounded-full ${
                 isInvalid ? 'bg-amber-400' : isExit ? 'bg-emerald-500' : isEntry ? 'bg-indigo-500' : 'bg-slate-300'
               }`}></div>

               <div className="flex items-center justify-between">
                  <span className={`text-[8px] font-black uppercase tracking-tighter ${
                    isExit ? 'text-emerald-700' : isEntry ? 'text-indigo-700' : 'text-slate-500'
                  }`}>
                    {group.period}
                  </span>
               </div>

               <div className="flex flex-wrap gap-1">
                 {group.punches.map((p, pIdx) => (
                   <span 
                    key={pIdx} 
                    className={`px-1.5 py-0.5 rounded border text-[9px] font-bold ${
                      p.is_duplicate 
                        ? 'bg-rose-50 border-rose-100 text-rose-300 line-through' 
                        : 'bg-white border-slate-100 text-slate-600 shadow-sm'
                    }`}
                  >
                     {p.time}
                   </span>
                 ))}
               </div>
            </div>
          );
        })}
        {shift.status === 'ناقصة' && (
           <div className="flex items-center gap-1 text-rose-400 text-[8px] font-bold px-1 mt-1">
              <ShieldAlert size={10} />
              <span>نوبة ناقصة</span>
           </div>
        )}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Sparkles, ChevronDown, Check,
  Fingerprint, ShieldCheck, AlertTriangle, Target,
  TrendingUp, RefreshCcw, Clock, ShieldAlert,
  History, Timer, LogOut, LogIn, Activity, FileText,
  CheckCircle2, ClipboardList, Copy, CheckCircle
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { auditEmployeeFullPerformanceAI, analyzeCompanyTrendsAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';

type ViewType = 'dashboard' | 'employees' | 'integrity';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [companyInsight, setCompanyInsight] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setCompanyInsight(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const generateIntegrityReport = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    try {
      const result = await analyzeCompanyTrendsAI(employees);
      setCompanyInsight(result);
      setCurrentView('integrity');
    } catch (e) {
      console.error(e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#f1f5f9] text-slate-900 font-sans flex flex-col lg:flex-row rtl overflow-hidden selection:bg-indigo-100">
      <aside className={`fixed inset-y-0 right-0 z-50 w-64 bg-[#0a0f1e] text-white transition-all lg:static lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="h-full flex flex-col p-6">
          <div className="flex items-center gap-3 mb-10 group cursor-pointer">
            <div className="p-2.5 bg-gradient-to-tr from-indigo-600 to-indigo-400 rounded-xl shadow-lg shadow-indigo-500/20">
              <ShieldCheck size={24} className="text-white" />
            </div>
            <div>
              <h1 className="font-extrabold text-lg text-white">بصمتي <span className="text-indigo-400">PRO</span></h1>
              <p className="text-[9px] text-slate-500 font-bold uppercase tracking-widest mt-0.5">التدقيق الفائق</p>
            </div>
          </div>
          <nav className="space-y-2 flex-1">
            <SidebarLink icon={<LayoutDashboard size={18}/>} label="لوحة التحكم" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Users size={18}/>} label="سجل الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<FileText size={18}/>} label="تقرير النزاهة" active={currentView === 'integrity'} onClick={() => { setCurrentView('integrity'); setIsSidebarOpen(false); }} />
          </nav>
          <div className="mt-auto pt-6 border-t border-slate-800">
            <label className="flex items-center justify-center gap-2 w-full p-3.5 bg-indigo-600 rounded-xl cursor-pointer hover:bg-indigo-500 transition-all font-black text-xs text-white shadow-xl shadow-indigo-600/10 active:scale-95">
              <FileUp size={18} />
              <span>رفع ملف Excel</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
            </label>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="bg-white/70 backdrop-blur-lg border-b border-slate-200 px-6 py-4 flex items-center justify-between shrink-0 z-20">
          <div className="flex items-center gap-4 flex-1">
            <button className="lg:hidden p-2 text-slate-500 hover:bg-slate-100 rounded-lg" onClick={() => setIsSidebarOpen(!isSidebarOpen)}>
              <Menu size={22} />
            </button>
            <div className="relative w-full max-w-md">
              <Search className="absolute right-3.5 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
              <input 
                type="text" 
                placeholder="بحث سريع..." 
                className="w-full bg-slate-100/50 border border-slate-200 rounded-xl pr-10 pl-4 py-2 text-xs outline-none focus:ring-4 focus:ring-indigo-500/5 transition-all"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
          </div>
          <button 
            onClick={generateIntegrityReport}
            disabled={employees.length === 0 || isAnalyzing}
            className="flex items-center gap-2 px-5 py-2.5 bg-[#0a0f1e] text-white rounded-xl text-[10px] font-black hover:bg-slate-800 transition-all active:scale-95 disabled:opacity-20 shadow-md"
          >
            {isAnalyzing && currentView === 'integrity' ? <RefreshCcw size={16} className="animate-spin" /> : <ShieldCheck size={16} className="text-indigo-400" />}
            <span className="hidden sm:inline">تحليل النزاهة</span>
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8 space-y-6 bg-slate-50 custom-scrollbar pb-32">
          {currentView === 'dashboard' && (
            <div className="animate-in fade-in duration-500 space-y-8">
              {stats ? (
                <>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <StatBox title="إجمالي الكادر" value={stats.totalEmployees} icon={<Users size={20}/>} color="indigo" />
                    <StatBox title="معدل الانضباط" value={`${stats.completionRate}%`} icon={<Target size={20}/>} color="emerald" />
                    <StatBox title="سجلات البصمة" value={stats.totalPunches.toLocaleString()} icon={<Fingerprint size={20}/>} color="amber" />
                  </div>
                  <div>
                    <SectionTitle icon={<Activity size={18}/>} title="نظرة سريعة" />
                    <EmployeeListSection employees={filteredEmployees.slice(0, 5)} isAnalyzing={isAnalyzing} />
                  </div>
                </>
              ) : <EmptyState />}
            </div>
          )}

          {currentView === 'employees' && (
            <div className="animate-in fade-in duration-500 space-y-6">
              <SectionTitle icon={<Users size={18}/>} title="قاعدة بيانات الموظفين" />
              <EmployeeListSection employees={filteredEmployees} isAnalyzing={isAnalyzing} />
            </div>
          )}

          {currentView === 'integrity' && (
            <div className="animate-in fade-in duration-500 max-w-4xl mx-auto space-y-8">
              <div className="bg-[#0a0f1e] text-white p-10 rounded-[2.5rem] shadow-2xl relative overflow-hidden">
                <div className="relative z-10">
                  <h2 className="text-2xl font-black mb-6 flex items-center gap-3"><ShieldCheck className="text-indigo-400" size={28} /> تقرير النزاهة الذكي</h2>
                  <div className="bg-white/5 backdrop-blur-md p-8 rounded-[1.5rem] border border-white/10 mb-8 font-medium italic text-indigo-50 leading-relaxed shadow-inner">
                    {isAnalyzing ? "جاري التوليد..." : companyInsight || "اضغط على زر التحليل للبدء."}
                  </div>
                  <div className="grid grid-cols-3 gap-6">
                     <IntegrityMetric label="بصمات مكررة" value={employees.reduce((acc, e) => acc + e.shifts.reduce((sacc, s) => sacc + s.punches_details.filter(p => p.is_duplicate).length, 0), 0)} />
                     <IntegrityMetric label="نواقص" value={employees.filter(e => !e.isEligible).length} />
                     <IntegrityMetric label="ثقة" value={`${(stats?.completionRate || 0)}%`} />
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

