  };

  const completedCount = employee.shifts.filter(s => s.status === 'مكتملة').length;
  const isAllComplete = completedCount === employee.shifts.length;

  return (
    <div className={`bg-white rounded-[2rem] transition-all duration-300 overflow-hidden group/main ${isExpanded ? 'shadow-2xl shadow-slate-200 ring-2 ring-indigo-50' : 'shadow-sm border border-slate-100 hover:border-indigo-200 hover:shadow-md'}`}>
