            <div className={`w-14 h-14 rounded-[1.25rem] flex items-center justify-center font-black text-2xl shadow-xl transition-all group-hover/main:rotate-3 ${isAllComplete ? 'bg-gradient-to-br from-emerald-500 to-emerald-600 text-white shadow-emerald-200/50' : 'bg-gradient-to-br from-rose-500 to-rose-600 text-white shadow-rose-200/50'}`}>
              {employee.name.charAt(0)}
            </div>
            <div className="absolute -bottom-1 -right-1 bg-white p-1 rounded-full shadow-lg border border-slate-50">
               {isAllComplete ? <CheckCircle size={14} className="text-emerald-500" /> : <ShieldAlert size={14} className="text-rose-500" />}
            </div>
          </div>
          <div>
            <h3 className="font-extrabold text-base text-slate-900 group-hover:text-indigo-600 transition-colors tracking-tight truncate max-w-[200px]">{employee.name}</h3>
            <div className="flex items-center gap-2 mt-0.5">
              <span className="text-[9px] font-black text-slate-400 bg-slate-50 px-2 py-0.5 rounded-lg border border-slate-100 uppercase tracking-widest">ID: {employee.id}</span>
              <span className={`px-2 py-0.5 rounded-lg text-[8px] font-black uppercase border ${employee.isEligible ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-rose-50 text-rose-600 border-rose-100'}`}>
                {employee.isEligible ? 'منتظم' : 'نواقص'}
              </span>
            </div>
          </div>
        </div>

        {/* Stats Glass Box */}
        <div className="flex-1 w-full grid grid-cols-4 items-center bg-slate-50/70 backdrop-blur-sm rounded-2xl py-3 px-6 border border-slate-100/50 gap-4 shadow-inner group-hover/main:bg-white transition-all">
          <StatMini icon={<Fingerprint size={12} className="text-amber-500"/>} label="بصمة" value={employee.totalPunches} />
          <StatMini icon={<Timer size={12} className="text-indigo-500"/>} label="وردية" value={employee.shifts.length} />
          <StatMini icon={<CheckCircle2 size={12} className="text-emerald-500"/>} label="مكتمل" value={completedCount} />
          <StatMini icon={<TrendingUp size={12} className="text-violet-500"/>} label="أداء" value={`${employee.performanceScore}%`} />
        </div>

        {/* Action Panel */}
        <div className="flex items-center gap-3">
          <div className="flex bg-slate-100/50 p-1 rounded-xl border border-slate-200/50">
             <button 
                onClick={showDetailedSummary} 
                disabled={loadingSummary} 
                className="flex items-center justify-center w-10 h-10 rounded-lg hover:bg-white hover:text-indigo-600 text-slate-500 hover:shadow-sm transition-all disabled:opacity-50"
                title="ملخص النواقص"
              >
                {loadingSummary ? <RefreshCcw size={14} className="animate-spin" /> : <ClipboardList size={18} />}
              </button>
              <button 
                onClick={runSmartAudit} 
                disabled={loadingAudit} 
                className="flex items-center justify-center w-10 h-10 rounded-lg hover:bg-white hover:text-indigo-600 text-slate-500 hover:shadow-sm transition-all disabled:opacity-50"
                title="تدقيق فني"
