                {loadingAudit ? <RefreshCcw size={14} className="animate-spin" /> : <ShieldCheck size={18} />}
              </button>
          </div>
          <div className={`p-2 rounded-xl text-slate-300 transition-all ${isExpanded ? 'rotate-180 text-indigo-500 bg-indigo-50' : ''}`}>
             <ChevronDown size={20} />
