      </div>

      {isExpanded && (
        <div className="bg-slate-50/40 p-6 pt-2 border-t border-slate-100 animate-in slide-in-from-top-2 duration-300">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

            {/* Left AI Column */}
            <div className="lg:col-span-4 space-y-4">
              {detailedSummary && (
                <div className="bg-white p-6 rounded-[1.75rem] border border-indigo-100 shadow-xl shadow-indigo-500/5 relative animate-in zoom-in-95 duration-500">
                  <button onClick={copyToClipboard} className="absolute top-4 left-4 p-2 text-slate-300 hover:text-indigo-600 transition-all bg-slate-50 rounded-xl">
                     {copySuccess ? <Check size={14} className="text-emerald-500" /> : <Copy size={14} />}
                  </button>
                  <div className="flex items-center gap-3 mb-4">
                    <div className="p-2.5 bg-indigo-600 text-white rounded-xl shadow-md">
                      <ClipboardList size={18} />
                    </div>
                    <div>
                       <span className="font-black text-xs text-slate-900 block">ملخص النواقص</span>
                       <span className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">تحليل Gemini AI</span>
                    </div>
                  </div>
                  <div className="text-[11px] text-slate-600 leading-relaxed whitespace-pre-line font-bold bg-slate-50/80 p-5 rounded-2xl border border-slate-100 shadow-inner italic">
                    {detailedSummary}
                  </div>
                </div>
              )}

              {auditResult && (
                <div className={`p-5 rounded-2xl border text-[11px] font-black flex items-center gap-4 shadow-sm animate-in slide-in-from-right-2 ${auditResult.includes('خلل') ? 'bg-rose-50 text-rose-700 border-rose-100' : 'bg-emerald-50 text-emerald-700 border-emerald-100'}`}>
                   <div className={`p-2 rounded-lg ${auditResult.includes('خلل') ? 'bg-rose-500' : 'bg-emerald-500'} text-white`}>
                      <ShieldCheck size={16} />
                   </div>
                   <span>الحالة التقنية: {auditResult}</span>
                </div>
              )}

              {!detailedSummary && !auditResult && (
                 <div className="text-center py-10 opacity-40">
                    <BrainCircuit size={32} className="mx-auto mb-2 text-slate-300" />
                    <p className="text-[9px] font-black uppercase tracking-widest">بانتظار التحليل الذكي</p>
                 </div>
              )}
            </div>

            {/* Right Shifts Grid */}
            <div className="lg:col-span-8 grid grid-cols-1 md:grid-cols-2 gap-4">
              {employee.shifts.map((shift, i) => <ShiftAuditCard key={i} shift={shift} />)}
            </div>
          </div>
        </div>
      )}
