  );
};

const StatMini = ({ icon, label, value }: any) => (
  <div className="text-center group-hover:scale-105 transition-transform">
     <div className="flex items-center justify-center gap-1.5 mb-1 opacity-50">
        {icon}
        <span className="text-[9px] font-bold text-slate-500 uppercase tracking-tighter">{label}</span>
     </div>
     <div className="text-xs font-black text-slate-900">{value}</div>
  </div>
);

const ShiftAuditCard: React.FC<{ shift: ShiftReport }> = ({ shift }) => {
  const groupedPunches = useMemo(() => {
    const groups: { period: string; punches: PunchDetail[] }[] = [];
    shift.punches_details.forEach((p) => {
      const last = groups[groups.length - 1];
      if (last && last.period === p.period) last.punches.push(p);
      else groups.push({ period: p.period, punches: [p] });
    });
    return groups;
  }, [shift.punches_details]);

  const isComplete = shift.status === 'مكتملة';

  return (
    <div className={`p-5 rounded-[1.75rem] border bg-white flex flex-col transition-all hover:shadow-md ${isComplete ? 'border-slate-100' : 'border-rose-100 bg-rose-50/5'}`}>
      <div className="flex items-center justify-between mb-5">
        <div className="flex items-center gap-3">
          <div className={`p-2 rounded-xl shadow-sm ${isComplete ? 'bg-indigo-50 text-indigo-600' : 'bg-rose-50 text-rose-600'}`}>
            <Calendar size={14} />
          </div>
          <div className="flex flex-col">
             <span className="text-[11px] font-black text-slate-800">{shift.shift_date}</span>
             <span className="text-[8px] text-slate-400 font-bold uppercase tracking-widest">تاريخ النوبة</span>
          </div>
        </div>
        <span className={`px-2.5 py-1 rounded-lg text-[9px] font-black uppercase shadow-sm ${isComplete ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
          {shift.status}
        </span>
      </div>

      <div className="space-y-3 flex-1">
        {groupedPunches.map((group, idx) => {
          const isEntry = group.period === 'دخول صباحي';
          const isExit = group.period === 'بصمة خروج';
          const isInvalid = group.period === 'غير مصنفة';

          return (
            <div key={idx} className={`flex flex-col gap-1.5 pr-4 relative py-2 px-3 rounded-2xl transition-all ${
              isExit ? 'bg-emerald-50/40 border border-emerald-100/50' : 
              isEntry ? 'bg-indigo-50/40 border border-indigo-100/50' : 
              'bg-slate-50/70 border border-slate-100'
            }`}>
               <div className={`absolute right-0 top-1/2 -translate-y-1/2 w-1 h-6 rounded-full ${
                 isInvalid ? 'bg-amber-400' : isExit ? 'bg-emerald-500' : isEntry ? 'bg-indigo-500' : 'bg-slate-300'
               }`}></div>

               <div className="flex items-center justify-between">
                  <span className={`text-[9px] font-black uppercase tracking-widest flex items-center gap-2 ${
                    isExit ? 'text-emerald-700' : isEntry ? 'text-indigo-700' : 'text-slate-500'
                  }`}>
                    {isExit && <LogOut size={12}/>}
                    {isEntry && <LogIn size={12}/>}
                    {group.period}
                  </span>
               </div>

               <div className="flex flex-wrap gap-1.5">
                 {group.punches.map((p, pIdx) => (
                   <span 
                    key={pIdx} 
                    className={`px-2 py-1 rounded-lg border text-[10px] font-black flex items-center gap-1.5 transition-all ${
                      p.is_duplicate 
                        ? 'bg-rose-50 border-rose-100 text-rose-300 line-through opacity-60' 
                        : 'bg-white border-slate-100 text-slate-700 shadow-sm hover:shadow-md'
                    }`}
                  >
                     <Clock size={10} className="opacity-40" />
                     {p.time}
                   </span>
                 ))}
               </div>
            </div>
          );
        })}
        {shift.status === 'ناقصة' && (
           <div className="flex items-center gap-2 text-rose-400 text-[9px] font-black px-2 mt-2 py-2 bg-rose-50/50 rounded-xl border border-dashed border-rose-200">
              <ShieldAlert size={12} />
              <span>يوجد خلل في تسلسل البصمة</span>
           </div>
        )}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Sparkles, ChevronDown, Check,
  Fingerprint, ShieldCheck, AlertTriangle, Target,
  TrendingUp, RefreshCcw, Clock, ShieldAlert,
  History, Timer, LogOut, LogIn, Activity, FileText,
  CheckCircle2, ClipboardList, Copy, CheckCircle
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { auditEmployeeFullPerformanceAI, analyzeCompanyTrendsAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';

type ViewType = 'dashboard' | 'employees' | 'integrity';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [companyInsight, setCompanyInsight] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setCompanyInsight(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const generateIntegrityReport = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    try {
      const result = await analyzeCompanyTrendsAI(employees);
      setCompanyInsight(result);
      setCurrentView('integrity');
    } catch (e) {
      console.error(e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 font-sans flex flex-col lg:flex-row rtl overflow-hidden selection:bg-indigo-100">
      {/* Sidebar Navigation */}
      <aside className={`fixed inset-y-0 right-0 z-50 w-64 bg-[#0a0f1e] text-white transition-all duration-300 lg:static lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0 shadow-2xl' : 'translate-x-full'}`}>
        <div className="h-full flex flex-col p-6">
          <div className="flex items-center gap-3 mb-10 group cursor-pointer">
            <div className="p-2.5 bg-gradient-to-tr from-indigo-600 to-violet-500 rounded-[1.25rem] shadow-lg shadow-indigo-500/20 group-hover:rotate-6 transition-transform">
              <ShieldCheck size={24} className="text-white" />
            </div>
            <div>
              <h1 className="font-extrabold text-lg text-white tracking-tight">بصمتي <span className="text-indigo-400">PRO</span></h1>
              <p className="text-[9px] text-slate-500 font-bold uppercase tracking-widest mt-0.5 opacity-60">نظام التدقيق الذكي</p>
            </div>
          </div>
          <nav className="space-y-1.5 flex-1">
            <SidebarLink icon={<LayoutDashboard size={18}/>} label="لوحة التحكم" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Users size={18}/>} label="قائمة الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<FileText size={18}/>} label="تقرير النزاهة" active={currentView === 'integrity'} onClick={() => { setCurrentView('integrity'); setIsSidebarOpen(false); }} />
          </nav>
          <div className="mt-auto pt-6 border-t border-slate-800">
            <label className="flex items-center justify-center gap-3 w-full p-4 bg-indigo-600 rounded-2xl cursor-pointer hover:bg-indigo-500 transition-all font-black text-xs text-white shadow-xl shadow-indigo-600/10 active:scale-95 group">
              <FileUp size={20} className="group-hover:-translate-y-1 transition-transform" />
              <span>رفع ملف الحضور</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
            </label>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="bg-white/80 backdrop-blur-md border-b border-slate-100 px-6 py-4 flex items-center justify-between shrink-0 z-20">
          <div className="flex items-center gap-4 flex-1">
            <button className="lg:hidden p-2 text-slate-500 hover:bg-slate-50 rounded-xl" onClick={() => setIsSidebarOpen(!isSidebarOpen)}>
              <Menu size={22} />
            </button>
            <div className="relative w-full max-w-md">
              <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
              <input 
                type="text" 
                placeholder="ابحث عن موظف بالاسم أو الرقم..." 
                className="w-full bg-slate-50 border border-slate-200 rounded-xl pr-11 pl-4 py-2.5 text-xs outline-none focus:ring-4 focus:ring-indigo-500/5 focus:border-indigo-400 transition-all"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
          </div>
          <button 
            onClick={generateIntegrityReport}
            disabled={employees.length === 0 || isAnalyzing}
            className="flex items-center gap-2.5 px-6 py-2.5 bg-slate-900 text-white rounded-xl text-[10px] font-black hover:bg-indigo-600 transition-all active:scale-95 disabled:opacity-20 shadow-lg shadow-slate-900/10"
          >
            {isAnalyzing && currentView === 'integrity' ? <RefreshCcw size={16} className="animate-spin" /> : <Sparkles size={16} className="text-indigo-400" />}
            <span className="hidden sm:inline">تحليل النزاهة الشامل</span>
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8 space-y-8 bg-[#f8fafc] custom-scrollbar pb-32">
          {currentView === 'dashboard' && (
            <div className="animate-in fade-in duration-700 space-y-8 max-w-6xl mx-auto">
              {stats ? (
                <>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <StatBox title="إجمالي الكادر" value={stats.totalEmployees} icon={<Users size={20}/>} color="indigo" />
                    <StatBox title="معدل الانضباط" value={`${stats.completionRate}%`} icon={<Target size={20}/>} color="emerald" />
                    <StatBox title="سجلات البصمة" value={stats.totalPunches.toLocaleString()} icon={<Fingerprint size={20}/>} color="amber" />
                  </div>
                  <div>
                    <div className="flex items-center justify-between mb-6">
                      <SectionTitle icon={<Activity size={18}/>} title="أحدث عمليات التدقيق" />
                      <button onClick={() => setCurrentView('employees')} className="text-xs font-bold text-indigo-600 hover:underline">عرض الكل</button>
                    </div>
                    <EmployeeListSection employees={filteredEmployees.slice(0, 5)} isAnalyzing={isAnalyzing} />
                  </div>
                </>
              ) : <EmptyState />}
            </div>
          )}

          {currentView === 'employees' && (
            <div className="animate-in fade-in duration-500 space-y-6 max-w-6xl mx-auto">
              <SectionTitle icon={<Users size={18}/>} title="سجل الموظفين والتدقيق التقني" />
              <EmployeeListSection employees={filteredEmployees} isAnalyzing={isAnalyzing} />
            </div>
          )}

          {currentView === 'integrity' && (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 max-w-4xl mx-auto space-y-8">
              <div className="bg-gradient-to-br from-[#0a0f1e] to-slate-900 text-white p-12 rounded-[3rem] shadow-2xl relative overflow-hidden group">
                <div className="absolute -top-24 -right-24 w-64 h-64 bg-indigo-500/10 rounded-full blur-[80px] group-hover:bg-indigo-500/20 transition-all duration-700"></div>
                <div className="relative z-10">
                  <div className="flex items-center gap-5 mb-10">
                     <div className="p-4 bg-indigo-500/10 rounded-[2rem] border border-white/5">
                        <ShieldCheck className="text-indigo-400" size={36} />
                     </div>
                     <div>
                        <h2 className="text-3xl font-black tracking-tight">تحليل نزاهة المؤسسة</h2>
                        <p className="text-slate-500 text-sm font-medium mt-1 uppercase tracking-widest">إصدار التقارير الذكية</p>
                     </div>
                  </div>
                  <div className="bg-white/5 backdrop-blur-xl p-8 rounded-[2rem] border border-white/10 mb-10 font-bold italic text-indigo-100/90 leading-relaxed shadow-inner">
                    {isAnalyzing ? "جاري تدقيق البيانات الكبيرة..." : companyInsight || "يرجى الضغط على زر التحليل في الأعلى للبدء."}
                  </div>
                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
                     <IntegrityMetric label="بصمات مكررة محذوفة" value={employees.reduce((acc, e) => acc + e.shifts.reduce((sacc, s) => sacc + s.punches_details.filter(p => p.is_duplicate).length, 0), 0)} />
                     <IntegrityMetric label="نواقص تتطلب مراجعة" value={employees.filter(e => !e.isEligible).length} />
                     <IntegrityMetric label="مؤشر الثقة العام" value={`${(stats?.completionRate || 0)}%`} />
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

/* --- UI Components --- */

const IntegrityMetric = ({ label, value }: any) => (
  <div className="p-6 bg-white/5 rounded-3xl border border-white/5 text-center hover:bg-white/10 transition-all cursor-default">
     <div className="text-indigo-300 text-[10px] font-black uppercase mb-2 tracking-widest opacity-70">{label}</div>
     <div className="text-2xl font-black text-white">{value}</div>
  </div>
);

const SectionTitle = ({ icon, title }: any) => (
  <h2 className="text-base font-black text-slate-800 flex items-center gap-3">
    <div className="p-2 bg-white text-indigo-600 rounded-xl shadow-sm border border-slate-100">{icon}</div>
    {title}
  </h2>
);

const EmptyState = () => (
  <div className="text-center py-32 bg-white rounded-[3rem] border border-slate-100 shadow-sm overflow-hidden relative group">
    <div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-indigo-500 via-violet-500 to-indigo-600"></div>
    <div className="w-20 h-20 bg-slate-50 rounded-[2rem] flex items-center justify-center mx-auto mb-6 shadow-inner group-hover:scale-110 transition-transform duration-500">
      <Fingerprint size={40} className="text-slate-300 animate-float" />
    </div>
    <h3 className="text-xl font-black text-slate-800 mb-2">نظام بصمتي برو جاهز</h3>
    <p className="text-slate-400 text-xs max-w-xs mx-auto font-bold leading-relaxed">
      يرجى تزويدنا بملف Excel الخاص بسجلات البصمة لنقوم بالتحليل التقني والتدقيق الذكي لكل موظف.
    </p>
  </div>
);

const EmployeeListSection = ({ employees, isAnalyzing }: { employees: EmployeeSummary[], isAnalyzing: boolean }) => (
  <div className="space-y-5 animate-in fade-in duration-700">
    {isAnalyzing ? (
      <div className="flex flex-col items-center py-20 bg-white rounded-[3rem] border border-slate-100 shadow-sm">
        <div className="relative mb-6">
           <RefreshCcw className="animate-spin text-indigo-600" size={40} />
           <div className="absolute inset-0 flex items-center justify-center">
              <div className="w-2 h-2 bg-indigo-600 rounded-full animate-ping"></div>
           </div>
        </div>
        <p className="text-[10px] font-black text-slate-400 tracking-[0.4em] uppercase">جاري المعالجة الذكية</p>
      </div>
    ) : employees.map((emp) => <EmployeeSection key={emp.id} employee={emp} />)}
  </div>
);

const StatBox = ({ title, value, icon, color }: any) => {
  const themes: any = {
    indigo: "from-indigo-600 to-violet-600 shadow-indigo-200 ring-indigo-500/10",
    emerald: "from-emerald-600 to-teal-500 shadow-emerald-200 ring-emerald-500/10",
    amber: "from-amber-500 to-orange-400 shadow-amber-200 ring-amber-500/10"
  };
  return (
    <div className={`bg-gradient-to-br ${themes[color]} p-7 rounded-[2.5rem] text-white shadow-xl relative overflow-hidden group transition-all hover:scale-[1.02] active:scale-95 ring-1 border-white/10`}>
       <div className="absolute -top-12 -right-12 w-32 h-32 bg-white/10 rounded-full blur-2xl group-hover:scale-150 transition-transform duration-700"></div>
       <div className="relative flex justify-between items-center">
          <div>
            <p className="text-[10px] font-black uppercase opacity-70 mb-1 tracking-widest">{title}</p>
            <h4 className="text-3xl font-black tracking-tight">{value}</h4>
          </div>
          <div className="p-4 bg-white/20 backdrop-blur-md rounded-[1.5rem] border border-white/20 shadow-lg group-hover:rotate-6 transition-transform">
            {icon}
          </div>
       </div>
    </div>
  );
};

const SidebarLink = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-3.5 px-6 py-4 rounded-[1.25rem] transition-all font-bold text-sm ${active ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/20 translate-x-1' : 'text-slate-400 hover:bg-white/5 hover:text-slate-200'}`}>
    {icon} <span>{label}</span>
  </button>
);

const EmployeeSection: React.FC<{ employee: EmployeeSummary }> = ({ employee }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [auditResult, setAuditResult] = useState<string | null>(null);
  const [detailedSummary, setDetailedSummary] = useState<string | null>(null);
  const [loadingAudit, setLoadingAudit] = useState(false);
  const [loadingSummary, setLoadingSummary] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);

  const runSmartAudit = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoadingAudit(true);
    try {
      const res = await auditEmployeeFullPerformanceAI(employee);
      setAuditResult(res);
    } catch (err) {
      setAuditResult("⚠️ خطأ.");
    } finally {
      setLoadingAudit(false);
    }
  };

  const showDetailedSummary = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoadingSummary(true);
    try {
      const res = await generateDetailedAuditSummaryAI(employee);
      setDetailedSummary(res);
    } catch (err) {
      setDetailedSummary("⚠️ فشل التوليد.");
    } finally {
      setLoadingSummary(false);
    }
  };

  const copyToClipboard = () => {
    if (detailedSummary) {
      navigator.clipboard.writeText(detailedSummary);
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    }
  };

  const completedCount = employee.shifts.filter(s => s.status === 'مكتملة').length;
  const isAllComplete = completedCount === employee.shifts.length;

  return (
    <div className={`bg-white rounded-[2.5rem] transition-all duration-500 overflow-hidden group/main ${isExpanded ? 'shadow-2xl shadow-slate-200 ring-2 ring-indigo-50 border-transparent' : 'shadow-sm border border-slate-100 hover:border-indigo-100 hover:shadow-lg hover:shadow-slate-200/50'}`}>
      <div className="p-5 md:p-6 flex flex-col lg:flex-row items-center gap-8 cursor-pointer relative" onClick={() => setIsExpanded(!isExpanded)}>

        {/* Modern Accent Border (Visual) */}
        <div className={`absolute right-0 top-0 bottom-0 w-2 transition-all duration-500 ${isAllComplete ? 'bg-emerald-500' : 'bg-rose-500'} ${isExpanded ? 'opacity-100' : 'opacity-0'}`}></div>

        {/* Profile Card Section */}
        <div className="flex items-center gap-5 min-w-[300px]">
          <div className="relative group-hover/main:scale-105 transition-transform">
            <div className={`w-16 h-16 rounded-[1.75rem] flex items-center justify-center font-black text-2xl shadow-2xl transition-all ${isAllComplete ? 'bg-gradient-to-br from-emerald-500 to-emerald-600 text-white shadow-emerald-200/40' : 'bg-gradient-to-br from-rose-500 to-rose-600 text-white shadow-rose-200/40'}`}>
              {employee.name.charAt(0)}
            </div>
            <div className={`absolute -bottom-1 -right-1 bg-white p-1.5 rounded-full shadow-xl border border-slate-50`}>
               {isAllComplete ? <CheckCircle2 size={16} className="text-emerald-500" /> : <ShieldAlert size={16} className="text-rose-500" />}
            </div>
          </div>
          <div className="space-y-1">
            <h3 className="font-extrabold text-lg text-slate-900 group-hover/main:text-indigo-600 transition-colors tracking-tight truncate max-w-[220px] leading-none">{employee.name}</h3>
            <div className="flex items-center gap-2">
              <span className="text-[10px] font-black text-slate-400 bg-slate-100/80 px-2 py-0.5 rounded-lg border border-slate-100/50 uppercase tracking-widest">المعرف: {employee.id}</span>
              <span className={`px-2.5 py-0.5 rounded-lg text-[9px] font-black uppercase tracking-widest border transition-all ${employee.isEligible ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-rose-50 text-rose-600 border-rose-100'}`}>
                {employee.isEligible ? 'سجل مكتمل' : 'نواقص مكتشفة'}
              </span>
            </div>
          </div>
        </div>

        {/* Stats Grid (Horizontal Layout) */}
        <div className="flex-1 w-full grid grid-cols-4 items-center bg-slate-50/60 backdrop-blur-md rounded-[2rem] py-4 px-8 border border-slate-200/30 gap-6 shadow-inner hover:bg-white transition-all">
          <StatMini icon={<Fingerprint size={12} className="text-amber-500"/>} label="بصمات" value={employee.totalPunches} />
          <StatMini icon={<Timer size={12} className="text-indigo-500"/>} label="نوبات" value={employee.shifts.length} />
          <StatMini icon={<CheckCircle size={12} className="text-emerald-500"/>} label="مكتمل" value={completedCount} />
          <StatMini icon={<TrendingUp size={12} className="text-violet-500"/>} label="انضباط" value={`${employee.performanceScore}%`} />
        </div>

        {/* Compact Action Panel */}
        <div className="flex items-center gap-3">
          <div className="flex bg-slate-100/80 p-1.5 rounded-2xl border border-slate-200/50 shadow-sm">
             <button 
                onClick={showDetailedSummary} 
                disabled={loadingSummary} 
                className="flex items-center justify-center w-11 h-11 rounded-xl bg-white hover:bg-indigo-600 hover:text-white text-slate-500 shadow-sm transition-all active:scale-90 disabled:opacity-40"
                title="ملخص النواقص"
              >
                {loadingSummary ? <RefreshCcw size={16} className="animate-spin" /> : <ClipboardList size={20} />}
              </button>
              <button 
                onClick={runSmartAudit} 
                disabled={loadingAudit} 
                className="flex items-center justify-center w-11 h-11 rounded-xl hover:bg-slate-900 hover:text-white text-slate-400 transition-all active:scale-90 disabled:opacity-40"
                title="تدقيق تقني فوري"
              >
                {loadingAudit ? <RefreshCcw size={16} className="animate-spin" /> : <ShieldCheck size={20} />}
              </button>
          </div>
          <div className={`p-2.5 rounded-xl text-slate-300 transition-all duration-500 ${isExpanded ? 'rotate-180 text-indigo-500 bg-indigo-50 shadow-inner' : 'group-hover/main:text-indigo-300'}`}>
             <ChevronDown size={22} />
          </div>
        </div>
      </div>

      {isExpanded && (
        <div className="bg-slate-50/50 p-8 pt-2 border-t border-slate-100 animate-in slide-in-from-top-4 duration-500">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

            {/* AI Analysis Column */}
            <div className="lg:col-span-4 space-y-5">
              {detailedSummary && (
                <div className="bg-white p-8 rounded-[2rem] border border-indigo-100 shadow-xl shadow-indigo-500/5 relative animate-in zoom-in-95 duration-500 group/report">
                  <div className="absolute top-5 left-5 flex gap-2 opacity-0 group-hover/report:opacity-100 transition-opacity">
                     <button onClick={copyToClipboard} className="p-2.5 bg-slate-50 text-slate-400 hover:text-indigo-600 hover:bg-white rounded-xl transition-all shadow-sm border border-slate-100">
                        {copySuccess ? <Check size={16} className="text-emerald-500" /> : <Copy size={16} />}
                     </button>
                  </div>
                  <div className="flex items-center gap-4 mb-6">
                    <div className="p-3 bg-gradient-to-tr from-indigo-600 to-indigo-400 text-white rounded-[1.25rem] shadow-lg shadow-indigo-500/20">
                      <ClipboardList size={20} />
                    </div>
                    <div>
                       <span className="font-black text-sm text-slate-900 block tracking-tight">ملخص النواقص المكتشفة</span>
                       <span className="text-[9px] text-indigo-500 font-bold uppercase tracking-[0.2em] mt-0.5">مدعوم بـ Gemini AI</span>
                    </div>
                  </div>
                  <div className="text-[12px] text-slate-700 leading-relaxed whitespace-pre-line font-bold bg-[#fbfdff] p-6 rounded-[1.5rem] border border-indigo-50/50 shadow-inner italic">
                    {detailedSummary}
                  </div>
                </div>
              )}

              {auditResult && (
                <div className={`p-6 rounded-[1.75rem] border text-[11px] font-black flex items-center gap-5 shadow-lg shadow-slate-200/20 animate-in slide-in-from-right-4 ${auditResult.includes('خلل') ? 'bg-rose-50 text-rose-700 border-rose-100' : 'bg-emerald-50 text-emerald-700 border-emerald-100'}`}>
                   <div className={`p-2.5 rounded-xl ${auditResult.includes('خلل') ? 'bg-rose-500 shadow-rose-200' : 'bg-emerald-500 shadow-emerald-200'} text-white shadow-lg`}>
                      <ShieldCheck size={20} />
                   </div>
                   <div className="flex flex-col gap-0.5">
                      <span className="opacity-60 uppercase tracking-widest text-[9px]">حالة الربط التقني</span>
                      <span className="text-sm">{auditResult}</span>
                   </div>
                </div>
              )}

              {!detailedSummary && !auditResult && (
                 <div className="text-center py-16 opacity-30 bg-white/40 rounded-[2.5rem] border border-dashed border-slate-200">
                    <BrainCircuit size={40} className="mx-auto mb-3 text-slate-300" />
                    <p className="text-[10px] font-black uppercase tracking-[0.3em]">بانتظار التحليل الذكي للبيانات</p>
                 </div>
              )}
            </div>

            {/* Attendance Timeline Column */}
            <div className="lg:col-span-8 space-y-4">
              <div className="flex items-center gap-3 px-4 mb-2">
                 <History size={16} className="text-slate-400" />
                 <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em]">الجدول الزمني للوردية</span>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                {employee.shifts.map((shift, i) => <ShiftAuditCard key={i} shift={shift} />)}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const StatMini = ({ icon, label, value }: any) => (
  <div className="text-center group transition-transform duration-300">
     <div className="flex items-center justify-center gap-2 mb-1.5 opacity-50 group-hover:opacity-100 transition-opacity">
        {icon}
        <span className="text-[10px] font-bold text-slate-500 uppercase tracking-tighter">{label}</span>
     </div>
     <div className="text-sm font-black text-slate-900 group-hover:text-indigo-600 transition-colors">{value}</div>
  </div>
);

const ShiftAuditCard: React.FC<{ shift: ShiftReport }> = ({ shift }) => {
  const groupedPunches = useMemo(() => {
    const groups: { period: string; punches: PunchDetail[] }[] = [];
    shift.punches_details.forEach((p) => {
      const last = groups[groups.length - 1];
      if (last && last.period === p.period) last.punches.push(p);
      else groups.push({ period: p.period, punches: [p] });
    });
    return groups;
  }, [shift.punches_details]);

  const isComplete = shift.status === 'مكتملة';

  return (
    <div className={`p-6 rounded-[2.25rem] border bg-white flex flex-col transition-all duration-300 hover:shadow-xl hover:-translate-y-1 ${isComplete ? 'border-slate-100 shadow-sm' : 'border-rose-100 bg-rose-50/5 shadow-md shadow-rose-500/5'}`}>
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <div className={`p-2.5 rounded-2xl shadow-sm ${isComplete ? 'bg-indigo-50 text-indigo-600' : 'bg-rose-50 text-rose-600'}`}>
            <Calendar size={16} />
          </div>
          <div className="flex flex-col">
             <span className="text-[13px] font-black text-slate-800 tracking-tight">{shift.shift_date}</span>
             <span className="text-[9px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">تاريخ الوردية</span>
          </div>
        </div>
        <span className={`px-3 py-1.5 rounded-[1rem] text-[10px] font-black uppercase shadow-lg transition-colors ${isComplete ? 'bg-emerald-500 text-white shadow-emerald-200/50' : 'bg-rose-500 text-white shadow-rose-200/50'}`}>
          {shift.status}
        </span>
      </div>

      <div className="space-y-4 flex-1">
        {groupedPunches.map((group, idx) => {
          const isEntry = group.period === 'دخول صباحي';
          const isExit = group.period === 'بصمة خروج';
          const isInvalid = group.period === 'غير مصنفة';

          return (
            <div key={idx} className={`flex flex-col gap-2 pr-5 relative py-3 px-4 rounded-[1.5rem] transition-all border ${
              isExit ? 'bg-emerald-50/40 border-emerald-100/40' : 
              isEntry ? 'bg-indigo-50/40 border-indigo-100/40' : 
              'bg-slate-50/80 border-slate-100'
            }`}>
               <div className={`absolute right-0 top-1/2 -translate-y-1/2 w-1.5 h-7 rounded-full ${
                 isInvalid ? 'bg-amber-400 shadow-[0_0_8px_rgba(251,191,36,0.4)]' : 
                 isExit ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.4)]' : 
                 isEntry ? 'bg-indigo-500 shadow-[0_0_8px_rgba(79,70,229,0.4)]' : 'bg-slate-300'
               }`}></div>

               <div className="flex items-center justify-between">
                  <span className={`text-[10px] font-black uppercase tracking-widest flex items-center gap-2.5 ${
                    isExit ? 'text-emerald-700' : isEntry ? 'text-indigo-700' : 'text-slate-500'
                  }`}>
                    {isExit && <LogOut size={14} className="opacity-70" />}
                    {isEntry && <LogIn size={14} className="opacity-70" />}
                    {group.period}
                  </span>
               </div>

               <div className="flex flex-wrap gap-2">
                 {group.punches.map((p, pIdx) => (
                   <span 
                    key={pIdx} 
                    className={`px-3 py-1.5 rounded-xl border text-[11px] font-black flex items-center gap-2 transition-all group/punch ${
                      p.is_duplicate 
                        ? 'bg-rose-50 border-rose-100 text-rose-300 line-through opacity-60' 
                        : 'bg-white border-slate-100 text-slate-700 shadow-sm hover:shadow-md'
                    }`}
                  >
                     <Clock size={12} className="opacity-30 group-hover/punch:opacity-80 transition-opacity" />
                     {p.time}
                   </span>
                 ))}
               </div>
            </div>
          );
        })}
        {!isComplete && (
           <div className="flex items-center gap-3 text-rose-400 text-[10px] font-black px-4 py-3 bg-rose-50/50 rounded-2xl border border-dashed border-rose-200">
              <ShieldAlert size={16} />
              <span className="tracking-tight">تم اكتشاف خلل في تسلسل البصمة لهذه النوبة</span>
           </div>
        )}
      </div>
    </div>
  );
};

