import { ATTENDANCE_RULES } from '../constants';
import { ShiftReport, PunchDetail, EmployeeSummary } from '../types';

const getTimeInMinutes = (date: Date) => date.getHours() * 60 + date.getMinutes();

const getRuleMinutes = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h * 60 + m;
};

export const classifyPunch = (
  punchDate: Date,
  isFirst: boolean,
  isLast: boolean,
  shiftStartDate: Date
): string | null => {
  const t = getTimeInMinutes(punchDate);
  const periods = ATTENDANCE_RULES.TIME_PERIODS;
  const isNextDay = punchDate.getDate() !== shiftStartDate.getDate();

  const exitStart = getRuleMinutes(periods["بصمة خروج"].start);
  const exitEnd = getRuleMinutes(periods["بصمة خروج"].end);
  if (isLast && (isNextDay || t >= exitStart) && t <= exitEnd) return "بصمة خروج";

  const mornStart = getRuleMinutes(periods["دخول صباحي"].start);
  const mornEnd = getRuleMinutes(periods["دخول صباحي"].end);
  if (isFirst && !isNextDay && t >= mornStart && t <= mornEnd) return "دخول صباحي";

  const nightStart = getRuleMinutes(periods["بصمة ليلية"].start);
  const nightEnd = getRuleMinutes(periods["بصمة ليلية"].end);
  if (t >= nightStart || t <= nightEnd) {
    if (t > mornEnd || t < 240) return "بصمة ليلية";
  }

  const midStart = getRuleMinutes(periods["بصمة وسطية"].start);
  const midEnd = getRuleMinutes(periods["بصمة وسطية"].end);
  if (t >= midStart && t <= midEnd) return "بصمة وسطية";

  const eveStart = getRuleMinutes(periods["بصمة مسائية"].start);
  const eveEnd = getRuleMinutes(periods["بصمة مسائية"].end);
  if (t >= eveStart && t <= eveEnd) return "بصمة مسائية";

  return null;
};

export const processExcelData = (rawData: any[]): EmployeeSummary[] => {
  if (!rawData || rawData.length === 0) return [];
  const employeesMap: Map<string, { name: string, punches: Date[] }> = new Map();

  rawData.forEach(row => {
    const id = String(row['AC-No'] || row[1] || '0');
    if (id === '0' || id === 'undefined' || id === 'No') return;
    const name = row['Name'] || row[2] || 'موظف غير معروف';
    const dateVal = row['Date'] || row[3];
    const timePart = String(row['Time'] || row[4] || "");
    if (!timePart || !timePart.trim()) return;

    let dt: Date;
    if (typeof dateVal === 'number') dt = new Date((dateVal - 25569) * 86400 * 1000);
    else dt = new Date(dateVal);

    const times = timePart.split(/\s+/).filter(t => t.includes(':'));
    if (!employeesMap.has(id)) employeesMap.set(id, { name, punches: [] });

    times.forEach(tStr => {
      const d = new Date(dt);
      const parts = tStr.split(':').map(Number);
      if (parts.length >= 2) {
        d.setHours(parts[0] || 0, parts[1] || 0, 0, 0);
        employeesMap.get(id)?.punches.push(d);
      }
    });
  });

  const allSummaries: EmployeeSummary[] = [];
  employeesMap.forEach((data, id) => {
    const sortedPunches = data.punches.sort((a, b) => a.getTime() - b.getTime());
    const shiftsData: Date[][] = [];
    if (sortedPunches.length > 0) {
      let currentShift: Date[] = [sortedPunches[0]];
      for (let i = 1; i < sortedPunches.length; i++) {
        const diffHours = (sortedPunches[i].getTime() - sortedPunches[i-1].getTime()) / (1000 * 3600);
        if (diffHours > ATTENDANCE_RULES.MAX_HOURS_BETWEEN_PUNCHES) {
          shiftsData.push(currentShift);
          currentShift = [];
        }
        currentShift.push(sortedPunches[i]);
      }
      if (currentShift.length > 0) shiftsData.push(currentShift);
    }

    const shiftsReports: ShiftReport[] = shiftsData.map(punchDates => {
      const shiftStart = punchDates[0];
      const details: PunchDetail[] = [];
      const seenTimes = new Set<string>();
      const processedPeriods = new Set<string>();

      punchDates.forEach((p, idx) => {
        const timeStr = p.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
        const periodType = classifyPunch(p, idx === 0, idx === punchDates.length - 1, shiftStart) || "غير مصنفة";

        // كشف المكرر بناءً على الوقت المتطابق أو الفترة المسجلة مسبقاً
        const isDuplicateTime = seenTimes.has(timeStr);
        const isDuplicatePeriod = processedPeriods.has(periodType) && periodType !== "غير مصنفة" && periodType !== "بصمة خروج";

        const isDuplicate = isDuplicateTime || isDuplicatePeriod;

        details.push({
          time: timeStr,
          period: periodType,
          is_duplicate: isDuplicate,
          raw_datetime: p
        });

        if (!isDuplicate) {
          seenTimes.add(timeStr);
          if (periodType !== "غير مصنفة") processedPeriods.add(periodType);
        }
      });

      const uniqueValidPeriods = new Set(details.filter(d => !d.is_duplicate && d.period !== "غير مصنفة").map(d => d.period));
      return {
        employee_id: id,
        employee_name: data.name,
        shift_date: shiftStart.toLocaleDateString('en-CA'),
        punches_details: details,
        punches_count: uniqueValidPeriods.size,
        status: uniqueValidPeriods.size >= ATTENDANCE_RULES.REQUIRED_PUNCHES_PER_SHIFT ? 'مكتملة' : 'ناقصة'
      };
    });

    const activeShifts = shiftsReports.filter(s => s.punches_count > 0);
    if (activeShifts.length === 0) return;

    allSummaries.push({
      id,
      name: data.name,
      shifts: activeShifts,
      totalPunches: activeShifts.reduce((sum, s) => sum + s.punches_count, 0),
      completionRate: Math.round((activeShifts.filter(s => s.status === 'مكتملة').length / activeShifts.length) * 100),
      performanceScore: Math.round((activeShifts.reduce((sum, s) => sum + s.punches_count, 0) / (activeShifts.length * 5)) * 100),
      isEligible: activeShifts.every(s => s.status === 'مكتملة')
    });
  });

  return allSummaries.sort((a, b) => parseInt(String(a.id)) - parseInt(String(b.id)));
};

import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary } from "../types";

export const auditEmployeeFullPerformanceAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const sample = employee.shifts.filter(s => s.status === 'ناقصة').slice(0, 5); 
  if (sample.length === 0) return "✅ السجل سليم.";

  const prompt = `دقق موظف ${employee.id}. نواقص: ${JSON.stringify(sample.map(s => ({d: s.shift_date, p: s.punches_count})))}. رد بكلمتين: "سجل سليم" أو "خلل نظام".`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0, maxOutputTokens: 10 }
    });
    return response.text?.trim() || "تم التدقيق.";
  } catch (error) {
    return "⚠️ خطأ.";
  }
};

export const generateDetailedAuditSummaryAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const faulty = employee.shifts
    .filter(s => s.status === 'ناقصة')
    .map(s => ({
      d: s.shift_date,
      m: ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
        .filter(p => !s.punches_details.some(pd => pd.period === p && !pd.is_duplicate))
    }));

  if (faulty.length === 0) return "✨ لا توجد نواقص.";

  // برومبت مختصر جداً لزيادة السرعة
  const prompt = `قائمة النواقص لموظف ${employee.name}: ${JSON.stringify(faulty)}. 
أجب بصيغة:
- التاريخ: نقص [الفترة].
بدون أي كلام آخر.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0, maxOutputTokens: 200 }
    });
    return response.text?.trim() || "لا توجد ملاحظات.";
  } catch (error) {
    return "⚠️ تعذر التوليد حالياً.";
  }
};

export const analyzeCompanyTrendsAI = async (employees: EmployeeSummary[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const stats = { t: employees.length, c: employees.filter(e => !e.isEligible).length };
  const prompt = `حكم من 5 كلمات عن انضباط: ${JSON.stringify(stats)}`;
  try {
    const response = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt });
    return response.text?.trim() || "التحليل جاهز.";
  } catch (error) {
    return "فشل التحليل.";
  }
};

