                  </div>
                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
                     <IntegrityMetric label="مكررات محذوفة" value={employees.reduce((acc, e) => acc + e.shifts.reduce((sacc, s) => sacc + s.punches_details.filter(p => p.is_duplicate).length, 0), 0)} />
